import { useEffect, useState } from 'react';
import {
  DndContext,
  DragOverlay,
  closestCorners,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
  DragStartEvent,
  DragOverEvent,
  DragEndEvent,
} from '@dnd-kit/core';
import { arrayMove, sortableKeyboardCoordinates } from '@dnd-kit/sortable';
import TaskColumn from './TaskColumn';
import TaskCard from './TaskCard';
import { useTaskStore } from '../../store/taskStore';
import { useAuthStore } from '../../store/authStore';
import { Trash2, CheckCircle2 } from 'lucide-react';

const COLUMNS = ['todo', 'in-progress', 'review', 'done'];

export default function TaskBoard({ onTaskClick }: { onTaskClick?: (task: any) => void }) {
  const { tasks, fetchTasks, loading, reorderTask, bulkUpdate, bulkDelete } = useTaskStore();
  
  const [selectedTaskIds, setSelectedTaskIds] = useState<string[]>([]);
  
  // We maintain a local copy of tasks for smooth drag and drop
  // We'll sync this with the global store when dragging ends
  const [localTasks, setLocalTasks] = useState([]);
  const [activeTask, setActiveTask] = useState(null);

  // Sync local tasks when global tasks change
  useEffect(() => {
    setLocalTasks(tasks);
  }, [tasks]);

  useEffect(() => {
    // Assuming workspaceId is 'default' for now
    fetchTasks('default');
  }, [fetchTasks]);

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 5 } }),
    useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates })
  );

  const handleToggleSelect = (id: string) => {
    setSelectedTaskIds(prev => 
      prev.includes(id) ? prev.filter(tId => tId !== id) : [...prev, id]
    );
  };

  const handleBulkDelete = () => {
    if (confirm(`Delete ${selectedTaskIds.length} tasks?`)) {
      bulkDelete(selectedTaskIds, '000000000000000000000000');
      setSelectedTaskIds([]);
    }
  };

  const handleBulkComplete = () => {
    bulkUpdate(selectedTaskIds, { status: 'done' }, '000000000000000000000000');
    setSelectedTaskIds([]);
  };

  const handleDragStart = (event: DragStartEvent) => {
    const { active } = event;
    const task = localTasks.find((t) => t._id === active.id);
    if (task) setActiveTask(task);
  };

  const handleDragOver = (event: DragOverEvent) => {
    const { active, over } = event;
    if (!over) return;

    const activeId = active.id;
    const overId = over.id;

    if (activeId === overId) return;

    const isActiveTask = active.data.current?.type === 'Task';
    const isOverTask = over.data.current?.type === 'Task';
    const isOverColumn = over.data.current?.type === 'Column';

    if (!isActiveTask) return;

    // Dropping a Task over another Task
    if (isActiveTask && isOverTask) {
      setLocalTasks((tasks) => {
        const activeIndex = tasks.findIndex((t) => t._id === activeId);
        const overIndex = tasks.findIndex((t) => t._id === overId);

        if (tasks[activeIndex].status !== tasks[overIndex].status) {
          // Moving between columns
          const updatedTasks = [...tasks];
          updatedTasks[activeIndex].status = tasks[overIndex].status;
          return arrayMove(updatedTasks, activeIndex, overIndex);
        }

        // Reordering in same column
        return arrayMove(tasks, activeIndex, overIndex);
      });
    }

    // Dropping a Task over an empty column area
    if (isActiveTask && isOverColumn) {
      setLocalTasks((tasks) => {
        const activeIndex = tasks.findIndex((t) => t._id === activeId);
        const updatedTasks = [...tasks];
        updatedTasks[activeIndex].status = overId as string;
        return arrayMove(updatedTasks, activeIndex, activeIndex);
      });
    }
  };

  const handleDragEnd = (event: DragEndEvent) => {
    setActiveTask(null);
    const { active, over } = event;
    if (!over) return;

    const activeTask = localTasks.find(t => t._id === active.id);
    if (!activeTask) return;
    
    const newIndex = localTasks.findIndex(t => t._id === active.id);
    const orderScore = newIndex * 1000; // simple ordering logic for now
    
    // Call API to save new position
    reorderTask(active.id as string, activeTask.status, orderScore).then(() => {
      // Refresh to ensure we have the correct server state
      fetchTasks('default');
    });
  };

  if (loading && localTasks.length === 0) {
    return <div className="p-8 text-center text-gray-500">Loading tasks...</div>;
  }

  return (
    <div className="flex gap-6 overflow-x-auto pb-4 pt-2 h-full">
      <DndContext
        sensors={sensors}
        collisionDetection={closestCorners}
        onDragStart={handleDragStart}
        onDragOver={handleDragOver}
        onDragEnd={handleDragEnd}
      >
        {COLUMNS.map((colId) => (
          <TaskColumn
            key={colId}
            id={colId}
            title={colId}
            tasks={localTasks.filter((t) => t.status === colId)}
            selectedTaskIds={selectedTaskIds}
            onToggleSelect={handleToggleSelect}
            onTaskClick={onTaskClick}
          />
        ))}

        <DragOverlay>
          {activeTask ? <TaskCard task={activeTask} /> : null}
        </DragOverlay>
      </DndContext>

      {/* Bulk Actions Bar */}
      {selectedTaskIds.length > 0 && (
        <div className="fixed bottom-6 left-1/2 -translate-x-1/2 z-50 flex items-center gap-4 rounded-2xl border border-border bg-[color:var(--color-surface)] px-6 py-3 shadow-float">
          <span className="text-sm font-semibold text-[color:var(--color-foreground)]">
            {selectedTaskIds.length} selected
          </span>
          <div className="h-6 w-px bg-border" />
          <button onClick={handleBulkComplete} className="flex items-center gap-2 rounded-lg px-3 py-1.5 text-sm font-medium text-emerald-600 hover:bg-emerald-50 transition-colors">
            <CheckCircle2 size={16} /> Mark Done
          </button>
          <button onClick={handleBulkDelete} className="flex items-center gap-2 rounded-lg px-3 py-1.5 text-sm font-medium text-red-600 hover:bg-red-50 transition-colors">
            <Trash2 size={16} /> Delete
          </button>
        </div>
      )}
    </div>
  );
}

import { useSortable } from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { Clock, GripVertical } from 'lucide-react';
import clsx from 'clsx';

interface Task {
  _id: string;
  title: string;
  priority: 'low' | 'medium' | 'high' | 'urgent';
  status: string;
  dependencies?: any[];
  parentTaskId?: any;
}

interface TaskCardProps {
  task: Task;
  isSelected?: boolean;
  onToggleSelect?: (id: string) => void;
  onClick?: () => void;
}

const priorityColors = {
  low: 'bg-slate-100 text-slate-700',
  medium: 'bg-sky-100 text-sky-700',
  high: 'bg-amber-100 text-amber-700',
  urgent: 'bg-rose-100 text-rose-700',
};

export default function TaskCard({ task, isSelected, onToggleSelect, onClick }: TaskCardProps) {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({ id: task._id, data: { type: 'Task', task } });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
  };

  return (
    <div
      ref={setNodeRef}
      style={style}
      className={clsx(
        'group relative cursor-grab rounded-xl border bg-[color:var(--color-surface)] p-3 shadow-sm transition-all active:cursor-grabbing',
        isDragging ? 'z-50 scale-[1.01] border-[color:var(--color-accent)]/30 shadow-float' : 'border-border hover:shadow-soft',
        isSelected ? 'ring-2 ring-[color:var(--color-accent)]' : ''
      )}
      onClick={onClick}
      {...attributes}
      {...listeners}
    >
      <div className="absolute right-2 top-2 flex gap-2 text-[color:var(--color-muted)] opacity-0 transition-opacity group-hover:opacity-100">
        {onToggleSelect && (
          <input 
            type="checkbox" 
            className="cursor-pointer" 
            checked={isSelected}
            onChange={() => onToggleSelect(task._id)}
            onPointerDown={(e) => e.stopPropagation()} 
          />
        )}
        <GripVertical size={14} />
      </div>

      <h3 className="pr-12 text-sm font-medium text-[color:var(--color-foreground)]">{task.title}</h3>

      <div className="mt-3 flex items-center justify-between">
        <span className={clsx('rounded-full px-2 py-1 text-[11px] font-semibold', priorityColors[task.priority])}>
          {task.priority.charAt(0).toUpperCase() + task.priority.slice(1)}
        </span>

        <div className="flex items-center gap-2 text-[11px] text-[color:var(--color-muted)]">
          {task.dependencies && task.dependencies.length > 0 && (
            <div className="flex items-center gap-1" title="Has dependencies">
              <span className="text-[10px] font-bold text-amber-500">ΓÜá Dep</span>
            </div>
          )}
          <div className="flex items-center gap-1">
            <Clock size={12} />
            <span>Today</span>
          </div>
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { useAuthStore } from '../../store/authStore';
import { useRealtime } from '../../providers/RealtimeProvider';
import { Send } from 'lucide-react';
import api from '../../utils/api';
import toast from 'react-hot-toast';
import { format } from 'date-fns';

interface Comment {
  _id: string;
  content: string;
  userId: { _id: string; name: string; avatarUrl: string };
  createdAt: string;
}

export default function TaskComments({ taskId }: { taskId: string }) {
  const { user } = useAuthStore();
  const { socket } = useRealtime();
  const [comments, setComments] = useState<Comment[]>([]);
  const [newComment, setNewComment] = useState('');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchComments = async () => {
      try {
        const { data } = await api.get(`/tasks/${taskId}/comments`);
        setComments(data);
      } catch (error) {
        toast.error('Failed to load comments');
      } finally {
        setLoading(false);
      }
    };
    
    fetchComments();

    if (socket) {
      socket.on('comment_added', (comment: Comment) => {
        setComments(prev => [comment, ...prev]);
      });

      socket.on('comment_deleted', ({ commentId }) => {
        setComments(prev => prev.filter(c => c._id !== commentId));
      });
    }

    return () => {
      if (socket) {
        socket.off('comment_added');
        socket.off('comment_deleted');
      }
    };
  }, [taskId, socket]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newComment.trim()) return;

    try {
      await api.post(`/tasks/${taskId}/comments`, { content: newComment });
      setNewComment('');
    } catch (error) {
      toast.error('Failed to post comment');
    }
  };

  const handleDelete = async (commentId: string) => {
    try {
      await api.delete(`/comments/${commentId}`);
    } catch (error) {
      toast.error('Failed to delete comment');
    }
  };

  return (
    <div className="flex h-full flex-col">
      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {loading ? (
          <div className="text-center text-sm text-[color:var(--color-muted)]">Loading comments...</div>
        ) : comments.length === 0 ? (
          <div className="text-center text-sm text-[color:var(--color-muted)]">No comments yet.</div>
        ) : (
          comments.map(comment => (
            <div key={comment._id} className="flex gap-3">
              <div className="h-8 w-8 overflow-hidden rounded-full bg-[color:var(--color-surface-hover)]">
                {comment.userId.avatarUrl ? (
                  <img src={comment.userId.avatarUrl} alt={comment.userId.name} className="h-full w-full object-cover" />
                ) : (
                  <div className="flex h-full w-full items-center justify-center font-semibold text-[color:var(--color-muted)]">
                    {comment.userId.name.charAt(0)}
                  </div>
                )}
              </div>
              <div className="flex-1 rounded-xl bg-[color:var(--color-surface)] border border-border p-3">
                <div className="flex items-center justify-between mb-1">
                  <span className="text-xs font-semibold text-[color:var(--color-foreground)]">{comment.userId.name}</span>
                  <span className="text-[10px] text-[color:var(--color-muted)]">
                    {format(new Date(comment.createdAt), 'MMM d, h:mm a')}
                  </span>
                </div>
                <p className="text-sm text-[color:var(--color-foreground)]">{comment.content}</p>
                {user?.id === comment.userId._id && (
                  <button 
                    onClick={() => handleDelete(comment._id)}
                    className="mt-2 text-[10px] text-red-500 hover:underline"
                  >
                    Delete
                  </button>
                )}
              </div>
            </div>
          ))
        )}
      </div>

      <form onSubmit={handleSubmit} className="border-t border-border p-4 bg-[color:var(--color-surface)]">
        <div className="relative">
          <input
            type="text"
            value={newComment}
            onChange={(e) => setNewComment(e.target.value)}
            placeholder="Write a comment..."
            className="w-full rounded-xl border border-border bg-[color:var(--color-surface-hover)] py-2 pl-4 pr-10 text-sm focus:border-[color:var(--color-accent)] focus:outline-none"
          />
          <button
            type="submit"
            disabled={!newComment.trim()}
            className="absolute right-2 top-1/2 -translate-y-1/2 rounded p-1 text-[color:var(--color-muted)] hover:text-[color:var(--color-accent)] disabled:opacity-50"
          >
            <Send size={16} />
          </button>
        </div>
      </form>
    </div>
  );
}

