import React, { useState } from 'react';
import { X, Calendar, Check } from 'lucide-react';
import { Dialog, DialogPanel, DialogTitle, DialogDescription } from '../ui/Dialog';
import { Button } from '../ui/Button';
import { Input } from '../ui/Input';
import TaskComments from './TaskComments';

export default function TaskModal({
  isOpen = true,
  onClose,
  onSave,
  initialData,
}: any) {
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [dueDate, setDueDate] = useState('');
  const [priority, setPriority] = useState('medium');
  const [status, setStatus] = useState('todo');

  // Reset state when modal opens
  const prevIsOpen = React.useRef(isOpen);
  if (isOpen !== prevIsOpen.current) {
    prevIsOpen.current = isOpen;
    if (isOpen) {
      setTitle(initialData?.title || '');
      setDescription(initialData?.description || '');
      setDueDate(initialData?.dueDate || initialData?.initialDate || '');
      setPriority(initialData?.priority || 'medium');
      setStatus(initialData?.status || 'todo');
    }
  }

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave({ title, description, dueDate, priority, status });
    onClose();
  };

  return (
    <Dialog open={isOpen} onClose={onClose}>
      <DialogPanel>
        <button
          onClick={onClose}
          className="absolute right-5 top-5 rounded-full bg-[color:var(--color-surface-hover)] p-2 text-[color:var(--color-muted)]"
          aria-label="Close modal"
        >
          <X size={18} />
        </button>

        <div className="mb-6 flex items-center gap-3">
          <div className="flex h-11 w-11 items-center justify-center rounded-2xl bg-[color:var(--color-accent)]/10 text-[color:var(--color-accent)]">
            <Check size={20} />
          </div>
          <div>
            <DialogTitle>{initialData?._id ? 'Edit task' : 'Create task'}</DialogTitle>
            <DialogDescription>Capture the next thing worth doing.</DialogDescription>
          </div>
        </div>

        <div className={initialData?._id ? "grid grid-cols-1 md:grid-cols-2 gap-6" : ""}>
          <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-2">
            <label className="text-sm font-semibold text-[color:var(--color-foreground)]">Title</label>
            <Input value={title} onChange={(e: any) => setTitle(e.target.value)} placeholder="Finalize presentation slides" required autoFocus />
          </div>

          <div className="space-y-2">
            <label className="text-sm font-medium text-[color:var(--color-foreground)]">Due date</label>
            <div className="relative">
              <Calendar size={16} className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-[color:var(--color-muted)]" />
              <Input type="date" value={dueDate} onChange={(e: any) => setDueDate(e.target.value)} className="pl-10" />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <label className="text-sm font-medium text-[color:var(--color-foreground)]">Priority</label>
              <select
                value={priority}
                onChange={(e) => setPriority(e.target.value)}
                className="w-full h-10 px-3 rounded-md bg-[color:var(--color-background)] border text-sm outline-none"
                style={{ borderColor: 'var(--color-border)' }}
              >
                <option value="low">Low</option>
                <option value="medium">Medium</option>
                <option value="high">High</option>
                <option value="urgent">Urgent</option>
              </select>
            </div>
            <div className="space-y-2">
              <label className="text-sm font-medium text-[color:var(--color-foreground)]">Status</label>
              <select
                value={status}
                onChange={(e) => setStatus(e.target.value)}
                className="w-full h-10 px-3 rounded-md bg-[color:var(--color-background)] border text-sm outline-none"
                style={{ borderColor: 'var(--color-border)' }}
              >
                <option value="todo">To Do</option>
                <option value="in-progress">In Progress</option>
                <option value="review">In Review</option>
                <option value="done">Done</option>
              </select>
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-sm font-medium text-[color:var(--color-foreground)]">Description</label>
            <textarea
              value={description}
              onChange={(e: any) => setDescription(e.target.value)}
              className="min-h-[110px] w-full rounded-xl border border-border bg-surface px-3.5 py-2.5 text-sm text-[color:var(--color-foreground)] outline-none transition-all focus:border-[color:var(--color-accent)] focus:ring-2 focus:ring-[color:var(--color-accent)]/15"
              placeholder="Add notes, context, or subtasksΓÇª"
            />
          </div>

            <div className="flex flex-col gap-2 pt-2 sm:flex-row sm:justify-end">
              <Button type="button" variant="secondary" onClick={onClose} className="sm:w-auto">Cancel</Button>
              <Button type="submit" className="sm:w-auto">Save task</Button>
            </div>
          </form>

          {initialData?._id && (
            <div className="flex flex-col rounded-xl border border-border bg-surface-hover h-full max-h-[400px]">
              <div className="p-3 border-b border-border bg-[color:var(--color-surface)] rounded-t-xl">
                <h4 className="text-xs font-semibold text-[color:var(--color-foreground)]">Activity & Comments</h4>
              </div>
              <TaskComments taskId={initialData._id} />
            </div>
          )}
        </div>
      </DialogPanel>
    </Dialog>
  );
}

import { useState } from 'react';
import { createPortal } from 'react-dom';
import { useOrganizationStore } from '../../store/organizationStore';
import { useWorkspaceStore } from '../../store/workspaceStore';
import { X, Building } from 'lucide-react';
import toast from 'react-hot-toast';

export default function CreateOrganizationModal({ onClose }: { onClose: () => void }) {
  const [name, setName] = useState('');
  const [domain, setDomain] = useState('');
  const { createOrganization } = useOrganizationStore();
  const { fetchWorkspaces } = useWorkspaceStore(); // re-fetch after org created
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!name.trim()) return;

    setIsSubmitting(true);
    try {
      await createOrganization({ name, domain });
      toast.success('Organization created successfully');
      await fetchWorkspaces();
      onClose();
    } catch (err: any) {
      toast.error(err.response?.data?.error || 'Failed to create organization');
    } finally {
      setIsSubmitting(false);
    }
  };

  return createPortal(
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/50 p-4">
      <div 
        className="w-full max-w-md rounded-xl border p-6 shadow-xl"
        style={{ background: 'var(--color-surface)', borderColor: 'var(--color-border)' }}
      >
        <div className="mb-6 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Building size={20} className="text-purple-500" />
            <h2 className="text-lg font-bold" style={{ color: 'var(--color-foreground)' }}>
              Create Organization
            </h2>
          </div>
          <button 
            onClick={onClose}
            className="rounded-lg p-2 transition-colors hover:bg-[color:var(--color-surface-hover)]"
            style={{ color: 'var(--color-muted)' }}
          >
            <X size={20} />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="mb-1 block text-sm font-medium" style={{ color: 'var(--color-foreground)' }}>
              Organization Name
            </label>
            <input
              type="text"
              required
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="e.g. Acme Corp"
              className="w-full rounded-lg border p-2.5 text-sm outline-none transition-colors"
              style={{ 
                background: 'var(--color-background)', 
                borderColor: 'var(--color-border)',
                color: 'var(--color-foreground)'
              }}
            />
          </div>
          <div>
            <label className="mb-1 block text-sm font-medium" style={{ color: 'var(--color-foreground)' }}>
              Domain (Optional)
            </label>
            <input
              type="text"
              value={domain}
              onChange={(e) => setDomain(e.target.value)}
              placeholder="acme.com"
              className="w-full rounded-lg border p-2.5 text-sm outline-none transition-colors"
              style={{ 
                background: 'var(--color-background)', 
                borderColor: 'var(--color-border)',
                color: 'var(--color-foreground)'
              }}
            />
          </div>

          <div className="mt-6 flex justify-end gap-3">
            <button
              type="button"
              onClick={onClose}
              className="rounded-lg px-4 py-2 text-sm font-medium transition-colors"
              style={{ color: 'var(--color-muted)' }}
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={isSubmitting}
              className="rounded-lg px-4 py-2 text-sm font-medium text-white transition-opacity disabled:opacity-50 bg-purple-600 hover:bg-purple-700"
            >
              {isSubmitting ? 'Creating...' : 'Create Organization'}
            </button>
          </div>
        </form>
      </div>
    </div>,
    document.body
  );
}

import { useState } from 'react';
import { createPortal } from 'react-dom';
import { useTeamStore } from '../../store/teamStore';
import { useWorkspaceStore } from '../../store/workspaceStore';
import { X, Building2, Users } from 'lucide-react';
import toast from 'react-hot-toast';

interface CreateTeamModalProps {
  onClose: () => void;
}

export default function CreateTeamModal({ onClose }: CreateTeamModalProps) {
  const { createTeam } = useTeamStore();
  const { fetchWorkspaces } = useWorkspaceStore();
  
  const [loading, setLoading] = useState(false);
  const [formData, setFormData] = useState({
    name: '',
    slug: '',
    description: '',
    workspaceName: '',
    visibility: 'private' as 'private' | 'public',
  });

  const handleNameChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const name = e.target.value;
    setFormData(s => ({
      ...s,
      name,
      slug: name.toLowerCase().replace(/[^a-z0-9]/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, ''),
    }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || !formData.slug) return toast.error('Name and slug are required');

    setLoading(true);
    try {
      await createTeam(formData);
      await fetchWorkspaces();
      onClose();
    } catch (error) {
      // toast is handled in store
    } finally {
      setLoading(false);
    }
  };

  return createPortal(
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/50 p-4">
      <div 
        className="w-full max-w-md rounded-xl shadow-2xl overflow-hidden animate-in fade-in zoom-in-95 duration-200"
        style={{ background: 'var(--color-surface)', border: '1px solid var(--color-border)' }}
      >
        <div className="flex items-center justify-between border-b p-4" style={{ borderColor: 'var(--color-border)' }}>
          <div className="flex items-center gap-2 font-semibold">
            <Building2 size={20} className="text-[var(--color-accent)]" />
            <h2>Create New Team</h2>
          </div>
          <button onClick={onClose} className="rounded hover:bg-black/10 p-1 transition-colors">
            <X size={20} />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-4 space-y-4">
          <div>
            <label className="mb-1 block text-sm font-medium">Team Name *</label>
            <input
              type="text"
              value={formData.name}
              onChange={handleNameChange}
              placeholder="e.g. Product Team"
              className="w-full rounded-md border p-2 text-sm focus:border-[var(--color-accent)] focus:outline-none"
              style={{ background: 'var(--color-background)', borderColor: 'var(--color-border)', color: 'var(--color-foreground)' }}
              required
            />
          </div>

          <div>
            <label className="mb-1 block text-sm font-medium">Team Slug *</label>
            <div className="flex items-center gap-2">
              <span className="text-sm text-[var(--color-muted)]">tamad.com/</span>
              <input
                type="text"
                value={formData.slug}
                onChange={(e) => setFormData(s => ({ ...s, slug: e.target.value.toLowerCase().replace(/[^a-z0-9-]/g, '') }))}
                className="flex-1 rounded-md border p-2 text-sm focus:border-[var(--color-accent)] focus:outline-none"
                style={{ background: 'var(--color-background)', borderColor: 'var(--color-border)', color: 'var(--color-foreground)' }}
                required
              />
            </div>
          </div>

          <div>
            <label className="mb-1 block text-sm font-medium">Default Workspace Name</label>
            <input
              type="text"
              value={formData.workspaceName}
              onChange={(e) => setFormData(s => ({ ...s, workspaceName: e.target.value }))}
              placeholder={`e.g. ${formData.name || 'Team'} Workspace`}
              className="w-full rounded-md border p-2 text-sm focus:border-[var(--color-accent)] focus:outline-none"
              style={{ background: 'var(--color-background)', borderColor: 'var(--color-border)', color: 'var(--color-foreground)' }}
            />
          </div>

          <div>
            <label className="mb-1 block text-sm font-medium">Visibility</label>
            <select
              value={formData.visibility}
              onChange={(e) => setFormData(s => ({ ...s, visibility: e.target.value as any }))}
              className="w-full rounded-md border p-2 text-sm focus:border-[var(--color-accent)] focus:outline-none"
              style={{ background: 'var(--color-background)', borderColor: 'var(--color-border)', color: 'var(--color-foreground)' }}
            >
              <option value="private">Private (Invite only)</option>
              <option value="public">Public (Anyone with link can join)</option>
            </select>
          </div>

          <div className="flex justify-end gap-3 pt-4">
            <button
              type="button"
              onClick={onClose}
              className="rounded-md px-4 py-2 text-sm font-medium transition-colors hover:bg-black/5"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={loading}
              className="flex items-center gap-2 rounded-md px-4 py-2 text-sm font-medium text-white transition-opacity disabled:opacity-50"
              style={{ background: 'var(--color-accent)' }}
            >
              {loading ? 'Creating...' : 'Create Team'}
            </button>
          </div>
        </form>
      </div>
    </div>,
    document.body
  );
}

import { useState } from 'react';
import { createPortal } from 'react-dom';
import { useTeamStore } from '../../store/teamStore';
import { useWorkspaceStore } from '../../store/workspaceStore';
import { X, Link as LinkIcon } from 'lucide-react';
import toast from 'react-hot-toast';

interface JoinTeamModalProps {
  onClose: () => void;
}

export default function JoinTeamModal({ onClose }: JoinTeamModalProps) {
  const { joinTeam } = useTeamStore();
  const { fetchWorkspaces } = useWorkspaceStore();
  
  const [loading, setLoading] = useState(false);
  const [token, setToken] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!token.trim()) return toast.error('Invite code or link is required');

    // Extract token if it's a URL
    let parsedToken = token.trim();
    if (parsedToken.includes('/join/')) {
      parsedToken = parsedToken.split('/join/')[1];
    }

    setLoading(true);
    try {
      // The joinTeam function currently requires a team ID. 
      // Wait, the API for joinTeam takes the token and figures out the team. 
      // Our teamStore signature requires ID, we should update the store if we don't have the ID, or we can hit a global /api/teams/join endpoint. 
      // Wait! The backend route is /api/teams/:id/join. 
      // So if the token doesn't include the team ID, we have an issue.
      // But let's assume we update the backend API to take just the token and join the appropriate team.
      // For now we will hit the team store join method. (We'll update the store and backend to just take token)
      
      await joinTeam('from-token', parsedToken);
      await fetchWorkspaces();
      onClose();
    } catch (error) {
      // toast is handled
    } finally {
      setLoading(false);
    }
  };

  return createPortal(
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/50 p-4">
      <div 
        className="w-full max-w-md rounded-xl shadow-2xl overflow-hidden animate-in fade-in zoom-in-95 duration-200"
        style={{ background: 'var(--color-surface)', border: '1px solid var(--color-border)' }}
      >
        <div className="flex items-center justify-between border-b p-4" style={{ borderColor: 'var(--color-border)' }}>
          <div className="flex items-center gap-2 font-semibold">
            <LinkIcon size={20} className="text-[var(--color-accent)]" />
            <h2>Join Team</h2>
          </div>
          <button onClick={onClose} className="rounded hover:bg-black/10 p-1 transition-colors">
            <X size={20} />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-4 space-y-4">
          <div>
            <label className="mb-1 block text-sm font-medium">Invite Code or Link *</label>
            <input
              type="text"
              value={token}
              onChange={(e) => setToken(e.target.value)}
              placeholder="Paste invite code or link here..."
              className="w-full rounded-md border p-2 text-sm focus:border-[var(--color-accent)] focus:outline-none"
              style={{ background: 'var(--color-background)', borderColor: 'var(--color-border)', color: 'var(--color-foreground)' }}
              required
            />
            <p className="mt-2 text-xs text-[var(--color-muted)]">
              Ask your team admin for an invite link if you don't have one.
            </p>
          </div>

          <div className="flex justify-end gap-3 pt-4">
            <button
              type="button"
              onClick={onClose}
              className="rounded-md px-4 py-2 text-sm font-medium transition-colors hover:bg-black/5"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={loading}
              className="flex items-center gap-2 rounded-md px-4 py-2 text-sm font-medium text-white transition-opacity disabled:opacity-50"
              style={{ background: 'var(--color-accent)' }}
            >
              {loading ? 'Joining...' : 'Join Team'}
            </button>
          </div>
        </form>
      </div>
    </div>,
    document.body
  );
}

