        </button>
        <button
          onClick={() => setActiveTab('parser')}
          className={clsx('rounded-lg px-4 py-2 text-sm font-medium transition-all', activeTab === 'parser' ? 'btn-primary' : 'btn-ghost')}
          style={activeTab === 'parser' ? {} : { color: 'var(--color-muted)' }}
