                          style={{
                            background: msg.role === 'user' ? 'var(--color-accent)' : 'var(--color-background)',
                            color: msg.role === 'user' ? 'white' : 'var(--color-foreground)',
                            border: msg.role === 'user' ? 'none' : '1px solid var(--color-border-light)',
                          }}
                        >
                          <p className="whitespace-pre-wrap">{msg.content}</p>
                          <p className="mt-2 text-[10px] opacity-60">
                            {new Date(msg.timestamp).toLocaleTimeString()}
                          </p>
                        </div>
                      </motion.div>
                    ))}
                    {chatLoading && (
                      <div className="flex gap-3">
                        <div
                          className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg"
                          style={{ background: 'var(--color-accent-light)', color: 'var(--color-accent)' }}
                        >
                          <Sparkles size={14} />
                        </div>
                        <div className="rounded-xl rounded-bl-sm px-4 py-3" style={{ background: 'var(--color-background)', border: '1px solid var(--color-border-light)' }}>
                          <div className="flex items-center gap-2">
                            <Loader2 size={14} className="animate-spin" style={{ color: 'var(--color-accent)' }} />
                            <span className="text-sm" style={{ color: 'var(--color-muted)' }}>Thinking...</span>
                          </div>
                        </div>
                      </div>
                    )}
                    <div ref={chatEndRef} />
                  </div>
                )}
              </div>

              <div className="border-t p-4" style={{ borderColor: 'var(--color-border)' }}>
                <div className="flex items-end gap-3">
                  <textarea
                    ref={chatInputRef}
                    value={chatInput}
                    onChange={(e) => setChatInput(e.target.value)}
                    onKeyDown={handleKeyDown}
                    placeholder="Ask about your workspace..."
                    rows={1}
                    className="input flex-1 resize-none"
                    style={{ minHeight: '42px', maxHeight: '120px' }}
                  />
                  <button
                    onClick={handleSendChat}
                    disabled={!chatInput.trim() || chatLoading}
                    className="btn btn-primary shrink-0"
                    style={{ height: '42px', width: '42px', padding: 0, display: 'flex', alignItems: 'center', justifyContent: 'center' }}
                  >
                    <Send size={16} />
                  </button>
                </div>
              </div>
            </div>
          </motion.div>
        ) : (
          <motion.div
            key="parser"
            initial={{ opacity: 0, y: 8 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -8 }}
          >
            <div className="grid gap-6 lg:grid-cols-2">
              <div className="card p-6">
                <h3 className="mb-4 text-base font-bold" style={{ color: 'var(--color-foreground)' }}>
                  <Wand2 size={16} className="mr-2 inline" style={{ color: 'var(--color-accent)' }} />
                  Natural Language Input
                </h3>
                <textarea
                  value={parseInput}
                  onChange={(e) => setParseInput(e.target.value)}
                  onKeyDown={handleKeyDown}
                  placeholder="Describe your task in natural language..."
                  rows={4}
                  className="input mb-4 w-full resize-none"
                />
                <button
                  onClick={handleParse}
                  disabled={!parseInput.trim() || parsing}
                  className="btn btn-primary w-full"
                >
                  {parsing ? <Loader2 size={16} className="animate-spin" /> : <Wand2 size={16} />}
                  {parsing ? 'Parsing...' : 'Parse Task'}
                </button>

                <div className="mt-6">
                  <p className="mb-3 text-xs font-semibold uppercase tracking-wider" style={{ color: 'var(--color-muted)' }}>
                    Examples
                  </p>
                  <div className="space-y-2">
                    {PARSE_EXAMPLES.map((example, i) => (
                      <button
                        key={i}
                        onClick={() => setParseInput(example)}
                        className="w-full rounded-lg border p-3 text-left text-xs leading-relaxed transition-all hover:shadow-sm"
                        style={{ background: 'var(--color-background)', borderColor: 'var(--color-border-light)', color: 'var(--color-muted)' }}
                      >
                        "{example}"
                      </button>
                    ))}
                  </div>
                </div>
              </div>

              <div className="card p-6">
                <h3 className="mb-4 text-base font-bold" style={{ color: 'var(--color-foreground)' }}>
                  <Sparkles size={16} className="mr-2 inline" style={{ color: 'var(--color-accent)' }} />
                  Parsed Result
                </h3>
                {!parsedTask ? (
                  <div className="flex flex-col items-center justify-center py-12">
                    <div
                      className="mb-4 flex h-12 w-12 items-center justify-center rounded-xl"
                      style={{ background: 'var(--color-surface-active)', color: 'var(--color-muted)' }}
                    >
                      <Wand2 size={20} />
                    </div>
                    <p className="text-sm" style={{ color: 'var(--color-muted)' }}>
                      Enter text on the left to see the parsed task.
                    </p>
                  </div>
                ) : (
                  <motion.div
                    initial={{ opacity: 0, scale: 0.95 }}
                    animate={{ opacity: 1, scale: 1 }}
                    className="space-y-4"
                  >
                    <div
                      className="rounded-xl border p-4"
                      style={{ background: 'var(--color-background)', borderColor: 'var(--color-border-light)' }}
                    >
                      <div className="mb-3 flex items-center justify-between">
                        <h4 className="text-sm font-bold" style={{ color: 'var(--color-foreground)' }}>
                          {parsedTask.title}
                        </h4>
                        <button
                          onClick={() => handleCopy(parsedTask.title)}
                          className="rounded p-1 transition-colors hover:bg-[var(--color-surface-active)]"
                          style={{ color: 'var(--color-muted)' }}
                        >
                          {copied ? <Check size={14} /> : <Copy size={14} />}
                        </button>
                      </div>

                      {parsedTask.description && (
                        <p className="mb-3 text-sm leading-relaxed" style={{ color: 'var(--color-muted)' }}>
                          {parsedTask.description}
                        </p>
                      )}

                      <div className="flex flex-wrap gap-2">
                        <span
                          className="inline-flex items-center gap-1 rounded-full px-2.5 py-1 text-xs font-semibold"
                          style={{ background: priorityColors[parsedTask.priority] + '20', color: priorityColors[parsedTask.priority] }}
                        >
                          <AlertCircle size={12} />
                          {parsedTask.priority}
                        </span>
                        {parsedTask.dueDate && (
                          <span
                            className="inline-flex items-center gap-1 rounded-full px-2.5 py-1 text-xs font-semibold"
                            style={{ background: 'var(--color-info-light)', color: 'var(--color-info)' }}
                          >
                            <Calendar size={12} />
                            {new Date(parsedTask.dueDate).toLocaleDateString()}
                          </span>
                        )}
                      </div>
                    </div>

                    <div className="flex gap-3">
                      <button onClick={handleCreateFromParsed} className="btn btn-primary flex-1">
                        <Check size={16} />
                        Create Task
                      </button>
                      <button onClick={clearParsedTask} className="btn btn-ghost">
                        <Trash2 size={16} />
                        Clear
                      </button>
                    </div>
                  </motion.div>
                )}
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { useWorkspaceStore } from '../store/workspaceStore';
import { useTaskStore } from '../store/taskStore';
import { useAgileStore } from '../store/agileStore';
import IssueDetailModal from '../components/tasks/IssueDetailModal';
import { DndContext, closestCenter, KeyboardSensor, PointerSensor, useSensor, useSensors, DragEndEvent } from '@dnd-kit/core';
import { SortableContext, verticalListSortingStrategy, useSortable } from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import toast from 'react-hot-toast';

function SortableKanbanItem({ task, onClick }: { task: any, onClick: () => void }) {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({ id: task._id });
  const style = { transform: CSS.Transform.toString(transform), transition, opacity: isDragging ? 0.4 : 1 };

  return (
    <div 
      ref={setNodeRef}
      style={{ ...style, borderColor: 'var(--color-border-light)' }}
      className="mb-2 cursor-pointer rounded-lg border p-3 bg-[color:var(--color-surface)] shadow-sm hover:border-[color:var(--color-accent)] transition-colors"
      onClick={onClick}
    >
      <div className="mb-2 flex justify-between items-center" {...attributes} {...listeners}>
        <span className="text-[10px] font-bold uppercase tracking-wider text-[color:var(--color-muted)]">{task.taskType || 'Task'}</span>
        <span className="text-xs text-[color:var(--color-muted)]">{task.storyPoints ? `${task.storyPoints} pts` : ''}</span>
      </div>
      <h4 className="text-sm font-medium text-[color:var(--color-foreground)]">{task.title}</h4>
      {task.assignees && task.assignees.length > 0 && (
        <div className="mt-3 flex -space-x-1">
          {task.assignees.map((a: any) => (
            <div key={a.email} className="h-5 w-5 rounded-full bg-[color:var(--color-accent)] text-white flex items-center justify-center text-[10px] font-bold border border-[color:var(--color-surface)]" title={a.name}>
              {a.name.charAt(0)}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export default function AgileBoardPage() {
  const currentWorkspace = useWorkspaceStore(s => s.currentWorkspace);
  const { tasks, fetchTasks, updateTask } = useTaskStore();
  const { sprints, fetchSprints, completeSprint } = useAgileStore();
  const [selectedTask, setSelectedTask] = useState<any>(null);

  useEffect(() => {
    if (currentWorkspace?._id) {
      fetchTasks(currentWorkspace._id);
      fetchSprints(currentWorkspace._id, '');
    }
  }, [currentWorkspace?._id]);

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 5 } }),
    useSensor(KeyboardSensor)
  );

  if (!currentWorkspace) return <div className="p-8">Loading...</div>;

  const activeSprint = sprints.find(s => s.status === 'active');
  
  // Show tasks in active sprint. If no active sprint, maybe show an empty state.
  const activeTasks = activeSprint ? tasks.filter(t => t.sprintId === activeSprint._id) : [];

  const handleDragEnd = async (event: DragEndEvent) => {
    const { active, over } = event;
    if (!over) return;

    const taskId = active.id as string;
    const overId = over.id as string; // Will be the column ID (e.g. 'todo') or a task in the column

    // Find the task
    const task = tasks.find(t => t._id === taskId);
    if (!task) return;

    // Determine target column
    let targetStatus = overId;
    const columns = ['todo', 'in-progress', 'review', 'done'];
    if (!columns.includes(overId)) {
      // dropped over another task, find its status
      const targetTask = tasks.find(t => t._id === overId);
      if (targetTask) targetStatus = targetTask.status;
    }

    if (task.status === targetStatus || !columns.includes(targetStatus)) return; // No change

    // Optimistic Update
    try {
      await updateTask(taskId, { status: targetStatus });
    } catch {
      fetchTasks(currentWorkspace._id); // Revert on failure
    }
  };

  const columns = [
    { id: 'todo', label: 'To Do' },
    { id: 'in-progress', label: 'In Progress' },
    { id: 'review', label: 'In Review' },
    { id: 'done', label: 'Done' }
  ];

  return (
    <div className="flex h-full flex-col">
      <div className="flex items-center justify-between border-b border-[var(--color-border-light)] p-6">
        <div>
          <h1 className="text-2xl font-bold" style={{ color: 'var(--color-foreground)' }}>Active Sprint</h1>
          <p className="mt-1 text-sm text-[var(--color-muted)]">
            {activeSprint ? activeSprint.name : 'No active sprint'}
          </p>
        </div>
        <div className="flex items-center gap-3">
          {activeSprint && (
            <button 
              onClick={() => completeSprint(activeSprint._id)}
              className="rounded-lg px-4 py-2 text-sm font-medium transition-colors hover:opacity-90 text-white" 
              style={{ background: 'var(--color-accent)' }}>
              Complete Sprint
            </button>
          )}
        </div>
      </div>

      <div className="flex-1 overflow-x-auto p-6">
        {!activeSprint ? (
          <div className="flex h-full items-center justify-center">
            <div className="text-center">
              <h2 className="text-xl font-bold text-[color:var(--color-foreground)]">No Active Sprint</h2>
              <p className="mt-2 text-[color:var(--color-muted)]">Go to Sprint Planning to start a sprint.</p>
            </div>
          </div>
        ) : (
          <DndContext sensors={sensors} collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
            <div className="flex h-full min-w-max gap-6">
              {columns.map((col) => {
                const colTasks = activeTasks.filter(t => t.status === col.id);
                return (
                  <div key={col.id} className="flex w-80 flex-col rounded-xl" style={{ background: 'var(--color-surface-hover)' }}>
                    <div className="flex items-center justify-between p-4">
                      <h3 className="font-semibold text-[var(--color-foreground)]">{col.label}</h3>
                      <span className="flex h-5 items-center justify-center rounded-full px-2 text-xs font-medium" style={{ background: 'var(--color-surface)', color: 'var(--color-muted)' }}>
                        {colTasks.length}
                      </span>
                    </div>
                    
                    <SortableContext items={colTasks.map(t => t._id)} strategy={verticalListSortingStrategy}>
                      <div className="flex-1 p-2 flex flex-col gap-2 min-h-[200px]" id={col.id}>
                        {colTasks.length === 0 ? (
                          <div className="flex h-full min-h-[100px] items-center justify-center border-2 border-dashed rounded-lg opacity-50" style={{ borderColor: 'var(--color-border-light)' }}>
                            <p className="text-sm" style={{ color: 'var(--color-muted)' }}>Drop tasks here</p>
                          </div>
                        ) : (
                          colTasks.map(task => (
                            <SortableKanbanItem key={task._id} task={task} onClick={() => setSelectedTask(task)} />
                          ))
                        )}
                      </div>
                    </SortableContext>
                  </div>
                );
              })}
            </div>
          </DndContext>
        )}
      </div>
      
      <IssueDetailModal 
        isOpen={!!selectedTask}
        onClose={() => setSelectedTask(null)}
        initialData={selectedTask}
      />
    </div>
  );
}

import { useMemo, useEffect, useCallback } from 'react';
import { motion } from 'framer-motion';
import {
  TrendingUp, CheckCircle2, ListTodo, Clock, Zap, Target, Download,
} from 'lucide-react';
import {
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
  PieChart, Pie, Cell,
} from 'recharts';
import { useTaskStore } from '../store/taskStore';
import { useProjectStore } from '../store/projectStore';
import { useAuthStore } from '../store/authStore';
import LoadingSpinner from '../components/ui/LoadingSpinner';
import ErrorState from '../components/ui/ErrorState';
import toast from 'react-hot-toast';

const cardVariant = {
  hidden: { opacity: 0, y: 12 },
  visible: (i: number) => ({
    opacity: 1, y: 0,
    transition: { delay: i * 0.08, duration: 0.35, ease: [0.16, 1, 0.3, 1] as [number, number, number, number] },
  }),
};

export default function AnalyticsPage() {
  const { tasks, fetchTasks, loading: tasksLoading, error: tasksError } = useTaskStore();
  const { projects, fetchProjects, loading: projectsLoading, error: projectsError } = useProjectStore();
  const workspace = useAuthStore(s => s.workspace);
  const workspaceId = workspace?._id || '';

  const isLoading = tasksLoading || projectsLoading;
  const error = tasksError || projectsError;

  const retry = useCallback(() => {
    if (workspaceId) {
      fetchTasks(workspaceId);
      fetchProjects(workspaceId);
    }
  }, [fetchTasks, fetchProjects, workspaceId]);

  const exportCSV = useCallback(() => {
    try {
      const header = 'Title,Status,Priority,Project,Created,Updated,Assignee';
      const rows = tasks.map((t: any) => {
        const project = projects.find((p: any) => p._id === t.projectId);
        return [
          `"${(t.title || '').replace(/"/g, '""')}"`,
          t.status || '',
          t.priority || '',
          project?.name || '',
          t.createdAt ? new Date(t.createdAt).toISOString().slice(0, 10) : '',
          t.updatedAt ? new Date(t.updatedAt).toISOString().slice(0, 10) : '',
          t.assigneeName || t.assignee || '',
        ].join(',');
      });
      const csv = [header, ...rows].join('\n');
      const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `tamad-analytics-${new Date().toISOString().slice(0, 10)}.csv`;
      a.click();
      URL.revokeObjectURL(url);
      toast.success('Analytics exported as CSV');
    } catch {
      toast.error('Failed to export analytics');
    }
  }, [tasks, projects]);

  useEffect(() => {
    if (workspaceId) {
      fetchTasks(workspaceId);
      fetchProjects(workspaceId);
    }
  }, [fetchTasks, fetchProjects, workspaceId]);

  const totalTasks = tasks.length;
  const completed = tasks.filter((t: any) => t.status === 'done').length;
  const inProgress = tasks.filter((t: any) => t.status === 'in-progress').length;
  const efficiency = totalTasks > 0 ? Math.round((completed / totalTasks) * 100) : 0;

  const weeklyProductivity = useMemo(() => {
    const days = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
    const now = new Date();
    return days.map((day, i) => {
      const date = new Date(now);
      date.setDate(now.getDate() - (6 - i));
      const dateStr = date.toISOString().slice(0, 10);
      const completedCount = tasks.filter((t: any) => {
        if (!t.updatedAt) return false;
        return t.updatedAt.slice(0, 10) === dateStr && t.status === 'done';
      }).length;
      const createdCount = tasks.filter((t: any) => {
        if (!t.createdAt) return false;
        return t.createdAt.slice(0, 10) === dateStr;
      }).length;
      return { day, completed: completedCount, created: createdCount };
    });
  }, [tasks]);

  const statusDistribution = useMemo(() => {
    const counts: Record<string, number> = {};
    tasks.forEach((t: any) => {
      counts[t.status] = (counts[t.status] || 0) + 1;
    });
    return [
      { name: 'To Do', value: counts['todo'] || 0, color: 'var(--color-muted)' },
      { name: 'In Progress', value: counts['in-progress'] || 0, color: 'var(--color-accent)' },
      { name: 'Review', value: counts['review'] || 0, color: 'var(--color-warning)' },
      { name: 'Done', value: counts['done'] || 0, color: 'var(--color-success)' },
    ].filter(s => s.value > 0);
  }, [tasks]);

  const priorityDistribution = useMemo(() => {
    const counts: Record<string, number> = {};
    tasks.forEach((t: any) => {
      counts[t.priority] = (counts[t.priority] || 0) + 1;
    });
    return [
      { name: 'Urgent', value: counts['urgent'] || 0, color: 'var(--color-danger)' },
      { name: 'High', value: counts['high'] || 0, color: 'var(--color-warning)' },
      { name: 'Medium', value: counts['medium'] || 0, color: 'var(--color-accent)' },
      { name: 'Low', value: counts['low'] || 0, color: 'var(--color-muted)' },
    ].filter(p => p.value > 0);
  }, [tasks]);

  const stats = [
    { label: 'Tasks Completed', value: completed, sub: `of ${totalTasks} total`, icon: CheckCircle2, color: 'var(--color-success)', bg: 'var(--color-success-light)' },
    { label: 'Completion Rate', value: `${efficiency}%`, sub: 'overall efficiency', icon: TrendingUp, color: 'var(--color-accent)', bg: 'var(--color-accent-light)' },
    { label: 'In Progress', value: inProgress, sub: 'active tasks', icon: Clock, color: 'var(--color-info)', bg: 'var(--color-info-light)' },
    { label: 'Projects', value: projects.length, sub: 'total projects', icon: Zap, color: 'var(--color-warning)', bg: 'var(--color-warning-light)' },
  ];

  const insights = [
    { title: 'Focus Opportunity', text: `${inProgress} tasks are in progress. Consider finishing before starting new ones.`, icon: Target, color: 'var(--color-info)' },
    { title: 'Great Progress', text: `You've completed ${completed} tasks so far. Keep up the momentum!`, icon: CheckCircle2, color: 'var(--color-success)' },
    { title: 'Priority Alert', text: `${tasks.filter((t: any) => t.priority === 'urgent').length} urgent tasks need immediate attention.`, icon: Zap, color: 'var(--color-warning)' },
  ];

  const tooltipStyle = {
    background: 'var(--color-surface)',
    border: '1px solid var(--color-border)',
    borderRadius: 8,
    boxShadow: 'var(--shadow-medium)',
    fontSize: 13,
  };

  return (
    <div className="page">
      {/* Header */}
      <div className="page-header">
        <div>
          <h1 className="page-title">Analytics</h1>
          <p className="page-subtitle">Track productivity and performance insights across your workspace.</p>
        </div>
        {!isLoading && !error && tasks.length > 0 && (
          <button onClick={exportCSV} className="btn btn-ghost btn-sm">
            <Download size={14} />
            Export CSV
          </button>
        )}
      </div>

      {isLoading && <LoadingSpinner text="Loading analytics..." />}

      {!isLoading && error && <ErrorState message={error} onRetry={retry} />}

      {!isLoading && !error && (
        <>
          {/* Stat cards */}
      <div className="mb-8 grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
        {stats.map((stat, i) => {
          const Icon = stat.icon;
          return (
            <motion.div key={stat.label} custom={i} initial="hidden" animate="visible" variants={cardVariant}>
              <div className="stat-card">
                <div className="mb-3 flex items-center justify-between">
                  <span className="text-xs font-bold uppercase tracking-wider" style={{ color: 'var(--color-muted)' }}>{stat.label}</span>
                  <div className="flex h-9 w-9 items-center justify-center rounded-xl" style={{ background: stat.bg, color: stat.color }}>
                    <Icon size={18} />
                  </div>
                </div>
                <div className="text-3xl font-bold tracking-tight" style={{ color: 'var(--color-foreground)' }}>{stat.value}</div>
                <p className="mt-1 text-xs" style={{ color: 'var(--color-muted)' }}>{stat.sub}</p>
              </div>
            </motion.div>
          );
        })}
      </div>

      {/* Charts grid */}
      <div className="grid gap-6 xl:grid-cols-3">
        {/* Weekly trend */}
        <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.3 }} className="xl:col-span-2">
          <div className="card p-5">
            <h3 className="mb-1 text-base font-bold" style={{ color: 'var(--color-foreground)' }}>Weekly Trend</h3>
            <p className="mb-5 text-xs" style={{ color: 'var(--color-muted)' }}>Tasks completed vs created</p>
            <div className="h-72">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={weeklyProductivity} barGap={4}>
                  <CartesianGrid strokeDasharray="3 3" stroke="var(--color-border-light)" vertical={false} />
                  <XAxis dataKey="day" tick={{ fontSize: 12, fill: 'var(--color-muted)' }} axisLine={false} tickLine={false} />
                  <YAxis tick={{ fontSize: 12, fill: 'var(--color-muted)' }} axisLine={false} tickLine={false} />
                  <Tooltip contentStyle={tooltipStyle} />
                  <Bar dataKey="completed" fill="var(--color-accent)" radius={[4, 4, 0, 0]} name="Completed" />
                  <Bar dataKey="created" fill="var(--color-border)" radius={[4, 4, 0, 0]} name="Created" />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </div>
        </motion.div>

        {/* Status distribution */}
        <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.35 }}>
          <div className="card p-5">
            <h3 className="mb-1 text-base font-bold" style={{ color: 'var(--color-foreground)' }}>Status Distribution</h3>
            <p className="mb-4 text-xs" style={{ color: 'var(--color-muted)' }}>Current task breakdown</p>
            <div className="flex h-52 items-center justify-center">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={statusDistribution}
                    cx="50%"
                    cy="50%"
                    innerRadius={50}
                    outerRadius={80}
                    paddingAngle={3}
                    dataKey="value"
                    strokeWidth={0}
                  >
                    {statusDistribution.map((entry, i) => (
                      <Cell key={i} fill={entry.color} />
                    ))}
                  </Pie>
                  <Tooltip contentStyle={tooltipStyle} />
                </PieChart>
              </ResponsiveContainer>
            </div>
            <div className="mt-2 grid grid-cols-2 gap-2">
              {statusDistribution.map(item => (
                <div key={item.name} className="flex items-center gap-2 text-xs">
                  <span className="h-2.5 w-2.5 rounded-sm shrink-0" style={{ background: item.color }} />
                  <span style={{ color: 'var(--color-muted)' }}>{item.name}</span>
                  <span className="ml-auto font-semibold" style={{ color: 'var(--color-foreground)' }}>{item.value}</span>
                </div>
              ))}
            </div>
          </div>
        </motion.div>
      </div>

      {/* Bottom row */}
      <div className="mt-6 grid gap-6 xl:grid-cols-3">
        {/* Priority breakdown */}
        <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.4 }}>
          <div className="card p-5">
            <h3 className="mb-1 text-base font-bold" style={{ color: 'var(--color-foreground)' }}>Priority Breakdown</h3>
            <p className="mb-5 text-xs" style={{ color: 'var(--color-muted)' }}>Tasks by priority level</p>
            <div className="space-y-3">
              {priorityDistribution.map(item => {
                const maxVal = Math.max(...priorityDistribution.map(d => d.value));
                const width = maxVal > 0 ? (item.value / maxVal) * 100 : 0;
                return (
                  <div key={item.name}>
                    <div className="mb-1 flex items-center justify-between text-xs">
                      <span className="font-medium" style={{ color: 'var(--color-foreground)' }}>{item.name}</span>
                      <span className="font-semibold" style={{ color: item.color }}>{item.value}</span>
                    </div>
                    <div className="h-2.5 w-full overflow-hidden rounded-full" style={{ background: 'var(--color-border-light)' }}>
                      <motion.div
                        initial={{ width: 0 }}
                        animate={{ width: `${width}%` }}
                        transition={{ duration: 0.6, delay: 0.5, ease: [0.16, 1, 0.3, 1] }}
                        className="h-full rounded-full"
                        style={{ background: item.color }}
                      />
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        </motion.div>

        {/* Project breakdown */}
        <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.45 }} className="xl:col-span-1">
          <div className="card p-5">
            <h3 className="mb-1 text-base font-bold" style={{ color: 'var(--color-foreground)' }}>Projects</h3>
            <p className="mb-4 text-xs" style={{ color: 'var(--color-muted)' }}>Active project count</p>
            <div className="space-y-3">
              {projects.slice(0, 5).map((project: any) => {
                const maxTasks = Math.max(...tasks.map((t: any) => 1), 1);
                return (
                  <div key={project._id} className="flex items-center gap-3">
                    <div className="avatar avatar-sm shrink-0" style={{ background: project.color || 'var(--color-accent)', color: 'white' }}>
                      {project.name?.charAt(0) || 'P'}
                    </div>
                    <div className="min-w-0 flex-1">
                      <div className="flex items-center justify-between text-xs mb-1">
                        <span className="font-medium truncate" style={{ color: 'var(--color-foreground)' }}>{project.name}</span>
                      </div>
                    </div>
                  </div>
                );
              })}
              {projects.length === 0 && (
                <p className="text-xs" style={{ color: 'var(--color-muted)' }}>No projects yet</p>
              )}
            </div>
          </div>
        </motion.div>

        {/* AI Insights */}
        <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.5 }}>
          <div className="card p-5">
            <h3 className="mb-4 text-base font-bold" style={{ color: 'var(--color-foreground)' }}>AI Insights</h3>
            <div className="space-y-3">
              {insights.map((insight, i) => {
                const Icon = insight.icon;
                return (
                  <div key={i} className="rounded-lg p-3.5" style={{ background: 'var(--color-background)' }}>
                    <div className="mb-1.5 flex items-center gap-2">
                      <Icon size={14} style={{ color: insight.color }} />
                      <span className="text-xs font-bold" style={{ color: insight.color }}>{insight.title}</span>
                    </div>
                    <p className="text-xs leading-relaxed" style={{ color: 'var(--color-muted)' }}>{insight.text}</p>
                  </div>
                );
              })}
            </div>
          </div>
        </motion.div>
      </div>
        </>
      )}
    </div>
  );
}

import { useState, useMemo, useEffect, useCallback } from 'react';
import { motion } from 'framer-motion';
import {
  ChevronLeft, ChevronRight, Calendar as CalendarIcon,
  Clock, AlertTriangle, CheckCircle2, GripVertical,
} from 'lucide-react';
import {
  format,
  startOfMonth,
  endOfMonth,
  startOfWeek,
  endOfWeek,
  eachDayOfInterval,
  isSameMonth,
  isToday,
  isSameDay,
  addMonths,
  subMonths,
  parseISO,
  isBefore,
  addDays,
} from 'date-fns';
import clsx from 'clsx';
import { DndContext, DragOverlay, useDraggable, useDroppable, PointerSensor, useSensor, useSensors, type DragEndEvent } from '@dnd-kit/core';
import { useTaskStore } from '../store/taskStore';
import { useProjectStore } from '../store/projectStore';
import { useMeetingStore } from '../store/meetingStore';
import { useAuthStore } from '../store/authStore';
import { useTeamStore } from '../store/teamStore';
import LoadingSpinner from '../components/ui/LoadingSpinner';
import ErrorState from '../components/ui/ErrorState';
import toast from 'react-hot-toast';

function getPriorityDot(priority: string) {
  switch (priority) {
    case 'urgent': return 'var(--color-danger)';
    case 'high': return 'var(--color-warning)';
    case 'medium': return 'var(--color-accent)';
    case 'low': return 'var(--color-muted)';
    default: return 'var(--color-muted)';
  }
}

function isOverdue(dateStr: string) {
  if (!dateStr) return false;
  try {
    return isBefore(parseISO(dateStr), new Date()) && !isToday(parseISO(dateStr));
  } catch { return false; }
}

function MemberAvatar({ memberId }: { memberId: string }) {
  const initial = memberId?.charAt(0)?.toUpperCase() || '?';
  return (
    <div
      className="h-5 w-5 inline-flex items-center justify-center rounded-full text-[9px] font-bold text-white shrink-0"
      style={{ background: 'var(--color-accent)' }}
      title={memberId}
    >
      {initial}
    </div>
  );
}

function DraggableTaskChip({ task, onDragStart }: { task: any; onDragStart: (task: any) => void }) {
  const { attributes, listeners, setNodeRef, transform, isDragging } = useDraggable({
    id: task._id,
    data: { task },
  });

  const style = transform
    ? { transform: `translate3d(${transform.x}px, ${transform.y}px, 0)` }
    : undefined;

  return (
    <div
      ref={setNodeRef}
      {...listeners}
      {...attributes}
      onPointerDown={(e) => { onDragStart(task); (listeners as any).onPointerDown?.(e); }}
      className={clsx(
        'flex items-center gap-1.5 rounded-md px-1.5 py-1 text-[10px] font-medium transition-colors truncate cursor-grab active:cursor-grabbing',
        isDragging && 'opacity-40',
      )}
      style={{
        ...style,
        background: 'var(--color-surface-active)',
        color: 'var(--color-foreground)',
      }}
      title={`${task.title} ΓÇö drag to reschedule`}
    >
      <span className="h-1.5 w-1.5 rounded-full shrink-0" style={{ background: getPriorityDot(task.priority) }} />
      <span className="truncate flex-1">{task.title}</span>
      <GripVertical size={10} className="shrink-0 opacity-40" />
    </div>
  );
}

function MeetingChip({ meeting, onClick }: { meeting: any; onClick: () => void }) {
  return (
    <div
      onClick={onClick}
      className={clsx(
        'flex items-center gap-1.5 rounded-md px-1.5 py-1 text-[10px] font-medium transition-colors truncate cursor-pointer',
      )}
      style={{
        background: 'var(--color-primary-light, #e0f2fe)',
        color: 'var(--color-primary-800, #075985)',
      }}
      title={`${meeting.title} - ${format(new Date(meeting.startTime), 'h:mm a')}`}
    >
      <span className="h-1.5 w-1.5 rounded-full shrink-0 bg-blue-500" />
      <span className="truncate flex-1">{meeting.title}</span>
    </div>
  );
}

function DroppableDayCell({
  day, currentDate, dayTasks, dayMeetings, inMonth, today, selected, onSelect, isOver,
}: {
  day: Date; currentDate: Date; dayTasks: any[]; dayMeetings: any[]; inMonth: boolean; today: boolean;
  selected: boolean; onSelect: () => void; isOver: boolean;
}) {
  const { setNodeRef } = useDroppable({ id: format(day, 'yyyy-MM-dd') });

  return (
    <div
      ref={setNodeRef}
      onClick={onSelect}
      className={clsx(
        'flex flex-col p-2 cursor-pointer transition-all border-b border-r',
        !inMonth && 'opacity-40',
      )}
      style={{
        borderColor: 'var(--color-border-light)',
        background: isOver
          ? 'var(--color-accent-light)'
          : selected
          ? 'var(--color-accent-light)'
          : today
          ? 'var(--color-surface-hover)'
          : 'transparent',
      }}
    >
      <div
        className={clsx('mb-1.5 flex h-7 w-7 items-center justify-center rounded-full text-[12px] font-bold transition-all')}
        style={{
          background: today ? 'var(--color-accent)' : 'transparent',
          color: today ? 'white' : inMonth ? 'var(--color-foreground)' : 'var(--color-muted)',
        }}
      >
        {format(day, 'd')}
      </div>

      <div className="flex flex-1 flex-col gap-1 overflow-y-auto" style={{ scrollbarWidth: 'none' }}>
        {dayMeetings.slice(0, 2).map((meeting: any) => (
          <MeetingChip key={meeting._id} meeting={meeting} onClick={onSelect} />
        ))}
        {dayTasks.slice(0, 3).map((task: any) => (
          <DraggableTaskChip key={task._id} task={task} onDragStart={() => {}} />
        ))}
        {(dayTasks.length + dayMeetings.length) > 5 && (
          <span className="text-[9px] font-bold px-1" style={{ color: 'var(--color-muted)' }}>
            +{(dayTasks.length + dayMeetings.length) - 5} more
          </span>
        )}
      </div>
    </div>
  );
}

const DAY_NAMES = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

export default function CalendarPage() {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [selectedDay, setSelectedDay] = useState<Date | null>(null);
  const [projectFilter, setProjectFilter] = useState<string[]>([]);
  const [activeTask, setActiveTask] = useState<any>(null);
  const [overDate, setOverDate] = useState<string | null>(null);

  const { tasks, fetchTasks, updateTask, loading: tasksLoading, error: tasksError } = useTaskStore();
  const { projects, fetchProjects, loading: projectsLoading, error: projectsError } = useProjectStore();
  const { meetings, fetchMeetings, loading: meetingsLoading } = useMeetingStore();
  const { currentTeam } = useTeamStore();
  const workspace = useAuthStore(s => s.workspace);
  const workspaceId = workspace?._id || '';

  const isLoading = tasksLoading || projectsLoading || meetingsLoading;
  const error = tasksError || projectsError;

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 5 } }),
  );

  const retry = useCallback(() => {
    if (workspaceId) {
      fetchTasks(workspaceId);
      fetchProjects(workspaceId);
    }
    if (currentTeam?._id) {
      fetchMeetings(currentTeam._id);
    }
  }, [fetchTasks, fetchProjects, workspaceId, fetchMeetings, currentTeam]);

  useEffect(() => {
    if (workspaceId) {
      fetchTasks(workspaceId);
      fetchProjects(workspaceId);
    }
    if (currentTeam?._id) {
      fetchMeetings(currentTeam._id);
    }
  }, [fetchTasks, fetchProjects, workspaceId, fetchMeetings, currentTeam]);

  const monthStart = startOfMonth(currentDate);
  const monthEnd = endOfMonth(currentDate);
  const calStart = startOfWeek(monthStart);
  const calEnd = endOfWeek(monthEnd);
  const days = eachDayOfInterval({ start: calStart, end: calEnd });
  const totalWeeks = Math.ceil(days.length / 7);

  const filteredTasks = useMemo(() => {
    if (projectFilter.length === 0) return tasks;
    return tasks.filter((t: any) => projectFilter.includes(t.projectId));
  }, [tasks, projectFilter]);

  const tasksByDate = useMemo(() => {
    const map: Record<string, any[]> = {};
    filteredTasks.forEach((t: any) => {
      if (!t.dueDate) return;
      try {
        const key = format(parseISO(t.dueDate), 'yyyy-MM-dd');
        if (!map[key]) map[key] = [];
        map[key].push(t);
      } catch {}
    });
    return map;
  }, [filteredTasks]);

  const meetingsByDate = useMemo(() => {
    const map: Record<string, any[]> = {};
    meetings.forEach((m: any) => {
      if (!m.startTime) return;
      try {
        const key = format(parseISO(m.startTime), 'yyyy-MM-dd');
        if (!map[key]) map[key] = [];
        map[key].push(m);
      } catch {}
    });
    return map;
  }, [meetings]);

  const upcomingTasks = useMemo(() => {
    const now = new Date();
    const weekFromNow = addDays(now, 7);
    return filteredTasks
      .filter((t: any) => {
        if (!t.dueDate || t.status === 'done') return false;
        try {
          const d = parseISO(t.dueDate);
          return d >= now && d <= weekFromNow;
        } catch { return false; }
      })
      .sort((a: any, b: any) => a.dueDate.localeCompare(b.dueDate));
  }, [filteredTasks]);

  const overdueCount = useMemo(() => {
    return filteredTasks.filter((t: any) => t.status !== 'done' && isOverdue(t.dueDate)).length;
  }, [filteredTasks]);

  const thisWeekCount = useMemo(() => {
    const now = new Date();
    const weekEnd = addDays(now, 7);
    return filteredTasks.filter((t: any) => {
      if (!t.dueDate) return false;
      try {
        const d = parseISO(t.dueDate);
        return d >= now && d <= weekEnd;
      } catch { return false; }
    }).length;
  }, [filteredTasks]);

  const toggleProject = (id: string) => {
    setProjectFilter(prev =>
      prev.includes(id) ? prev.filter(p => p !== id) : [...prev, id]
    );
  };

  const handleDragEnd = useCallback(async (event: DragEndEvent) => {
    const { active, over } = event;
    setActiveTask(null);
    setOverDate(null);

    if (!over) return;

    const taskId = active.id as string;
    const newDateStr = over.id as string;
    const task = tasks.find((t: any) => t._id === taskId);
    if (!task) return;

    try {
      const newDate = parseISO(newDateStr);
      const oldDate = task.dueDate ? parseISO(task.dueDate) : null;
      if (oldDate && isSameDay(oldDate, newDate)) return;

      await updateTask(taskId, { dueDate: newDateStr });
      toast.success(`Moved "${task.title}" to ${format(newDate, 'MMM d')}`);
    } catch {
      toast.error('Failed to reschedule task');
    }
  }, [tasks, updateTask]);

  return (
    <div className="page flex flex-col h-[calc(100vh-80px)] relative z-10">
      {/* Header */}
      <div className="mb-6 flex shrink-0 flex-col gap-4 lg:flex-row lg:items-end lg:justify-between">
        <div>
          <h1 className="page-title mb-0">Calendar</h1>
          <p className="mt-1 text-sm font-medium" style={{ color: 'var(--color-muted)' }}>
            Drag tasks to reschedule. Visualize deadlines at a glance.
          </p>
        </div>

        <div className="flex items-center gap-3">
          <button
            onClick={() => setCurrentDate(new Date())}
            className="rounded-xl border px-4 py-2 text-[12px] font-semibold transition-all"
            style={{ borderColor: 'var(--color-border)', color: 'var(--color-accent)', background: 'var(--color-surface)' }}
          >
            Today
          </button>

          <div className="inline-flex items-center rounded-xl p-1" style={{ background: 'var(--color-surface-active)', border: '1px solid var(--color-border)' }}>
            <button onClick={() => setCurrentDate(d => subMonths(d, 1))} className="rounded-lg p-2 transition-colors" style={{ color: 'var(--color-muted)' }}>
              <ChevronLeft size={16} />
            </button>
            <span className="min-w-[140px] text-center text-[13px] font-bold uppercase tracking-wider" style={{ color: 'var(--color-foreground)' }}>
              {format(currentDate, 'MMMM yyyy')}
            </span>
            <button onClick={() => setCurrentDate(d => addMonths(d, 1))} className="rounded-lg p-2 transition-colors" style={{ color: 'var(--color-muted)' }}>
              <ChevronRight size={16} />
            </button>
          </div>
        </div>
      </div>

      {isLoading && <LoadingSpinner text="Loading calendar..." />}

      {!isLoading && error && <ErrorState message={error} onRetry={retry} />}

      {/* Main Layout */}
      {!isLoading && !error && (
      <DndContext
        sensors={sensors}
        onDragStart={(event) => {
          const task = (event.active.data.current as any)?.task;
          setActiveTask(task);
        }}
        onDragOver={(event) => {
          const overId = event.over?.id as string;
          setOverDate(overId || null);
        }}
        onDragEnd={handleDragEnd}
        onDragCancel={() => { setActiveTask(null); setOverDate(null); }}
      >
        <div className="flex flex-1 min-h-0 gap-5">
          {/* Calendar Grid */}
          <div className="flex-1 flex flex-col min-w-0">
            <div className="flex flex-1 flex-col rounded-2xl border overflow-hidden" style={{ background: 'var(--color-surface)', borderColor: 'var(--color-border)', boxShadow: 'var(--shadow-xs)' }}>
              {/* Day Headers */}
              <div className="grid grid-cols-7" style={{ borderBottom: '1px solid var(--color-border)' }}>
                {DAY_NAMES.map(d => (
                  <div key={d} className="py-3 text-center text-[11px] font-bold uppercase tracking-widest" style={{ color: 'var(--color-muted)' }}>
                    {d}
                  </div>
                ))}
              </div>

              {/* Day Cells */}
              <div className="flex-1 grid grid-cols-7" style={{ gridTemplateRows: `repeat(${totalWeeks}, 1fr)` }}>
                {days.map((day, i) => {
                  const dateKey = format(day, 'yyyy-MM-dd');
                  const dayTasks = tasksByDate[dateKey] || [];
                  const dayMeetings = meetingsByDate[dateKey] || [];
                  const inMonth = isSameMonth(day, currentDate);
                  const today = isToday(day);
                  const selected = selectedDay && isSameDay(day, selectedDay);

                  return (
                    <DroppableDayCell
                      key={i}
                      day={day}
                      currentDate={currentDate}
                      dayTasks={dayTasks}
                      dayMeetings={dayMeetings}
                      inMonth={inMonth}
                      today={today}
                      selected={selected}
                      onSelect={() => setSelectedDay(day)}
                      isOver={overDate === dateKey}
                    />
                  );
                })}
              </div>
            </div>
          </div>

          {/* Sidebar */}
          <div className="hidden w-[280px] shrink-0 flex-col gap-5 xl:flex">
            {/* Quick Stats */}
            <motion.div initial={{ opacity: 0, x: 10 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: 0.1 }}>
              <div className="rounded-2xl border p-4" style={{ background: 'var(--color-surface)', borderColor: 'var(--color-border)', boxShadow: 'var(--shadow-xs)' }}>
                <h3 className="mb-3 text-[11px] font-bold uppercase tracking-wider" style={{ color: 'var(--color-muted)' }}>Quick Stats</h3>
                <div className="grid grid-cols-2 gap-3">
                  <div className="rounded-xl p-3" style={{ background: 'var(--color-accent-light)' }}>
                    <div className="mb-1 flex items-center gap-1.5">
                      <CalendarIcon size={12} style={{ color: 'var(--color-accent)' }} />
                      <span className="text-[10px] font-semibold uppercase" style={{ color: 'var(--color-accent)' }}>This Week</span>
                    </div>
                    <div className="text-xl font-bold" style={{ color: 'var(--color-accent)' }}>{thisWeekCount}</div>
                  </div>

                  <div className="rounded-xl p-3" style={{ background: overdueCount > 0 ? 'var(--color-danger-light)' : 'var(--color-success-light)' }}>
                    <div className="mb-1 flex items-center gap-1.5">
                      <AlertTriangle size={12} style={{ color: overdueCount > 0 ? 'var(--color-danger)' : 'var(--color-success)' }} />
                      <span className="text-[10px] font-semibold uppercase" style={{ color: overdueCount > 0 ? 'var(--color-danger)' : 'var(--color-success)' }}>Overdue</span>
                    </div>
                    <div className="text-xl font-bold" style={{ color: overdueCount > 0 ? 'var(--color-danger)' : 'var(--color-success)' }}>{overdueCount}</div>
                  </div>
                </div>
              </div>
            </motion.div>

            {/* Upcoming Tasks */}
            <motion.div initial={{ opacity: 0, x: 10 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: 0.2 }} className="flex flex-1 flex-col min-h-0">
              <div className="flex flex-1 flex-col rounded-2xl border overflow-hidden" style={{ background: 'var(--color-surface)', borderColor: 'var(--color-border)', boxShadow: 'var(--shadow-xs)' }}>
                <div className="px-4 pt-4 pb-3" style={{ borderBottom: '1px solid var(--color-border-light)' }}>
                  <h3 className="text-[11px] font-bold uppercase tracking-wider" style={{ color: 'var(--color-muted)' }}>Upcoming &middot; Next 7 Days</h3>
                </div>
                <div className="flex-1 overflow-y-auto p-2" style={{ scrollbarWidth: 'thin' }}>
                  {upcomingTasks.length === 0 ? (
                    <div className="flex flex-col items-center justify-center py-8 text-center">
                      <CheckCircle2 size={24} style={{ color: 'var(--color-success)' }} className="mb-2" />
                      <p className="text-[12px] font-medium" style={{ color: 'var(--color-muted)' }}>All clear!</p>
                    </div>
                  ) : (
                    <div className="flex flex-col gap-1.5">
                      {upcomingTasks.map((task: any, i: number) => (
                        <motion.div
                          key={task._id}
                          initial={{ opacity: 0, y: 4 }}
                          animate={{ opacity: 1, y: 0 }}
                          transition={{ delay: i * 0.04 }}
                          className="flex items-start gap-2.5 rounded-xl p-2.5 transition-colors"
                          style={{ background: isOverdue(task.dueDate) ? 'var(--color-danger-light)' : 'transparent' }}
                        >
                          <span className="mt-1 h-2 w-2 rounded-full shrink-0" style={{ background: getPriorityDot(task.priority) }} />
                          <div className="flex-1 min-w-0">
                            <p className="text-[12px] font-medium truncate" style={{ color: 'var(--color-foreground)' }}>{task.title}</p>
                            <div className="mt-1 flex items-center gap-2">
                              <span className="text-[10px] font-semibold" style={{ color: isOverdue(task.dueDate) ? 'var(--color-danger)' : 'var(--color-muted)' }}>
                                {(() => { try { return format(parseISO(task.dueDate), 'MMM d'); } catch { return task.dueDate; } })()}
                              </span>
                              {task.assignee && <MemberAvatar memberId={task.assignee} />}
                            </div>
                          </div>
                        </motion.div>
                      ))}
                    </div>
                  )}
                </div>
              </div>
            </motion.div>

            {/* Project Filter */}
            <motion.div initial={{ opacity: 0, x: 10 }} animate={{ opacity: 1, x: 0 }} transition={{ delay: 0.3 }}>
              <div className="rounded-2xl border p-4" style={{ background: 'var(--color-surface)', borderColor: 'var(--color-border)', boxShadow: 'var(--shadow-xs)' }}>
                <h3 className="mb-3 text-[11px] font-bold uppercase tracking-wider" style={{ color: 'var(--color-muted)' }}>Filter by Project</h3>
                <div className="flex flex-col gap-2">
                  {projects.map((project: any) => (
                    <label
                      key={project._id}
                      className="flex cursor-pointer items-center gap-2.5 rounded-lg px-2 py-1.5 transition-colors"
                      style={{ background: projectFilter.includes(project._id) ? 'var(--color-surface-hover)' : 'transparent' }}
                    >
                      <input
                        type="checkbox"
                        checked={projectFilter.includes(project._id)}
                        onChange={() => toggleProject(project._id)}
                        className="h-3.5 w-3.5 rounded accent-current"
                        style={{ accentColor: project.color || 'var(--color-accent)' }}
                      />
                      <span className="h-2.5 w-2.5 rounded-full shrink-0" style={{ background: project.color || 'var(--color-accent)' }} />
                      <span className="text-[12px] font-medium" style={{ color: 'var(--color-foreground)' }}>{project.name}</span>
                    </label>
                  ))}
                  {projects.length === 0 && (
                    <p className="text-[12px]" style={{ color: 'var(--color-muted)' }}>No projects yet</p>
                  )}
                  {projectFilter.length > 0 && (
                    <button onClick={() => setProjectFilter([])} className="mt-1 text-[11px] font-semibold transition-colors" style={{ color: 'var(--color-accent)' }}>
                      Clear filter
                    </button>
                  )}
                </div>
              </div>
            </motion.div>
          </div>
        </div>

        <DragOverlay>
          {activeTask ? (
            <div
              className="flex items-center gap-1.5 rounded-md px-2 py-1.5 text-[10px] font-medium shadow-lg"
              style={{ background: 'var(--color-accent)', color: 'white', minWidth: 120 }}
            >
              <span className="h-1.5 w-1.5 rounded-full shrink-0" style={{ background: 'white' }} />
              <span className="truncate">{activeTask.title}</span>
            </div>
          ) : null}
        </DragOverlay>
      </DndContext>
      )}
    </div>
  );
}

import { useMemo, useState } from 'react';
import { zodResolver } from '@hookform/resolvers/zod';
import { getCountries, getCountryCallingCode, isValidPhoneNumber, parsePhoneNumberFromString, type CountryCode } from 'libphonenumber-js';
import { Loader2, Mail, MapPin, Phone } from 'lucide-react';
import { useForm } from 'react-hook-form';
import * as z from 'zod';
import toast from 'react-hot-toast';
import api from '../utils/api';

const formSchema = z.object({
  name: z.string().trim().min(2, 'Enter your name').max(80, 'Name is too long'),
  email: z.string().trim().email('Enter a valid email address'),
  country: z.string().length(2),
  phone: z.string().trim().min(1, 'Enter your phone number'),
  subject: z.string().trim().min(3, 'Enter a subject').max(120, 'Subject is too long'),
  message: z.string().trim().min(10, 'Message must be at least 10 characters').max(2000, 'Message is too long'),
});

type ContactFormValues = z.infer<typeof formSchema>;
type Country = CountryCode;

const flagFor = (country: Country) => country.replace(/./g, (letter) => String.fromCodePoint(letter.charCodeAt(0) + 127397));

export default function ContactPage() {
  const [isSubmitted, setIsSubmitted] = useState(false);
  const countries = useMemo(() => {
    const displayNames = new Intl.DisplayNames(['en'], { type: 'region' });
    return getCountries().map((country) => ({
      code: country,
      name: displayNames.of(country) || country,
      dialCode: `+${getCountryCallingCode(country)}`,
    })).sort((left, right) => left.name.localeCompare(right.name));
  }, []);
  const { register, handleSubmit, setError, clearErrors, reset, formState: { errors, isSubmitting } } = useForm<ContactFormValues>({
    resolver: zodResolver(formSchema as any) as any,
    defaultValues: { country: 'US' },
  });

  const onSubmit = async (values: ContactFormValues) => {
    const country = values.country as Country;
    if (!isValidPhoneNumber(values.phone, country)) {
      setError('phone', { type: 'validate', message: 'Enter a valid phone number for the selected country' });
      return;
    }
    const parsedPhone = parsePhoneNumberFromString(values.phone, country);
    if (!parsedPhone?.isValid()) {
      setError('phone', { type: 'validate', message: 'Enter a valid phone number for the selected country' });
      return;
    }

    try {
      await api.post('/contact', {
        name: values.name.trim(),
        email: values.email.trim().toLowerCase(),
        country,
        phoneNumber: parsedPhone.number,
        subject: values.subject.trim(),
        message: values.message.trim(),
      });
      setIsSubmitted(true);
      reset({ country: values.country });
      toast.success('Your message has been sent.');
    } catch (error: any) {
      toast.error(error.response?.data?.error || 'Unable to send your message. Please try again.');
    }
  };

  if (isSubmitted) {
    return <div className="page"><div className="contact-success card"><div className="contact-success-icon"><Mail size={28} /></div><h1 className="page-title">Message sent</h1><p className="contact-muted">Thanks for reaching out. Our team will get back to you shortly.</p><button type="button" className="btn-primary contact-success-button" onClick={() => setIsSubmitted(false)}>Send another message</button></div></div>;
  }

  return <div className="page"><div className="contact-header"><p className="contact-eyebrow">WeΓÇÖre here to help</p><h1 className="page-title">Contact Us</h1><p className="contact-muted">Tell us what you need and weΓÇÖll get back to you as soon as possible.</p></div><div className="contact-layout"><aside className="contact-details card"><h2 className="contact-section-title">Get in touch</h2><p className="contact-muted">Whether you have a question, feedback, or need help with TaMaD, our team is ready to help.</p><div className="contact-detail-item"><Mail size={18} /><div><strong>Email</strong><span>support@tamad.app</span></div></div><div className="contact-detail-item"><Phone size={18} /><div><strong>Phone</strong><span>MonΓÇôFri, 9:00ΓÇô18:00 UTC</span></div></div><div className="contact-detail-item"><MapPin size={18} /><div><strong>Response time</strong><span>Usually within one business day</span></div></div></aside><form className="contact-form card" onSubmit={handleSubmit(onSubmit)} noValidate><div className="contact-form-grid"><div className="contact-field"><label htmlFor="contact-name">Full name</label><input id="contact-name" {...register('name', { onChange: () => clearErrors('name') })} className="input-field" autoComplete="name" />{errors.name && <p className="contact-error" role="alert">{errors.name.message}</p>}</div><div className="contact-field"><label htmlFor="contact-email">Email</label><input id="contact-email" {...register('email', { onChange: () => clearErrors('email') })} type="email" className="input-field" autoComplete="email" />{errors.email && <p className="contact-error" role="alert">{errors.email.message}</p>}</div></div><div className="contact-field"><label htmlFor="contact-country">Country</label><select id="contact-country" {...register('country', { onChange: () => clearErrors('phone') })} className="input-field contact-country-select" aria-describedby="contact-country-help">{countries.map((country) => <option key={country.code} value={country.code}>{flagFor(country.code)} {country.name} ({country.dialCode})</option>)}</select><span id="contact-country-help" className="contact-help">Select your country so we can validate and format your number correctly.</span></div><div className="contact-field"><label htmlFor="contact-phone">Phone number</label><input id="contact-phone" {...register('phone', { onChange: (event) => { event.target.value = event.target.value.replace(/[^\d\s().-]/g, ''); clearErrors('phone'); } })} type="tel" className="input-field" autoComplete="tel" inputMode="tel" />{errors.phone && <p className="contact-error" role="alert">{errors.phone.message}</p>}</div><div className="contact-field"><label htmlFor="contact-subject">Subject</label><input id="contact-subject" {...register('subject', { onChange: () => clearErrors('subject') })} className="input-field" />{errors.subject && <p className="contact-error" role="alert">{errors.subject.message}</p>}</div><div className="contact-field"><label htmlFor="contact-message">Message</label><textarea id="contact-message" {...register('message', { onChange: () => clearErrors('message') })} className="input-field contact-message" rows={6} />{errors.message && <p className="contact-error" role="alert">{errors.message.message}</p>}</div><button type="submit" disabled={isSubmitting} className="btn-primary contact-submit">{isSubmitting ? <Loader2 className="animate-spin" size={20} /> : 'Send message'}</button></form></div></div>;
}

import { useState, useMemo, useEffect } from 'react';
import { motion } from 'framer-motion';
import {
  CheckCircle2, Clock, AlertTriangle, ArrowUpRight, ArrowDownRight,
  LayoutGrid, Filter, AlertCircle, X, Inbox, FolderKanban, Activity,
} from 'lucide-react';
import {
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
} from 'recharts';
import { format, subDays, startOfWeek, endOfWeek } from 'date-fns';
import { useNavigate } from 'react-router-dom';
import { useAuthStore } from '../store/authStore';
import { useTaskStore } from '../store/taskStore';
import { useProjectStore } from '../store/projectStore';
import { EmptyState } from '../components/ui/EmptyState';
import LoadingSpinner from '../components/ui/LoadingSpinner';
import { SkeletonTable } from '../components/ui/Skeleton';
import { staggerContainer, cardVariant } from '../lib/animations';
import TeamDashboardPage from './TeamDashboardPage';
import clsx from 'clsx';

const STATUS_TABS = [
  { key: 'all', label: 'All Tasks' },
  { key: 'urgent', label: 'High Priority' },
  { key: 'today', label: 'Due Today' },
  { key: 'in-progress', label: 'In Progress' },
] as const;

const getPriorityColor = (priority: string) => {
  switch (priority) {
    case 'urgent': return { bg: '#fee2e2', text: '#dc2626', dot: '#ef4444' };
    case 'high': return { bg: '#fef3c7', text: '#d97706', dot: '#f59e0b' };
    case 'medium': return { bg: '#dbeafe', text: '#2563eb', dot: '#2563eb' };
    case 'low': return { bg: '#f1f5f9', text: '#64748b', dot: '#94a3b8' };
    default: return { bg: '#f1f5f9', text: '#64748b', dot: '#94a3b8' };
  }
};

const statusColors: Record<string, { bg: string; text: string }> = {
  'todo': { bg: 'var(--color-surface-active)', text: 'var(--color-muted)' },
  'in-progress': { bg: 'var(--color-accent-light)', text: 'var(--color-accent)' },
  'review': { bg: 'var(--color-warning-light)', text: 'var(--color-warning)' },
  'done': { bg: 'var(--color-success-light)', text: 'var(--color-success)' },
};

function useAuthName() {
  const user = useAuthStore(s => s.user);
  return user?.name?.split(' ')[0] || 'there';
}

export default function DashboardPage() {
  const navigate = useNavigate();
  const workspace = useAuthStore(s => s.workspace);
  const user = useAuthStore(s => s.user);
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [emailBannerDismissed, setEmailBannerDismissed] = useState(() => {
    if (user?.id) {
      return localStorage.getItem(`email_verify_dismissed_${user.id}`) === 'true';
    }
    return false;
  });
  const { tasks, loading: tasksLoading, fetchTasks } = useTaskStore();
  const { projects, loading: projectsLoading, fetchProjects } = useProjectStore();
  const workspaceId = workspace?._id || '';
  const today = format(new Date(), 'yyyy-MM-dd');

  useEffect(() => {
    if (workspaceId) {
      fetchTasks(workspaceId);
      fetchProjects(workspaceId);
    }
  }, [workspaceId, fetchTasks, fetchProjects]);

  const filteredTasks = useMemo(() => {
    switch (statusFilter) {
      case 'urgent': return tasks.filter(t => t.priority === 'urgent' || t.priority === 'high');
      case 'today': return tasks.filter(t => t.dueDate === today);
      case 'in-progress': return tasks.filter(t => t.status === 'in-progress');
      default: return tasks;
    }
  }, [statusFilter, today, tasks]);

  const totalTasks = tasks.length;
  const completedTasks = tasks.filter(t => t.status === 'done').length;
  const inProgressTasks = tasks.filter(t => t.status === 'in-progress').length;
  const overdueTasks = tasks.filter(t => t.dueDate && t.dueDate < today && t.status !== 'done').length;
  const completionRate = totalTasks > 0 ? Math.round((completedTasks / totalTasks) * 100) : 0;

  const weeklyData = useMemo(() => {
    const days = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
    const weekStart = startOfWeek(new Date(), { weekStartsOn: 1 });
    const weekEnd = endOfWeek(new Date(), { weekStartsOn: 1 });
    return days.slice(1).map(day => {
      const dayTasks = tasks.filter(t => {
        if (!t.createdAt) return false;
        const created = new Date(t.createdAt);
        return created >= weekStart && created <= weekEnd &&
          created.toLocaleDateString('en-US', { weekday: 'short' }) === day;
      });
      const completedDayTasks = tasks.filter(t => {
        if (!t.updatedAt || t.status !== 'done') return false;
        const updated = new Date(t.updatedAt);
        return updated >= weekStart && updated <= weekEnd &&
          updated.toLocaleDateString('en-US', { weekday: 'short' }) === day;
      });
      return { day, completed: completedDayTasks.length, created: dayTasks.length };
    });
  }, [tasks]);

  const stats = [
    { label: 'Total Tasks', value: totalTasks, icon: LayoutGrid, change: `${tasks.length} total`, up: true, color: 'var(--color-accent)', bg: 'var(--color-accent-light)' },
    { label: 'Completed', value: completedTasks, icon: CheckCircle2, change: `${completionRate}% rate`, up: true, color: 'var(--color-success)', bg: 'var(--color-success-light)' },
    { label: 'In Progress', value: inProgressTasks, icon: Clock, change: 'Active now', up: true, color: 'var(--color-info)', bg: 'var(--color-info-light)' },
    { label: 'Overdue', value: overdueTasks, icon: AlertTriangle, change: overdueTasks > 0 ? 'Needs attention' : 'All clear', up: false, color: 'var(--color-danger)', bg: 'var(--color-danger-light)' },
  ];

  const recentTasks = filteredTasks.slice(0, 6);

  const recentActivities = useMemo(() => {
    return [...tasks]
      .sort((a, b) => new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime())
      .slice(0, 6);
  }, [tasks]);

  const handleDismissEmailBanner = () => {
    if (user?.id) {
      localStorage.setItem(`email_verify_dismissed_${user.id}`, 'true');
    }
    setEmailBannerDismissed(true);
  };

  const showEmailBanner = user && user.emailVerified === false && user.authProvider === 'email' && !emailBannerDismissed;

  if (workspace?.type === 'team') {
    return <TeamDashboardPage />;
  }

  return (
    <div className="page">
      {/* Email verification banner */}
      {showEmailBanner && (
        <div
          className="mb-6 flex items-center justify-between gap-4 rounded-xl px-4 py-3"
          style={{
            background: 'var(--color-warning-light)',
            border: '1px solid var(--color-warning)',
          }}
        >
          <div className="flex items-center gap-3">
            <AlertCircle size={18} style={{ color: 'var(--color-warning)' }} />
            <span className="text-sm font-semibold" style={{ color: 'var(--color-warning)' }}>
              Please verify your email address
            </span>
          </div>
          <div className="flex items-center gap-2">
            <button
              onClick={() => navigate('/verify-email')}
              className="rounded-lg px-3 py-1.5 text-xs font-bold transition-colors"
              style={{
                background: 'var(--color-warning)',
                color: 'white',
              }}
            >
              Verify Now
            </button>
            <button
              onClick={handleDismissEmailBanner}
              className="rounded-lg p-1 transition-colors"
              style={{ color: 'var(--color-warning)' }}
              aria-label="Dismiss"
            >
              <X size={16} />
            </button>
          </div>
        </div>
      )}

      {/* Header */}
      <div className="page-header flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between">
        <div>
          <p className="mb-1 text-xs font-bold uppercase tracking-[0.2em]" style={{ color: 'var(--color-muted)' }}>
            {format(new Date(), 'EEEE, MMMM d, yyyy')}
          </p>
          <h1 className="page-title">
            Good {new Date().getHours() < 12 ? 'morning' : new Date().getHours() < 18 ? 'afternoon' : 'evening'}, {useAuthName()}
          </h1>
          <p className="page-subtitle mt-1">Here's what's happening across your workspace.</p>
        </div>
      </div>

      {/* Status filter pills */}
      <div className="mb-6 flex items-center gap-2 overflow-x-auto pb-2">
        <Filter size={14} style={{ color: 'var(--color-muted)' }} className="shrink-0" />
        {STATUS_TABS.map(tab => {
          const count = tab.key === 'all' ? totalTasks
            : tab.key === 'urgent' ? tasks.filter(t => t.priority === 'urgent' || t.priority === 'high').length
            : tab.key === 'today' ? tasks.filter(t => t.dueDate === today).length
            : tasks.filter(t => t.status === 'in-progress').length;
          return (
            <button
              key={tab.key}
              onClick={() => setStatusFilter(tab.key)}
              className={clsx(
                'shrink-0 rounded-full border px-3.5 py-1.5 text-xs font-semibold transition-all',
              )}
              style={{
                background: statusFilter === tab.key ? 'var(--color-accent-light)' : 'var(--color-surface)',
                borderColor: statusFilter === tab.key ? 'var(--color-accent)' : 'var(--color-border)',
                color: statusFilter === tab.key ? 'var(--color-accent)' : 'var(--color-muted)',
              }}
            >
              {tab.label}
              <span className="ml-1.5 rounded-full px-1.5 py-0.5 text-[10px]" style={{ background: statusFilter === tab.key ? 'var(--color-accent)' : 'var(--color-surface-active)', color: statusFilter === tab.key ? 'white' : 'var(--color-muted)' }}>
                {count}
              </span>
            </button>
          );
        })}
      </div>

      {/* Stat cards */}
      <div className="mb-6 grid gap-4 sm:grid-cols-2 xl:grid-cols-4">
        {stats.map((stat, i) => {
          const Icon = stat.icon;
          return (
            <motion.div key={stat.label} custom={i} initial="hidden" animate="visible" variants={cardVariant}>
              <div className="stat-card">
                <div className="mb-3 flex items-center justify-between">
                  <span className="text-xs font-bold uppercase tracking-wider" style={{ color: 'var(--color-muted)' }}>{stat.label}</span>
                  <div className="flex h-9 w-9 items-center justify-center rounded-xl" style={{ background: stat.bg, color: stat.color }}>
                    <Icon size={18} />
                  </div>
                </div>
                <div className="text-3xl font-bold tracking-tight" style={{ color: 'var(--color-foreground)' }}>{stat.value}</div>
                <div className="mt-2 flex items-center gap-1 text-xs font-medium" style={{ color: stat.up ? 'var(--color-success)' : 'var(--color-danger)' }}>
                  {stat.up ? <ArrowUpRight size={14} /> : <ArrowDownRight size={14} />}
                  {stat.change}
                </div>
              </div>
            </motion.div>
          );
        })}
      </div>

      {/* Main grid */}
      <div className="grid gap-6 xl:grid-cols-3">
        {/* Left: chart + tasks */}
        <div className="space-y-6 xl:col-span-2">
          {/* Weekly chart */}
          <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.25 }}>
            <div className="card p-5">
              <div className="mb-5 flex items-center justify-between">
                <div>
                  <h2 className="text-base font-bold" style={{ color: 'var(--color-foreground)' }}>Weekly Productivity</h2>
                  <p className="mt-0.5 text-xs" style={{ color: 'var(--color-muted)' }}>Tasks completed vs created this week</p>
                </div>
                <div className="flex items-center gap-4 text-xs font-medium">
                  <span className="flex items-center gap-1.5"><span className="inline-block h-2.5 w-2.5 rounded-sm" style={{ background: 'var(--color-accent)' }} /> Completed</span>
                  <span className="flex items-center gap-1.5"><span className="inline-block h-2.5 w-2.5 rounded-sm" style={{ background: 'var(--color-border)' }} /> Created</span>
                </div>
              </div>
              <div className="h-64">
                {tasksLoading ? (
                  <div className="flex h-full items-center justify-center">
                    <LoadingSpinner size={24} />
                  </div>
                ) : (
                  <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={weeklyData} barGap={4}>
                      <CartesianGrid strokeDasharray="3 3" stroke="var(--color-border-light)" vertical={false} />
                      <XAxis dataKey="day" tick={{ fontSize: 12, fill: 'var(--color-muted)' }} axisLine={false} tickLine={false} />
                      <YAxis tick={{ fontSize: 12, fill: 'var(--color-muted)' }} axisLine={false} tickLine={false} />
                      <Tooltip
                        contentStyle={{
                          background: 'var(--color-surface)', border: '1px solid var(--color-border)',
                          borderRadius: 8, boxShadow: '0 4px 12px rgba(0,0,0,0.1)', fontSize: 13,
                        }}
                      />
                      <Bar dataKey="completed" fill="var(--color-accent)" radius={[4, 4, 0, 0]} />
                      <Bar dataKey="created" fill="var(--color-border)" radius={[4, 4, 0, 0]} />
                    </BarChart>
                  </ResponsiveContainer>
                )}
              </div>
            </div>
          </motion.div>

          {/* Recent tasks */}
          <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.35 }}>
            <div className="card">
              <div className="card-header">
                <div>
                  <h2 className="text-base font-bold" style={{ color: 'var(--color-foreground)' }}>Recent Tasks</h2>
                  <p className="mt-0.5 text-xs" style={{ color: 'var(--color-muted)' }}>Latest activity across your workspace</p>
                </div>
                <button
                  onClick={() => navigate('/tasks')}
                  className="text-xs font-semibold transition-colors"
                  style={{ color: 'var(--color-accent)' }}
                >
                  View all
                </button>
              </div>
              <div className="overflow-x-auto">
                {tasksLoading ? (
                  <div className="p-6">
                    <SkeletonTable rows={5} cols={4} />
                  </div>
                ) : recentTasks.length === 0 ? (
                  <EmptyState
                    icon={Inbox}
                    title="No tasks yet"
                    description="Create your first task to get started"
                    action={{ label: 'Create Task', onClick: () => navigate('/tasks') }}
                  />
                ) : (
                  <table>
                    <thead>
                      <tr>
                        <th>Task</th>
                        <th>Status</th>
                        <th>Priority</th>
                        <th>Due</th>
                      </tr>
                    </thead>
                    <tbody>
                      {recentTasks.map(task => {
                        const pColor = getPriorityColor(task.priority);
                        const sc = statusColors[task.status] || statusColors.todo;
                        const isOverdue = task.dueDate && task.dueDate < today && task.status !== 'done';
                        return (
                          <tr key={task._id}>
                            <td>
                              <div className="flex items-center gap-3">
                                <div className="h-2 w-2 shrink-0 rounded-full" style={{ background: pColor.dot }} />
                                <div>
                                  <p className="font-medium" style={{ color: 'var(--color-foreground)' }}>{task.title}</p>
                                  {task.tags && task.tags.length > 0 && (
                                    <p className="text-xs" style={{ color: 'var(--color-muted)' }}>{task.tags[0].name}</p>
                                  )}
                                </div>
                              </div>
                            </td>
                            <td>
                              <span className="badge" style={{ background: sc.bg, color: sc.text }}>
                                {task.status.replace('-', ' ')}
                              </span>
                            </td>
                            <td>
                              <span className="badge" style={{ background: pColor.bg, color: pColor.text }}>
                                {task.priority}
                              </span>
                            </td>
                            <td>
                              <span className={clsx('text-xs font-medium', isOverdue && 'font-bold')} style={{ color: isOverdue ? 'var(--color-danger)' : 'var(--color-muted)' }}>
                                {!task.dueDate ? 'No date' : task.dueDate === today ? 'Today' : task.dueDate < today ? 'Overdue' : task.dueDate}
                              </span>
                            </td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
                )}
              </div>
            </div>
          </motion.div>
        </div>

        {/* Right: projects + activity */}
        <div className="space-y-6">
          {/* Active projects */}
          <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.3 }}>
            <div className="card p-5">
              <div className="mb-4 flex items-center justify-between">
                <h2 className="text-base font-bold" style={{ color: 'var(--color-foreground)' }}>Active Projects</h2>
                <button
                  onClick={() => navigate('/projects')}
                  className="text-xs font-semibold transition-colors"
                  style={{ color: 'var(--color-accent)' }}
                >
                  View all
                </button>
              </div>
              {projectsLoading ? (
                <div className="flex items-center justify-center py-8">
                  <LoadingSpinner size={16} />
                </div>
              ) : projects.length === 0 ? (
                <EmptyState
                  icon={FolderKanban}
                  title="No projects yet"
                  description="Create your first project to get started"
                  action={{ label: 'Create Project', onClick: () => navigate('/projects') }}
                />
              ) : (
                <div className="space-y-4">
                  {projects.slice(0, 4).map(project => (
                    <div key={project._id} className="group cursor-pointer rounded-lg p-3 transition-all" style={{ background: 'var(--color-background)' }}>
                      <div className="flex items-center gap-3 mb-2">
                        <div className="h-3 w-3 shrink-0 rounded-full" style={{ background: project.color }} />
                        <span className="text-sm font-semibold truncate" style={{ color: 'var(--color-foreground)' }}>{project.name}</span>
                      </div>
                      {project.description && (
                        <p className="text-xs mb-2 truncate" style={{ color: 'var(--color-muted)' }}>{project.description}</p>
                      )}
                    </div>
                  ))}
                </div>
              )}
            </div>
          </motion.div>

          {/* Recent activity */}
          <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.4 }}>
            <div className="card p-5">
              <div className="mb-4">
                <h2 className="text-base font-bold" style={{ color: 'var(--color-foreground)' }}>Recent Activity</h2>
                <p className="mt-0.5 text-xs" style={{ color: 'var(--color-muted)' }}>Latest changes in your workspace</p>
              </div>
              <div className="space-y-3">
                {recentActivities.length === 0 ? (
                  <EmptyState
                    icon={Activity}
                    title="No recent activity"
                    description="Start working on tasks to see activity here"
                  />
                ) : (
                  recentActivities.map(task => (
                    <div key={task._id} className="flex items-start gap-3 rounded-lg p-2 transition-colors" style={{ background: 'var(--color-background)' }}>
                      <div className="avatar avatar-sm shrink-0" style={{ background: getPriorityColor(task.priority).dot, color: 'white' }}>
                        {task.title.charAt(0).toUpperCase()}
                      </div>
                      <div className="min-w-0 flex-1">
                        <p className="text-xs leading-relaxed" style={{ color: 'var(--color-foreground)' }}>
                          <span className="font-medium" style={{ color: 'var(--color-accent)' }}>{task.title}</span>
                        </p>
                        <p className="mt-0.5 text-[11px]" style={{ color: 'var(--color-muted)' }}>
                          {task.status.replace('-', ' ')} &middot; {format(new Date(task.updatedAt), 'MMM d, h:mm a')}
                        </p>
                      </div>
                    </div>
                  ))
                )}
              </div>
            </div>
          </motion.div>
        </div>
      </div>
    </div>
  );
}

import { useState, useMemo, useEffect, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  FileText, Plus, Search, SortAsc, SortDesc, Trash2, Archive,
  ArchiveRestore, Edit3, Clock, Inbox, Filter, MoreVertical,
} from 'lucide-react';
import clsx from 'clsx';
import { useDocumentStore } from '../store/documentStore';
import { useAuthStore } from '../store/authStore';
import { Button } from '../components/ui/Button';
import { Input } from '../components/ui/Input';

type SortField = 'title' | 'updatedAt' | 'createdAt';

export default function DocumentsPage() {
  const workspace = useAuthStore(s => s.workspace);
  const workspaceId = workspace?._id || '';
  const {
    documents, loading, searchQuery, sortBy, sortDir,
    fetchDocuments, createDocument, deleteDocument, archiveDocument,
    setSearchQuery, setSortBy, toggleSortDir,
  } = useDocumentStore();

  const [showArchived, setShowArchived] = useState(false);
  const [activeMenu, setActiveMenu] = useState<string | null>(null);
  const [creating, setCreating] = useState(false);

  useEffect(() => {
    if (workspaceId) fetchDocuments(workspaceId);
  }, [workspaceId, fetchDocuments]);

  const filteredDocuments = useMemo(() => {
    let docs = showArchived
      ? documents
      : documents.filter(d => !d.isArchived);

    if (searchQuery) {
      const q = searchQuery.toLowerCase();
      docs = docs.filter(d =>
        d.title.toLowerCase().includes(q) ||
        d.content?.toLowerCase().includes(q)
      );
    }

    docs.sort((a, b) => {
      const aVal = a[sortBy] || '';
      const bVal = b[sortBy] || '';
      const cmp = String(aVal).localeCompare(String(bVal));
      return sortDir === 'asc' ? cmp : -cmp;
    });

    return docs;
  }, [documents, searchQuery, sortBy, sortDir, showArchived]);

  const archivedCount = useMemo(() => documents.filter(d => d.isArchived).length, [documents]);

  const handleCreate = useCallback(async () => {
    if (!workspaceId) return;
    setCreating(true);
    try {
      await createDocument({ title: 'Untitled Document', content: '', workspaceId });
    } finally {
      setCreating(false);
    }
  }, [workspaceId, createDocument]);

  const formatDate = (dateStr: string) => {
    const date = new Date(dateStr);
    const now = new Date();
    const diffMs = now.getTime() - date.getTime();
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMs / 3600000);
    const diffDays = Math.floor(diffMs / 86400000);
    if (diffMins < 1) return 'Just now';
    if (diffMins < 60) return `${diffMins}m ago`;
    if (diffHours < 24) return `${diffHours}h ago`;
    if (diffDays < 7) return `${diffDays}d ago`;
    return date.toLocaleDateString();
  };

  return (
    <div className="page" style={{ padding: '0 32px 40px' }}>
      <div className="mb-8 flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between">
        <div>
          <p className="mb-2 text-sm font-semibold uppercase tracking-[0.24em]" style={{ color: 'var(--color-muted)' }}>
            Knowledge base
          </p>
          <h1 className="page-title">Documents</h1>
          <p className="page-subtitle">
            Create, organize, and collaborate on documents.
          </p>
        </div>
        <Button onClick={handleCreate} disabled={creating} className="btn-primary">
          <Plus size={16} />
          New Document
        </Button>
      </div>

      <div className="mb-6 flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
        <div className="relative flex-1 max-w-md">
          <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2" style={{ color: 'var(--color-muted)' }} />
          <input
            type="text"
            placeholder="Search documents..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="input pl-9"
          />
        </div>
        <div className="flex items-center gap-3">
          <button
            onClick={() => setShowArchived(!showArchived)}
            className={clsx('btn btn-sm', showArchived ? 'btn-primary' : 'btn-ghost')}
          >
            <Archive size={14} />
            Archived {archivedCount > 0 && `(${archivedCount})`}
          </button>
          <button onClick={toggleSortDir} className="btn btn-ghost btn-sm" title="Toggle sort">
            {sortDir === 'asc' ? <SortAsc size={16} /> : <SortDesc size={16} />}
          </button>
          <select
            value={sortBy}
            onChange={(e) => setSortBy(e.target.value as SortField)}
            className="input text-sm"
            style={{ width: 'auto' }}
          >
            <option value="updatedAt">Last modified</option>
            <option value="createdAt">Created</option>
            <option value="title">Title</option>
          </select>
        </div>
      </div>

      <AnimatePresence mode="popLayout">
        {loading ? (
          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
            {[1, 2, 3, 4, 5, 6].map(i => (
              <div key={i} className="skeleton h-48 rounded-xl" />
            ))}
          </div>
        ) : filteredDocuments.length === 0 ? (
          <motion.div
            key="empty"
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            className="empty-state"
          >
            <div className="empty-state-icon">
              <FileText size={32} />
            </div>
            <p className="empty-state-title">
              {searchQuery ? 'No matching documents' : showArchived ? 'No archived documents' : 'No documents yet'}
            </p>
            <p className="empty-state-description">
              {searchQuery
                ? 'Try adjusting your search terms.'
                : 'Create your first document to get started.'}
            </p>
            {!searchQuery && (
              <Button onClick={handleCreate} className="btn-primary mt-4">
                <Plus size={16} />
                Create Document
              </Button>
            )}
          </motion.div>
        ) : (
          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
            {filteredDocuments.map((doc, index) => (
              <motion.div
                key={doc._id}
                layout
                initial={{ opacity: 0, y: 8 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, scale: 0.95 }}
                transition={{ delay: index * 0.03 }}
                className={clsx(
                  'group relative rounded-xl border p-5 transition-all hover:shadow-soft',
                  doc.isArchived && 'opacity-60'
                )}
                style={{
                  background: 'var(--color-surface)',
                  borderColor: 'var(--color-border)',
                }}
              >
                <div className="mb-3 flex items-start justify-between">
                  <div className="flex items-center gap-3 min-w-0 flex-1">
                    <div
                      className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl"
                      style={{ background: 'var(--color-accent-light)', color: 'var(--color-accent)' }}
                    >
                      <FileText size={18} />
                    </div>
                    <div className="min-w-0 flex-1">
                      <h3 className="truncate text-sm font-semibold" style={{ color: 'var(--color-foreground)' }}>
                        {doc.title}
                      </h3>
                    </div>
                  </div>
                  <div className="relative">
                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        setActiveMenu(activeMenu === doc._id ? null : doc._id);
                      }}
                      className="rounded-lg p-1.5 opacity-0 transition-all group-hover:opacity-100 hover:bg-[var(--color-surface-active)]"
                      style={{ color: 'var(--color-muted)' }}
                    >
                      <MoreVertical size={16} />
                    </button>
                    {activeMenu === doc._id && (
                      <div
                        className="absolute right-0 top-8 z-50 min-w-[160px] rounded-xl border py-1 shadow-float"
                        style={{ background: 'var(--color-surface)', borderColor: 'var(--color-border)' }}
                      >
                        <button
                          onClick={() => { archiveDocument(doc._id); setActiveMenu(null); }}
                          className="flex w-full items-center gap-2 px-3 py-2 text-sm hover:bg-[var(--color-surface-active)]"
                          style={{ color: 'var(--color-foreground)' }}
                        >
                          {doc.isArchived ? <ArchiveRestore size={14} /> : <Archive size={14} />}
                          {doc.isArchived ? 'Restore' : 'Archive'}
                        </button>
                        <button
                          onClick={() => { deleteDocument(doc._id); setActiveMenu(null); }}
                          className="flex w-full items-center gap-2 px-3 py-2 text-sm hover:bg-red-50"
                          style={{ color: 'var(--color-danger)' }}
                        >
                          <Trash2 size={14} />
                          Delete
                        </button>
                      </div>
                    )}
                  </div>
                </div>

                <p className="mb-4 line-clamp-3 text-sm leading-relaxed" style={{ color: 'var(--color-muted)' }}>
                  {doc.content
                    ? doc.content.replace(/[#*_`~\[\]]/g, '').slice(0, 150) + (doc.content.length > 150 ? '...' : '')
                    : 'Empty document'}
                </p>

                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-1.5 text-xs" style={{ color: 'var(--color-muted)', opacity: 0.7 }}>
                    <Clock size={12} />
                    {formatDate(doc.updatedAt)}
                  </div>
                  {doc.tags && doc.tags.length > 0 && (
                    <div className="flex gap-1">
                      {doc.tags.slice(0, 2).map(tag => (
                        <span
                          key={tag._id}
                          className="rounded-full px-2 py-0.5 text-[10px] font-medium"
                          style={{ background: tag.color + '20', color: tag.color }}
                        >
                          {tag.name}
                        </span>
                      ))}
                    </div>
                  )}
                </div>

                {doc.isArchived && (
                  <div
                    className="absolute left-3 top-3 rounded-full px-2 py-0.5 text-[10px] font-bold uppercase"
                    style={{ background: 'var(--color-warning-light)', color: 'var(--color-warning)' }}
                  >
                    Archived
                  </div>
                )}
              </motion.div>
            ))}
          </div>
        )}
      </AnimatePresence>
    </div>
  );
}

import { useState, useEffect, useCallback, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Upload, Search, Grid3X3, List, ArrowUpDown, Trash2, Archive,
  RotateCcw, Eye, Download, FolderOpen, Image, FileText, File,
  Film, Music, ArchiveIcon, HardDrive, Folder, ChevronDown,
  X, Loader2, Plus, Filter,
} from 'lucide-react';
import clsx from 'clsx';
import { useFileStore } from '../store/fileStore';
import { useAuthStore } from '../store/authStore';
import { useFileUpload, formatFileSize } from '../hooks/useFileUpload';
import FileUpload from '../components/ui/FileUpload';

const FILE_ICONS: Record<string, typeof File> = {
  image: Image,
  pdf: FileText,
  doc: FileText,
  xls: FileText,
  ppt: FileText,
  video: Film,
  audio: Music,
  archive: ArchiveIcon,
  file: File,
};

function getFileIconComponent(mimeType: string) {
  if (mimeType.startsWith('image/')) return Image;
  if (mimeType.includes('pdf')) return FileText;
  if (mimeType.startsWith('video/')) return Film;
  if (mimeType.startsWith('audio/')) return Music;
  if (mimeType.includes('zip') || mimeType.includes('rar') || mimeType.includes('tar')) return ArchiveIcon;
  if (mimeType.includes('word') || mimeType.includes('document')) return FileText;
  if (mimeType.includes('sheet') || mimeType.includes('excel')) return FileText;
  return File;
}

function formatDate(dateStr: string) {
  const d = new Date(dateStr);
  const now = new Date();
  const diffMs = now.getTime() - d.getTime();
  const diffMins = Math.floor(diffMs / 60000);
  if (diffMins < 1) return 'Just now';
  if (diffMins < 60) return `${diffMins}m ago`;
  const diffHrs = Math.floor(diffMins / 60);
  if (diffHrs < 24) return `${diffHrs}h ago`;
  const diffDays = Math.floor(diffHrs / 24);
  if (diffDays < 7) return `${diffDays}d ago`;
  return d.toLocaleDateString();
}

export default function FilesPage() {
  const workspace = useAuthStore(s => s.workspace);
  const workspaceId = workspace?._id || '';
  const {
    files, stats, loading, searchQuery, sortBy, sortDir, showArchived,
    setSearchQuery, setSortBy, toggleSortDir, toggleShowArchived,
    fetchFiles, createFileMetadata, archiveFile, restoreFile, deleteFile, fetchStats,
  } = useFileStore();
  const { uploadFile } = useFileUpload();

  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');
  const [showUploadModal, setShowUploadModal] = useState(false);
  const [previewFile, setPreviewFile] = useState<any>(null);
  const [dragOver, setDragOver] = useState(false);
  const dropRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (workspaceId) {
      fetchFiles(workspaceId);
      fetchStats(workspaceId);
    }
  }, [workspaceId, searchQuery, sortBy, sortDir, showArchived]);

  const handleQuickUpload = useCallback(async (e: React.ChangeEvent<HTMLInputElement>) => {
    const fileList = e.target.files;
    if (!fileList || fileList.length === 0 || !workspaceId) return;

    for (const file of Array.from(fileList)) {
      try {
        const timestamp = Date.now();
        const storagePath = `workspaces/${workspaceId}/files/${timestamp}_${file.name}`;
        const url = await uploadFile(file, storagePath);
        await createFileMetadata({
          originalName: file.name,
          fileName: `${timestamp}_${file.name}`,
          mimeType: file.type,
          size: file.size,
          url,
          storagePath,
          workspaceId,
        });
      } catch {}
    }

    fetchFiles(workspaceId);
    fetchStats(workspaceId);
    e.target.value = '';
  }, [workspaceId, uploadFile, createFileMetadata, fetchFiles, fetchStats]);

  const handleDrop = useCallback(async (e: React.DragEvent) => {
    e.preventDefault();
    setDragOver(false);
    if (!workspaceId) return;

    const fileList = e.dataTransfer.files;
    for (const file of Array.from(fileList)) {
      try {
        const timestamp = Date.now();
        const storagePath = `workspaces/${workspaceId}/files/${timestamp}_${file.name}`;
        const url = await uploadFile(file, storagePath);
        await createFileMetadata({
          originalName: file.name,
          fileName: `${timestamp}_${file.name}`,
          mimeType: file.type,
          size: file.size,
          url,
          storagePath,
          workspaceId,
        });
      } catch {}
    }

    fetchFiles(workspaceId);
    fetchStats(workspaceId);
  }, [workspaceId, uploadFile, createFileMetadata, fetchFiles, fetchStats]);

  const handleUploadComplete = useCallback(async (urls: string[]) => {
    setShowUploadModal(false);
    fetchFiles(workspaceId);
    fetchStats(workspaceId);
  }, [workspaceId, fetchFiles, fetchStats]);

  const handleDelete = useCallback(async (id: string) => {
    if (!confirm('Delete this file permanently?')) return;
    await deleteFile(id);
    fetchStats(workspaceId);
  }, [deleteFile, fetchStats, workspaceId]);

  const handleArchive = useCallback(async (id: string) => {
    await archiveFile(id);
    fetchStats(workspaceId);
  }, [archiveFile, fetchStats, workspaceId]);

  const handleRestore = useCallback(async (id: string) => {
    await restoreFile(id);
    fetchStats(workspaceId);
  }, [restoreFile, fetchStats, workspaceId]);

  const totalSize = stats?.totalSize || 0;
  const totalFiles = stats?.totalFiles || 0;

  return (
    <div
      className="page"
      style={{ padding: '0 32px 40px' }}
      onDragOver={(e) => { e.preventDefault(); setDragOver(true); }}
      onDragLeave={() => setDragOver(false)}
      onDrop={handleDrop}
    >
      <div className="mb-8">
        <p className="mb-2 text-sm font-semibold uppercase tracking-[0.24em]" style={{ color: 'var(--color-muted)' }}>
          Storage
        </p>
        <h1 className="page-title">Files</h1>
        <p className="page-subtitle">Manage your workspace files and attachments.</p>
      </div>

      {/* Stats bar */}
      <div className="mb-6 grid gap-4 sm:grid-cols-3">
        <div className="card flex items-center gap-3 p-4">
          <div className="flex h-10 w-10 items-center justify-center rounded-xl" style={{ background: 'var(--color-accent-light)', color: 'var(--color-accent)' }}>
            <HardDrive size={18} />
          </div>
          <div>
            <p className="text-lg font-bold" style={{ color: 'var(--color-foreground)' }}>{totalFiles}</p>
            <p className="text-xs" style={{ color: 'var(--color-muted)' }}>Total Files</p>
          </div>
        </div>
        <div className="card flex items-center gap-3 p-4">
          <div className="flex h-10 w-10 items-center justify-center rounded-xl" style={{ background: 'var(--color-info-light)', color: 'var(--color-info)' }}>
            <FolderOpen size={18} />
          </div>
          <div>
            <p className="text-lg font-bold" style={{ color: 'var(--color-foreground)' }}>{formatFileSize(totalSize)}</p>
            <p className="text-xs" style={{ color: 'var(--color-muted)' }}>Storage Used</p>
          </div>
        </div>
        <div className="card flex items-center gap-3 p-4">
          <div className="flex h-10 w-10 items-center justify-center rounded-xl" style={{ background: 'var(--color-success-light)', color: 'var(--color-success)' }}>
            <Folder size={18} />
          </div>
          <div>
            <p className="text-lg font-bold" style={{ color: 'var(--color-foreground)' }}>{stats?.byType?.length || 0}</p>
            <p className="text-xs" style={{ color: 'var(--color-muted)' }}>File Types</p>
          </div>
        </div>
      </div>

      {/* Toolbar */}
      <div className="mb-6 flex flex-wrap items-center gap-3">
        <div className="relative flex-1" style={{ minWidth: '240px' }}>
          <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2" style={{ color: 'var(--color-muted)' }} />
          <input
            type="text"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            placeholder="Search files..."
            className="input pl-10 w-full"
          />
        </div>

        <button onClick={() => setSortBy('originalName')} className="btn btn-ghost text-xs gap-1.5">
          <ArrowUpDown size={14} />
          Name {sortBy === 'originalName' && (sortDir === 'asc' ? 'Γåæ' : 'Γåô')}
        </button>
        <button onClick={() => setSortBy('size')} className="btn btn-ghost text-xs gap-1.5">
          <ArrowUpDown size={14} />
          Size {sortBy === 'size' && (sortDir === 'asc' ? 'Γåæ' : 'Γåô')}
        </button>

        <button
          onClick={toggleShowArchived}
          className={clsx('btn text-xs gap-1.5', showArchived ? 'btn-primary' : 'btn-ghost')}
        >
          <Archive size={14} />
          {showArchived ? 'Archived' : 'Archived'}
        </button>

        <div className="flex rounded-lg border overflow-hidden" style={{ borderColor: 'var(--color-border)' }}>
          <button
            onClick={() => setViewMode('grid')}
            className={clsx('p-2 transition-colors', viewMode === 'grid' ? 'btn-primary' : '')}
            style={viewMode !== 'grid' ? { background: 'var(--color-surface)', color: 'var(--color-muted)' } : {}}
          >
            <Grid3X3 size={14} />
          </button>
          <button
            onClick={() => setViewMode('list')}
            className={clsx('p-2 transition-colors', viewMode === 'list' ? 'btn-primary' : '')}
            style={viewMode !== 'list' ? { background: 'var(--color-surface)', color: 'var(--color-muted)' } : {}}
          >
            <List size={14} />
          </button>
        </div>

        <label className="btn btn-primary cursor-pointer gap-1.5">
          <Upload size={14} />
          Upload
          <input
            type="file"
            multiple
            onChange={handleQuickUpload}
            className="hidden"
          />
        </label>
      </div>

      {/* Drag overlay */}
      <AnimatePresence>
        {dragOver && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-50 flex items-center justify-center"
            style={{ background: 'rgba(0,0,0,0.5)', backdropFilter: 'blur(4px)' }}
          >
            <div className="rounded-2xl border-2 border-dashed p-12 text-center" style={{ background: 'var(--color-surface)', borderColor: 'var(--color-accent)' }}>
              <Upload size={48} style={{ color: 'var(--color-accent)' }} className="mx-auto mb-4" />
              <p className="text-lg font-bold" style={{ color: 'var(--color-foreground)' }}>Drop files to upload</p>
              <p className="text-sm mt-1" style={{ color: 'var(--color-muted)' }}>Release to start uploading</p>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Upload modal */}
      <AnimatePresence>
        {showUploadModal && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-50 flex items-center justify-center p-4"
            style={{ background: 'rgba(0,0,0,0.5)', backdropFilter: 'blur(4px)' }}
            onClick={() => setShowUploadModal(false)}
          >
            <motion.div
              initial={{ scale: 0.95, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.95, opacity: 0 }}
              className="card w-full max-w-lg p-6"
              onClick={e => e.stopPropagation()}
            >
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-lg font-bold" style={{ color: 'var(--color-foreground)' }}>Upload Files</h3>
                <button onClick={() => setShowUploadModal(false)} className="rounded p-1" style={{ color: 'var(--color-muted)' }}>
                  <X size={18} />
                </button>
              </div>
              <FileUpload
                path={`workspaces/${workspaceId}/files`}
                accept="all"
                multiple
                maxSize={50 * 1024 * 1024}
                onUploadComplete={handleUploadComplete}
              />
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* File preview modal */}
      <AnimatePresence>
        {previewFile && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-50 flex items-center justify-center p-4"
            style={{ background: 'rgba(0,0,0,0.6)', backdropFilter: 'blur(6px)' }}
            onClick={() => setPreviewFile(null)}
          >
            <motion.div
              initial={{ scale: 0.9, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.9, opacity: 0 }}
              className="card relative max-h-[80vh] w-full max-w-3xl overflow-hidden"
              onClick={e => e.stopPropagation()}
            >
              <div className="flex items-center justify-between border-b p-4" style={{ borderColor: 'var(--color-border)' }}>
                <p className="truncate text-sm font-semibold" style={{ color: 'var(--color-foreground)' }}>
                  {previewFile.originalName}
                </p>
                <div className="flex items-center gap-2">
                  <a href={previewFile.url} download target="_blank" rel="noreferrer" className="btn btn-ghost text-xs gap-1">
                    <Download size={14} /> Download
                  </a>
                  <button onClick={() => setPreviewFile(null)} className="rounded p-1" style={{ color: 'var(--color-muted)' }}>
                    <X size={18} />
                  </button>
                </div>
              </div>
              <div className="flex items-center justify-center p-8" style={{ minHeight: '300px' }}>
                {previewFile.mimeType?.startsWith('image/') ? (
                  <img src={previewFile.url} alt={previewFile.originalName} className="max-h-[60vh] max-w-full rounded-lg object-contain" />
                ) : previewFile.mimeType?.includes('pdf') ? (
                  <iframe src={previewFile.url} className="h-[60vh] w-full rounded-lg border" style={{ borderColor: 'var(--color-border)' }} title={previewFile.originalName} />
                ) : previewFile.mimeType?.startsWith('video/') ? (
                  <video src={previewFile.url} controls className="max-h-[60vh] max-w-full rounded-lg" />
                ) : previewFile.mimeType?.startsWith('audio/') ? (
                  <audio src={previewFile.url} controls className="w-full" />
                ) : (
                  <div className="text-center">
                    <File size={48} style={{ color: 'var(--color-muted)' }} className="mx-auto mb-4" />
                    <p className="text-sm" style={{ color: 'var(--color-muted)' }}>Preview not available for this file type</p>
                    <a href={previewFile.url} download target="_blank" rel="noreferrer" className="btn btn-primary mt-4 gap-1.5">
                      <Download size={14} /> Download File
                    </a>
                  </div>
                )}
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Files list */}
      {loading ? (
        <div className="flex items-center justify-center py-20">
          <Loader2 size={24} className="animate-spin" style={{ color: 'var(--color-accent)' }} />
        </div>
      ) : files.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-20">
          <div
            className="mb-4 flex h-16 w-16 items-center justify-center rounded-2xl"
            style={{ background: 'var(--color-surface-active)', color: 'var(--color-muted)' }}
          >
            <FolderOpen size={28} />
          </div>
          <h3 className="mb-2 text-lg font-bold" style={{ color: 'var(--color-foreground)' }}>
            {searchQuery ? 'No files found' : 'No files yet'}
          </h3>
          <p className="mb-6 text-sm text-center max-w-sm" style={{ color: 'var(--color-muted)' }}>
            {searchQuery
              ? 'Try adjusting your search terms.'
              : 'Drop files anywhere on this page or click Upload to get started.'}
          </p>
          {!searchQuery && (
            <label className="btn btn-primary cursor-pointer gap-1.5">
              <Plus size={16} /> Upload Files
              <input type="file" multiple onChange={handleQuickUpload} className="hidden" />
            </label>
          )}
        </div>
      ) : viewMode === 'grid' ? (
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
          {files.map((file) => {
            const Icon = getFileIconComponent(file.mimeType);
            const isImage = file.mimeType?.startsWith('image/');
            return (
              <motion.div
                key={file._id}
                layout
                initial={{ opacity: 0, scale: 0.95 }}
                animate={{ opacity: 1, scale: 1 }}
                className="card group cursor-pointer overflow-hidden transition-all hover:shadow-md"
                onClick={() => setPreviewFile(file)}
              >
                {isImage ? (
                  <div className="relative h-36 overflow-hidden" style={{ background: 'var(--color-surface-active)' }}>
                    <img src={file.url} alt={file.originalName} className="h-full w-full object-cover" />
                    <div className="absolute inset-0 bg-black/0 transition-colors group-hover:bg-black/20" />
                  </div>
                ) : (
                  <div className="flex h-36 items-center justify-center" style={{ background: 'var(--color-surface-active)' }}>
                    <Icon size={40} style={{ color: 'var(--color-muted)' }} />
                  </div>
                )}
                <div className="p-3">
                  <p className="truncate text-sm font-semibold" style={{ color: 'var(--color-foreground)' }}>
                    {file.originalName}
                  </p>
                  <div className="mt-1 flex items-center justify-between">
                    <p className="text-xs" style={{ color: 'var(--color-muted)' }}>
                      {formatFileSize(file.size)}
                    </p>
                    <p className="text-xs" style={{ color: 'var(--color-muted)' }}>
                      {formatDate(file.createdAt)}
                    </p>
                  </div>
                  <div className="mt-2 flex gap-1 opacity-0 transition-opacity group-hover:opacity-100">
                    <button
                      onClick={(e) => { e.stopPropagation(); setPreviewFile(file); }}
                      className="rounded p-1.5 transition-colors hover:bg-[var(--color-surface-active)]"
                      style={{ color: 'var(--color-muted)' }}
                    >
                      <Eye size={14} />
                    </button>
                    <a
                      href={file.url}
                      download
                      target="_blank"
                      rel="noreferrer"
                      onClick={e => e.stopPropagation()}
                      className="rounded p-1.5 transition-colors hover:bg-[var(--color-surface-active)]"
                      style={{ color: 'var(--color-muted)' }}
                    >
                      <Download size={14} />
                    </a>
                    {file.isArchived ? (
                      <button
                        onClick={(e) => { e.stopPropagation(); handleRestore(file._id); }}
                        className="rounded p-1.5 transition-colors hover:bg-[var(--color-success-light)]"
                        style={{ color: 'var(--color-success)' }}
                      >
                        <RotateCcw size={14} />
                      </button>
                    ) : (
                      <button
                        onClick={(e) => { e.stopPropagation(); handleArchive(file._id); }}
                        className="rounded p-1.5 transition-colors hover:bg-[var(--color-warning-light)]"
                        style={{ color: 'var(--color-warning)' }}
                      >
                        <Archive size={14} />
                      </button>
                    )}
                    <button
                      onClick={(e) => { e.stopPropagation(); handleDelete(file._id); }}
                      className="rounded p-1.5 transition-colors hover:bg-[var(--color-danger-light)]"
                      style={{ color: 'var(--color-danger)' }}
                    >
                      <Trash2 size={14} />
                    </button>
                  </div>
                </div>
              </motion.div>
            );
          })}
        </div>
      ) : (
        <div className="card overflow-hidden">
          <div className="border-b px-4 py-3" style={{ borderColor: 'var(--color-border)', background: 'var(--color-surface)' }}>
            <div className="grid grid-cols-12 gap-4 text-xs font-semibold uppercase tracking-wider" style={{ color: 'var(--color-muted)' }}>
              <div className="col-span-5">Name</div>
              <div className="col-span-2">Size</div>
              <div className="col-span-2">Type</div>
              <div className="col-span-2">Modified</div>
              <div className="col-span-1">Actions</div>
            </div>
          </div>
          {files.map((file) => {
            const Icon = getFileIconComponent(file.mimeType);
            return (
              <div
                key={file._id}
                className="flex items-center border-b px-4 py-3 transition-colors last:border-b-0 hover:bg-[var(--color-surface-hover)]"
                style={{ borderColor: 'var(--color-border-light)' }}
              >
                <div className="col-span-5 flex min-w-0 items-center gap-3">
                  {file.mimeType?.startsWith('image/') ? (
                    <img src={file.url} alt="" className="h-8 w-8 shrink-0 rounded-lg object-cover" />
                  ) : (
                    <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg" style={{ background: 'var(--color-surface-active)', color: 'var(--color-muted)' }}>
                      <Icon size={14} />
                    </div>
                  )}
                  <button
                    onClick={() => setPreviewFile(file)}
                    className="truncate text-sm font-medium text-left hover:underline"
                    style={{ color: 'var(--color-foreground)' }}
                  >
                    {file.originalName}
                  </button>
                </div>
                <div className="col-span-2 text-xs" style={{ color: 'var(--color-muted)' }}>{formatFileSize(file.size)}</div>
                <div className="col-span-2 text-xs" style={{ color: 'var(--color-muted)' }}>{file.mimeType?.split('/')[1] || file.mimeType}</div>
                <div className="col-span-2 text-xs" style={{ color: 'var(--color-muted)' }}>{formatDate(file.createdAt)}</div>
                <div className="col-span-1 flex gap-1">
                  <a href={file.url} download target="_blank" rel="noreferrer" className="rounded p-1.5 transition-colors hover:bg-[var(--color-surface-active)]" style={{ color: 'var(--color-muted)' }}>
                    <Download size={14} />
                  </a>
                  <button
                    onClick={() => setPreviewFile(file)}
                    className="rounded p-1.5 transition-colors hover:bg-[var(--color-surface-active)]"
                    style={{ color: 'var(--color-muted)' }}
                  >
                    <Eye size={14} />
                  </button>
                  <button
                    onClick={() => handleDelete(file._id)}
                    className="rounded p-1.5 transition-colors hover:bg-[var(--color-danger-light)]"
                    style={{ color: 'var(--color-danger)' }}
                  >
                    <Trash2 size={14} />
                  </button>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

