              className="mx-auto mb-6 flex h-20 w-20 items-center justify-center rounded-3xl bg-gradient-to-br from-brand-500 to-violet-600 text-white shadow-[0_20px_50px_-16px_rgba(37,99,235,0.55)]"
            >
              <PartyPopper size={36} />
            </motion.div>
            <h1 className="text-balance text-3xl font-extrabold tracking-tight text-navy-950 dark:text-white">
              You're all set, {firstName}!
            </h1>
            <p className="mx-auto mt-3 max-w-sm text-pretty text-sm leading-relaxed text-slate-500 dark:text-slate-400">
              Your workspace is ready. Start with your dashboard, create your first task, and watch TaMaD bring it all together.
            </p>
            <button
              type="button"
              onClick={() => navigate('/dashboard')}
              className="mt-8 inline-flex h-12 items-center justify-center gap-2 rounded-xl bg-brand-600 px-8 text-sm font-bold text-white shadow-[0_8px_30px_rgba(37,99,235,0.35)] transition-all duration-200 hover:-translate-y-0.5 hover:bg-brand-500"
            >
              <Rocket size={18} />
              Open my dashboard
            </button>
            <p className="mt-4 text-xs text-slate-400 dark:text-slate-500">You can invite teammates anytime from your workspace settings.</p>
          </motion.div>
        ) : mode === null ? (
          <motion.div
            key="mode"
            initial={{ opacity: 0, y: 16 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -16 }}
            transition={{ duration: 0.4, ease: [0.16, 1, 0.3, 1] }}
          >
            <div className="mb-8 text-center">
              <div className="mx-auto mb-5 flex h-14 w-14 items-center justify-center rounded-2xl bg-brand-500/10 text-brand-600 dark:bg-brand-400/10 dark:text-brand-300">
                <Sparkles size={26} />
              </div>
              <h1 className="text-balance text-3xl font-extrabold tracking-tight text-navy-950 dark:text-white">
                Welcome to TaMaD, {firstName}
              </h1>
              <p className="mt-2.5 text-sm text-slate-500 dark:text-slate-400">Let's set up your workspace in a few seconds.</p>
            </div>

            <div className="space-y-3">
              <button
                type="button"
                onClick={() => setMode('personal')}
                className="group flex w-full items-center gap-4 rounded-2xl border border-navy-900/10 bg-white/70 p-5 text-left transition-all duration-200 hover:-translate-y-0.5 hover:border-brand-500/40 hover:shadow-[0_16px_40px_-20px_rgba(37,99,235,0.3)] dark:border-white/10 dark:bg-white/[0.04] dark:hover:border-brand-400/30"
              >
                <span className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl bg-brand-500/10 text-brand-600 dark:text-brand-300">
                  <User size={20} />
                </span>
                <span className="flex-1">
                  <span className="block text-[15px] font-bold text-navy-950 dark:text-white">Just me</span>
                  <span className="block text-[13px] text-slate-500 dark:text-slate-400">A personal workspace for my own tasks, notes, goals and focus.</span>
                </span>
                <ArrowRight size={18} className="text-slate-300 transition-all group-hover:translate-x-1 group-hover:text-brand-500 dark:text-slate-600" />
              </button>

              <button
                type="button"
                onClick={() => setMode('team')}
                className="group flex w-full items-center gap-4 rounded-2xl border border-navy-900/10 bg-white/70 p-5 text-left transition-all duration-200 hover:-translate-y-0.5 hover:border-brand-500/40 hover:shadow-[0_16px_40px_-20px_rgba(37,99,235,0.3)] dark:border-white/10 dark:bg-white/[0.04] dark:hover:border-brand-400/30"
              >
                <span className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl bg-violet-500/10 text-violet-600 dark:text-violet-300">
                  <Building2 size={20} />
                </span>
                <span className="flex-1">
                  <span className="block text-[15px] font-bold text-navy-950 dark:text-white">My team</span>
                  <span className="block text-[13px] text-slate-500 dark:text-slate-400">An organization workspace for projects, sprints, meetings and collaboration.</span>
                </span>
                <ArrowRight size={18} className="text-slate-300 transition-all group-hover:translate-x-1 group-hover:text-brand-500 dark:text-slate-600" />
              </button>
            </div>

            <button type="button" onClick={() => void skip()} className="mt-6 w-full text-center text-sm font-semibold text-slate-400 transition-colors hover:text-slate-600 dark:text-slate-500 dark:hover:text-slate-300">
              Skip for now
            </button>
          </motion.div>
        ) : (
          <motion.div
            key="name"
            initial={{ opacity: 0, y: 16 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -16 }}
            transition={{ duration: 0.4, ease: [0.16, 1, 0.3, 1] }}
          >
            <div className="mb-8 text-center">
              <h1 className="text-balance text-3xl font-extrabold tracking-tight text-navy-950 dark:text-white">
                {mode === 'team' ? 'Name your workspace' : 'Name your workspace'}
              </h1>
              <p className="mt-2.5 text-sm text-slate-500 dark:text-slate-400">
                {mode === 'team' ? "Your team's shared home for everything TaMaD." : "Your personal command center."}
              </p>
            </div>

            <form
              onSubmit={(e) => {
                e.preventDefault();
                void finish();
              }}
              className="space-y-5"
            >
              <div>
                <label htmlFor="wsName" className="mb-1.5 block text-[13px] font-semibold text-navy-900 dark:text-slate-200">
                  {mode === 'team' ? 'Organization name' : 'Workspace name'}
                </label>
                <input
                  id="wsName"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  autoFocus
                  placeholder={mode === 'team' ? 'Acme Inc.' : "My personal workspace"}
                  className={clsx(
                    'h-12 w-full rounded-xl border bg-white/70 px-4 text-[14px] font-medium text-navy-900 outline-none transition-all duration-200 placeholder:text-slate-400 dark:bg-white/[0.04] dark:text-white',
                    'border-navy-900/10 hover:border-navy-900/20 focus:border-brand-600 focus:ring-4 focus:ring-brand-500/10 dark:border-white/10 dark:hover:border-white/20',
                  )}
                />
              </div>

              {mode === 'team' && (
                <div>
                  <label htmlFor="wsDomain" className="mb-1.5 block text-[13px] font-semibold text-navy-900 dark:text-slate-200">
                    Workspace URL (optional)
                  </label>
                  <div className="flex items-center gap-2">
                    <span className="pointer-events-none absolute ml-4 text-sm text-slate-400">tamad.app/</span>
                    <input
                      id="wsDomain"
                      value={domain}
                      onChange={(e) => setDomain(e.target.value.replace(/[^a-z0-9-]/g, ''))}
                      placeholder="acme"
                      className={clsx(
                        'h-12 w-full rounded-xl border bg-white/70 pl-[92px] pr-4 text-[14px] font-medium text-navy-900 outline-none transition-all duration-200 placeholder:text-slate-400 dark:bg-white/[0.04] dark:text-white',
                        'border-navy-900/10 hover:border-navy-900/20 focus:border-brand-600 focus:ring-4 focus:ring-brand-500/10 dark:border-white/10 dark:hover:border-white/20',
                      )}
                    />
                  </div>
                  <p className="mt-1.5 text-xs text-slate-400 dark:text-slate-500">You can change this later.</p>
                </div>
              )}

              <button
                type="submit"
                disabled={isCreating || !name.trim()}
                className="flex h-12 w-full items-center justify-center gap-2 rounded-xl bg-brand-600 text-sm font-bold text-white shadow-[0_8px_30px_rgba(37,99,235,0.35)] transition-all duration-200 hover:-translate-y-0.5 hover:bg-brand-500 disabled:cursor-not-allowed disabled:opacity-60"
              >
                {isCreating ? (
                  <>
                    <span className="h-4 w-4 animate-spin rounded-full border-2 border-white/30 border-t-white" />
                    CreatingΓÇª
                  </>
                ) : (
                  <>
                    <Check size={18} />
                    Create workspace
                  </>
                )}
              </button>

              <button type="button" onClick={() => void skip()} className="w-full text-center text-sm font-semibold text-slate-400 transition-colors hover:text-slate-600 dark:text-slate-500 dark:hover:text-slate-300">
                Skip for now
              </button>
            </form>
          </motion.div>
        )}
      </AnimatePresence>
    </AuthLayout>
  );
}

import { useEffect } from 'react';
import { useOrganizationStore } from '../store/organizationStore';
import { Building, Users, CreditCard, Settings, Plus } from 'lucide-react';
import { useParams } from 'react-router-dom';

export default function OrganizationDashboardPage() {
  const { id } = useParams();
  const { organizations, fetchOrganizations, setCurrentOrganization, currentOrganization } = useOrganizationStore();

  useEffect(() => {
    fetchOrganizations();
  }, [fetchOrganizations]);

  useEffect(() => {
    if (id && organizations.length > 0) {
      const org = organizations.find((o) => o._id === id);
      if (org) setCurrentOrganization(org);
    }
  }, [id, organizations, setCurrentOrganization]);

  if (!currentOrganization) return <div className="p-8">Loading Organization...</div>;

  return (
    <div className="flex h-full flex-col overflow-y-auto">
      <div className="border-b p-8" style={{ borderColor: 'var(--color-border)' }}>
        <div className="flex items-center gap-4">
          <div className="flex h-16 w-16 items-center justify-center rounded-xl bg-purple-500 text-white">
            <Building size={32} />
          </div>
          <div>
            <h1 className="text-3xl font-bold" style={{ color: 'var(--color-foreground)' }}>
              {currentOrganization.name}
            </h1>
            <p className="text-sm" style={{ color: 'var(--color-muted)' }}>
              Organization Dashboard ΓÇó {currentOrganization.domain || 'No domain configured'}
            </p>
          </div>
        </div>
      </div>

      <div className="p-8 space-y-8 max-w-7xl mx-auto w-full">
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
          
          {/* Quick Stat Cards */}
          <div className="rounded-xl border p-6" style={{ background: 'var(--color-surface)', borderColor: 'var(--color-border)' }}>
            <div className="flex items-center gap-3 text-purple-500 mb-2">
              <Users size={20} />
              <h3 className="font-semibold text-[color:var(--color-foreground)]">Total Members</h3>
            </div>
            <p className="text-3xl font-bold">{currentOrganization.members.length}</p>
          </div>

          <div className="rounded-xl border p-6" style={{ background: 'var(--color-surface)', borderColor: 'var(--color-border)' }}>
            <div className="flex items-center gap-3 text-[color:var(--color-success)] mb-2">
              <CreditCard size={20} />
              <h3 className="font-semibold text-[color:var(--color-foreground)]">Billing Plan</h3>
            </div>
            <p className="text-xl font-bold capitalize">{currentOrganization.billing?.plan || 'Free'}</p>
            <p className="text-xs text-[color:var(--color-muted)] mt-1">Status: {currentOrganization.billing?.status || 'Active'}</p>
          </div>

          <div className="rounded-xl border p-6 md:col-span-2 flex flex-col justify-center items-center text-center opacity-50" style={{ background: 'var(--color-surface-hover)', borderColor: 'var(--color-border)' }}>
            <h3 className="font-semibold text-[color:var(--color-foreground)] mb-2">Organization Analytics</h3>
            <p className="text-sm text-[color:var(--color-muted)]">Cross-team analytics coming soon.</p>
          </div>
        </div>

        {/* Global Members */}
        <div className="rounded-xl border" style={{ background: 'var(--color-surface)', borderColor: 'var(--color-border)' }}>
          <div className="flex items-center justify-between border-b p-6" style={{ borderColor: 'var(--color-border)' }}>
            <h2 className="text-lg font-bold" style={{ color: 'var(--color-foreground)' }}>Global Members</h2>
            <button className="flex items-center gap-2 rounded-lg bg-purple-600 px-4 py-2 text-sm font-medium text-white hover:bg-purple-700">
              <Plus size={16} /> Invite Member
            </button>
          </div>
          <div className="p-6">
            <div className="divide-y" style={{ borderColor: 'var(--color-border)' }}>
              {currentOrganization.members.map((member: any) => (
                <div key={member.userId?._id || member.userId} className="flex items-center justify-between py-3">
                  <div className="flex items-center gap-3">
                    <div className="flex h-8 w-8 items-center justify-center rounded-full bg-[color:var(--color-accent)] text-xs text-white">
                      {member.userId?.name?.charAt(0) || 'U'}
                    </div>
                    <div>
                      <p className="text-sm font-medium" style={{ color: 'var(--color-foreground)' }}>{member.userId?.name || 'Unknown User'}</p>
                      <p className="text-xs" style={{ color: 'var(--color-muted)' }}>{member.userId?.email}</p>
                    </div>
                  </div>
                  <span className="rounded-full px-2 py-1 text-xs font-medium bg-[color:var(--color-surface-hover)] text-[color:var(--color-muted)] uppercase">
                    {member.role}
                  </span>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Target, Activity, Plus, Check, MoreVertical } from 'lucide-react';
import clsx from 'clsx';
import { format, subDays } from 'date-fns';
import { useGoalStore } from '../store/goalStore';
import { useHabitStore } from '../store/habitStore';
import { useAuthStore } from '../store/authStore';
import GoalModal from '../components/planner/GoalModal';
import HabitModal from '../components/planner/HabitModal';

export default function PlannerPage() {
  const [activeTab, setActiveTab] = useState<'habits' | 'goals'>('habits');
  const [isGoalModalOpen, setIsGoalModalOpen] = useState(false);
  const [isHabitModalOpen, setIsHabitModalOpen] = useState(false);
  const workspace = useAuthStore(s => s.workspace);

  const { goals, fetchGoals, createGoal } = useGoalStore() as any;
  const { habits, fetchHabits, createHabit } = useHabitStore() as any;

  const workspaceId = workspace?._id || '';

  useEffect(() => {
    if (workspaceId) {
      fetchGoals(workspaceId);
      fetchHabits(workspaceId);
    }
  }, [fetchGoals, fetchHabits, workspaceId]);

  const handleSaveGoal = async (data: any) => {
    await createGoal({ ...data, workspaceId });
  };

  const handleSaveHabit = async (data: any) => {
    await createHabit({ ...data, workspaceId });
  };

  return (
    <div className="page flex flex-col h-[calc(100vh-80px)] overflow-y-auto">
      <div className="flex items-center justify-between mb-8 shrink-0">
        <div>
          <h1 className="page-title mb-0 flex items-center gap-3">
            <div className="p-2 bg-indigo-100 rounded-xl text-indigo-500">
              <Target size={24} className="fill-indigo-500" />
            </div>
            Planner & Habits
          </h1>
          <p className="text-secondary mt-2 text-sm">Track your daily habits and long-term goals.</p>
        </div>

        <button 
          onClick={() => activeTab === 'habits' ? setIsHabitModalOpen(true) : setIsGoalModalOpen(true)}
          className="btn-primary flex items-center justify-center gap-2 px-4 py-2 w-auto"
        >
          <Plus size={20} />
          New {activeTab === 'habits' ? 'Habit' : 'Goal'}
        </button>
      </div>

      <div className="flex bg-gray-100 p-1 rounded-xl mb-6 self-start">
        <button
          onClick={() => setActiveTab('habits')}
          className={clsx(
            'px-6 py-2 rounded-lg text-sm font-semibold transition-all',
            activeTab === 'habits' ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-500 hover:text-gray-700'
          )}
        >
          Daily Habits
        </button>
        <button
          onClick={() => setActiveTab('goals')}
          className={clsx(
            'px-6 py-2 rounded-lg text-sm font-semibold transition-all',
            activeTab === 'goals' ? 'bg-white text-gray-900 shadow-sm' : 'text-gray-500 hover:text-gray-700'
          )}
        >
          Long-Term Goals
        </button>
      </div>

      {activeTab === 'habits' ? (
        <div className="grid gap-4">
          {habits.length === 0 ? (
            <div className="flex items-center justify-center h-32 text-gray-400 text-sm font-medium border-2 border-dashed border-gray-200 rounded-2xl">
              No habits yet. Create one to start building consistency!
            </div>
          ) : habits.map((habit: any) => (
            <div key={habit._id} className="bg-white rounded-2xl border border-gray-100 p-6 flex items-center justify-between shadow-sm hover:shadow-md transition-shadow">
              <div className="flex items-center gap-4">
                <div className={clsx('w-12 h-12 rounded-2xl flex items-center justify-center', habit.color)}>
                  <Activity size={24} />
                </div>
                <div>
                  <h3 className="font-semibold text-gray-800 text-lg">{habit.name}</h3>
                  <p className="text-sm text-gray-500 font-medium">≡ƒöÑ {habit.streak || 0} Day Streak (Best: {habit.longestStreak || 0})</p>
                </div>
              </div>

              <div className="flex items-center gap-3">
                {[6, 5, 4, 3, 2, 1, 0].map((daysAgo, i) => {
                  const date = subDays(new Date(), daysAgo);
                  // Quick mock logic for UI since real backend history needs custom endpoint handling
                  const isCompleted = false; 
                  return (
                    <div key={i} className="flex flex-col items-center gap-2">
                      <span className="text-xs text-gray-400 font-medium">{format(date, 'eee')}</span>
                      <button
                        className={clsx(
                          'w-10 h-10 rounded-xl flex items-center justify-center transition-all',
                          isCompleted
                            ? clsx(habit.color.split(' ')[1], habit.color.split(' ')[0], 'shadow-inner border border-transparent')
                            : 'bg-gray-50 border border-gray-200 text-transparent hover:bg-gray-100'
                        )}
                      >
                        <Check size={20} />
                      </button>
                    </div>
                  );
                })}
                <button className="p-2 text-gray-400 hover:text-gray-700 ml-4">
                  <MoreVertical size={20} />
                </button>
              </div>
            </div>
          ))}
        </div>
      ) : (
        <div className="grid lg:grid-cols-2 gap-6">
          {goals.length === 0 ? (
            <div className="col-span-2 flex items-center justify-center h-32 text-gray-400 text-sm font-medium border-2 border-dashed border-gray-200 rounded-2xl">
              No goals yet. Set a long-term goal to track!
            </div>
          ) : goals.map((goal: any) => (
            <div key={goal._id} className="bg-white rounded-3xl border border-gray-100 p-8 shadow-sm hover:shadow-md transition-all group">
              <div className="flex justify-between items-start mb-6">
                <div>
                  <span className="px-3 py-1 bg-gray-100 text-gray-600 rounded-full text-xs font-semibold capitalize mb-3 inline-block">
                    {goal.type || 'Professional'}
                  </span>
                  <h3 className="font-bold text-xl text-gray-800">{goal.title}</h3>
                </div>
                <button className="text-gray-400 hover:text-gray-800 transition-colors opacity-0 group-hover:opacity-100">
                  <MoreVertical size={20} />
                </button>
              </div>

              <div className="mb-2 flex justify-between text-sm font-semibold text-gray-700">
                <span>Progress</span>
                <span>{goal.progress || 0}%</span>
              </div>
              <div className="h-2 bg-gray-100 rounded-full overflow-hidden mb-6">
                <div className="h-full bg-indigo-500 rounded-full transition-all" style={{ width: `${goal.progress || 0}%` }} />
              </div>

              <div className="flex items-center justify-between text-sm text-gray-500 font-medium bg-gray-50 p-4 rounded-2xl">
                <span>Milestones</span>
                <span className="text-gray-800">{goal.milestones?.filter((m:any)=>m.completed).length || 0} / {goal.milestones?.length || 0} Completed</span>
              </div>
            </div>
          ))}
        </div>
      )}

      <GoalModal 
        isOpen={isGoalModalOpen}
        onClose={() => setIsGoalModalOpen(false)}
        onSave={handleSaveGoal}
      />
      
      <HabitModal
        isOpen={isHabitModalOpen}
        onClose={() => setIsHabitModalOpen(false)}
        onSave={handleSaveHabit}
      />
    </div>
  );
}

