import { useEffect, useState, useCallback } from 'react';
import {
  Mail, Phone, Shield, Globe, Monitor, Clock,
  CheckCircle2, XCircle, LogOut, Pencil, Key,
  Smartphone, Laptop, Loader2,
} from 'lucide-react';
import { motion } from 'framer-motion';
import { useNavigate } from 'react-router-dom';
import toast from 'react-hot-toast';
import { useAuthStore } from '../store/authStore';
import { useTheme } from '../hooks/useTheme';

function InfoRow({
  icon: Icon,
  label,
  value,
  valueColor,
}: {
  icon: typeof Mail;
  label: string;
  value: string;
  valueColor?: string;
}) {
  return (
    <div
      className="flex items-center justify-between rounded-xl p-3"
      style={{ background: 'var(--color-surface-hover)' }}
    >
      <div className="flex items-center gap-3">
        <Icon size={18} style={{ color: 'var(--color-muted)' }} />
        <span
          className="text-sm font-medium"
          style={{ color: 'var(--color-muted)' }}
        >
          {label}
        </span>
      </div>
      <span
        className="text-sm font-semibold"
        style={{ color: valueColor || 'var(--color-foreground)' }}
      >
        {value}
      </span>
    </div>
  );
}

export default function ProfilePage() {
  const navigate = useNavigate();
  const { user, init, loading, logout, getSessions, updateProfile } = useAuthStore((state) => ({
    user: state.user,
    init: state.init,
    loading: state.loading,
    logout: state.logout,
    getSessions: state.getSessions,
    updateProfile: state.updateProfile,
  }));
  const { isDark, toggleTheme } = useTheme();
  const [showChangePassword, setShowChangePassword] = useState(false);
  const [sessions, setSessions] = useState<any[]>([]);
  const [sessionsLoading, setSessionsLoading] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editName, setEditName] = useState('');
  const [isSaving, setIsSaving] = useState(false);

  useEffect(() => {
    void init();
  }, [init]);

  useEffect(() => {
    if (user) {
      setEditName(user.name || '');
      loadSessions();
    }
  }, [user]);

  const loadSessions = useCallback(async () => {
    setSessionsLoading(true);
    try {
      const data = await getSessions();
      setSessions(data || []);
    } catch {
      setSessions([]);
    } finally {
      setSessionsLoading(false);
    }
  }, [getSessions]);

  const handleSaveProfile = async () => {
    if (!editName.trim()) {
      toast.error('Name cannot be empty');
      return;
    }
    setIsSaving(true);
    try {
      await updateProfile({ name: editName.trim() });
      toast.success('Profile updated');
      setIsEditing(false);
    } catch {
      toast.error('Failed to update profile');
    } finally {
      setIsSaving(false);
    }
  };

  const handleLogout = async () => {
    await logout();
    navigate('/login', { replace: true });
  };

  if (loading || !user) {
    return (
      <div className="page" style={{ padding: '0 32px 40px' }}>
        <div className="flex items-center justify-center py-32">
          <div
            className="h-8 w-8 animate-spin rounded-full border-2"
            style={{
              borderColor: 'var(--color-border)',
              borderTopColor: 'var(--color-accent)',
            }}
          />
        </div>
      </div>
    );
  }

  const memberSince = user.createdAt
    ? new Date(user.createdAt).toLocaleDateString('en-US', { month: 'short', year: 'numeric' })
    : 'Unknown';

  const stats = [
    { label: 'Auth Provider', value: user.authProvider === 'google' ? 'Google' : user.authProvider === 'phone' ? 'Phone' : 'Email' },
    { label: 'Role', value: user.role || 'User' },
    { label: 'Member Since', value: memberSince },
    { label: 'Sessions', value: sessions.length.toString() },
  ];

  return (
    <div className="page" style={{ padding: '0 32px 40px' }}>
      {/* Header */}
      <div className="mb-8">
        <p
          className="mb-2 text-sm font-semibold uppercase tracking-[0.24em]"
          style={{ color: 'var(--color-muted)' }}
        >
          Your profile
        </p>
        <h1 className="page-title">Profile</h1>
        <p className="page-subtitle">
          Manage your account details and preferences.
        </p>
      </div>

      {/* Profile Header Card */}
      <motion.div
        initial={{ opacity: 0, y: 10 }}
        animate={{ opacity: 1, y: 0 }}
        className="card mb-6 overflow-hidden"
      >
        <div
          className="relative h-32"
          style={{
            background: `linear-gradient(135deg, var(--color-accent), color-mix(in srgb, var(--color-accent) 60%, var(--color-info)))`,
          }}
        >
          <div
            className="absolute inset-0"
            style={{
              background:
                'repeating-linear-gradient(90deg, rgba(255,255,255,0.03) 0px, rgba(255,255,255,0.03) 1px, transparent 1px, transparent 40px)',
            }}
          />
        </div>
        <div className="relative px-6 pb-6">
          <div className="-mt-12 flex items-end gap-5">
            <div
              className="flex h-24 w-24 items-center justify-center rounded-2xl text-3xl font-bold text-white shadow-medium"
              style={{
                background: `linear-gradient(135deg, var(--color-accent), color-mix(in srgb, var(--color-accent) 70%, var(--color-info)))`,
                border: '4px solid var(--color-surface)',
              }}
            >
              {user.avatarUrl ? (
                <img src={user.avatarUrl} alt={user.name} className="h-full w-full rounded-2xl object-cover" />
              ) : (
                user.name?.charAt(0).toUpperCase()
              )}
            </div>
            <div className="min-w-0 flex-1 pb-1">
              <div className="flex items-center gap-3">
                {isEditing ? (
                  <div className="flex items-center gap-2">
                    <input
                      value={editName}
                      onChange={(e) => setEditName(e.target.value)}
                      className="input-field"
                      style={{ width: 200 }}
                      autoFocus
                    />
                    <button
                      onClick={handleSaveProfile}
                      disabled={isSaving}
                      className="btn btn-primary btn-sm"
                    >
                      {isSaving ? <Loader2 className="animate-spin" size={14} /> : 'Save'}
                    </button>
                    <button
                      onClick={() => { setIsEditing(false); setEditName(user.name || ''); }}
                      className="btn btn-ghost btn-sm"
                    >
                      Cancel
                    </button>
                  </div>
                ) : (
                  <>
                    <h2
                      className="text-2xl font-bold"
                      style={{ color: 'var(--color-foreground)' }}
                    >
                      {user.name}
                    </h2>
                    <span
                      className="badge badge-accent"
                      style={{ textTransform: 'uppercase', letterSpacing: '0.05em' }}
                    >
                      {user.role}
                    </span>
                  </>
                )}
              </div>
              <p
                className="mt-1 text-sm"
                style={{ color: 'var(--color-muted)' }}
              >
                {user.email}
              </p>
            </div>
            <div className="flex gap-2 pb-1">
              {!isEditing && (
                <button
                  onClick={() => setIsEditing(true)}
                  className="btn btn-secondary btn-sm"
                >
                  <Pencil size={14} />
                  Edit
                </button>
              )}
              <button
                onClick={handleLogout}
                className="btn btn-ghost btn-sm"
                style={{ color: 'var(--color-danger)' }}
              >
                <LogOut size={14} />
                Sign out
              </button>
            </div>
          </div>
        </div>
      </motion.div>

      {/* Stats Row */}
      <div className="mb-6 grid grid-cols-2 gap-4 lg:grid-cols-4">
        {stats.map((stat, i) => (
          <motion.div
            key={stat.label}
            initial={{ opacity: 0, y: 8 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.1 + i * 0.05 }}
            className="stat-card"
          >
            <p
              className="text-xs font-semibold uppercase tracking-[0.16em]"
              style={{ color: 'var(--color-muted)' }}
            >
              {stat.label}
            </p>
            <p
              className="mt-2 text-2xl font-bold"
              style={{ color: 'var(--color-foreground)' }}
            >
              {stat.value}
            </p>
          </motion.div>
        ))}
      </div>

      {/* Profile Sections Grid */}
      <div className="grid gap-6 lg:grid-cols-2">
        {/* Personal Info */}
        <motion.div
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.2 }}
          className="card"
        >
          <div className="card-header">
            <h3
              className="text-base font-semibold"
              style={{ color: 'var(--color-foreground)' }}
            >
              Personal Information
            </h3>
          </div>
          <div className="card-body">
            <div className="flex flex-col gap-4">
              <InfoRow
                icon={Mail}
                label="Email"
                value={user.email || 'Not provided'}
              />
              <InfoRow
                icon={Phone}
                label="Phone"
                value={user.phoneNumber || 'Not provided'}
              />
              <InfoRow
                icon={Shield}
                label="Auth Provider"
                value={
                  user.authProvider === 'google'
                    ? 'Google'
                    : user.authProvider === 'phone'
                      ? 'Phone'
                      : 'Email'
                }
              />
              <InfoRow
                icon={user.emailVerified ? CheckCircle2 : XCircle}
                label="Email Verified"
                value={user.emailVerified ? 'Verified' : 'Not verified'}
                valueColor={
                  user.emailVerified
                    ? 'var(--color-success)'
                    : 'var(--color-danger)'
                }
              />
              <InfoRow
                icon={user.phoneVerified ? CheckCircle2 : XCircle}
                label="Phone Verified"
                value={user.phoneVerified ? 'Verified' : 'Not verified'}
                valueColor={
                  user.phoneVerified
                    ? 'var(--color-success)'
                    : 'var(--color-danger)'
                }
              />
            </div>
          </div>
        </motion.div>

        {/* Preferences */}
        <motion.div
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.25 }}
          className="card"
        >
          <div className="card-header">
            <h3
              className="text-base font-semibold"
              style={{ color: 'var(--color-foreground)' }}
            >
              Preferences
            </h3>
          </div>
          <div className="card-body">
            <div className="flex flex-col gap-4">
              <InfoRow
                icon={Globe}
                label="Language"
                value={
                  user.preferences?.language
                    ? user.preferences.language.toUpperCase()
                    : 'EN'
                }
              />
              <InfoRow
                icon={Clock}
                label="Timezone"
                value={user.preferences?.timezone || 'UTC'}
              />
              <div
                className="flex items-center justify-between rounded-xl p-3"
                style={{
                  background: 'var(--color-surface-hover)',
                }}
              >
                <div className="flex items-center gap-3">
                  <Monitor
                    size={18}
                    style={{ color: 'var(--color-muted)' }}
                  />
                  <div>
                    <p
                      className="text-sm font-medium"
                      style={{ color: 'var(--color-foreground)' }}
                    >
                      Dark Mode
                    </p>
                    <p
                      className="text-xs"
                      style={{ color: 'var(--color-muted)' }}
                    >
                      {isDark ? 'Currently dark' : 'Currently light'}
                    </p>
                  </div>
                </div>
                <button
                  onClick={toggleTheme}
                  className="relative h-7 w-12 rounded-full transition-colors"
                  style={{
                    background: isDark
                      ? 'var(--color-accent)'
                      : 'var(--color-border)',
                  }}
                >
                  <span
                    className="absolute top-0.5 left-0.5 h-6 w-6 rounded-full transition-transform"
                    style={{
                      background: 'white',
                      transform: isDark ? 'translateX(20px)' : 'translateX(0)',
                      boxShadow: 'var(--shadow-sm)',
                    }}
                  />
                </button>
              </div>
            </div>
          </div>
        </motion.div>

        {/* Active Sessions */}
        <motion.div
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.3 }}
          className="card lg:col-span-2"
        >
          <div className="card-header">
            <h3
              className="text-base font-semibold"
              style={{ color: 'var(--color-foreground)' }}
            >
              Active Sessions
            </h3>
            <button
              onClick={loadSessions}
              className="btn btn-ghost btn-sm"
            >
              Refresh
            </button>
          </div>
          <div className="card-body">
            {sessionsLoading ? (
              <div className="flex items-center justify-center py-8">
                <div className="h-6 w-6 animate-spin rounded-full border-2" style={{ borderColor: 'var(--color-border)', borderTopColor: 'var(--color-accent)' }} />
              </div>
            ) : sessions.length === 0 ? (
              <div className="py-8 text-center text-sm" style={{ color: 'var(--color-muted)' }}>
                No active sessions found.
              </div>
            ) : (
              <div className="flex flex-col gap-3">
                {sessions.map((session, index) => (
                  <div
                    key={`${session.deviceName}-${index}`}
                    className="flex items-center justify-between rounded-xl p-3 transition-colors"
                    style={{
                      background: session.isCurrent
                        ? 'var(--color-accent-light)'
                        : 'var(--color-surface-hover)',
                      border: session.isCurrent
                        ? '1px solid color-mix(in srgb, var(--color-accent) 20%, transparent)'
                        : '1px solid transparent',
                    }}
                  >
                    <div className="flex items-center gap-3">
                      {(session.deviceName || '').toLowerCase().includes('iphone') ||
                      (session.deviceName || '').toLowerCase().includes('ipad') ? (
                        <Smartphone
                          size={18}
                          style={{ color: 'var(--color-muted)' }}
                        />
                      ) : (
                        <Laptop
                          size={18}
                          style={{ color: 'var(--color-muted)' }}
                        />
                      )}
                      <div>
                        <div className="flex items-center gap-2">
                          <p
                            className="text-sm font-medium"
                            style={{ color: 'var(--color-foreground)' }}
                          >
                            {session.deviceName || 'Unknown device'}
                          </p>
                          {session.isCurrent && (
                            <span
                              className="badge badge-success"
                              style={{ fontSize: '10px' }}
                            >
                              Current
                            </span>
                          )}
                        </div>
                        <p
                          className="text-xs"
                          style={{ color: 'var(--color-muted)' }}
                        >
                          {session.ipAddress || 'Unknown IP'} &middot; {session.lastUsedAt ? new Date(session.lastUsedAt).toLocaleString() : 'Unknown'}
                        </p>
                      </div>
                    </div>
                    {!session.isCurrent && (
                      <button
                        className="btn btn-ghost btn-sm"
                        style={{ color: 'var(--color-danger)', fontSize: '12px' }}
                      >
                        Revoke
                      </button>
                    )}
                  </div>
                ))}
              </div>
            )}
          </div>
        </motion.div>

        {/* Change Password */}
        <motion.div
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.35 }}
          className="card lg:col-span-2"
        >
          <div className="card-header">
            <h3
              className="text-base font-semibold"
              style={{ color: 'var(--color-foreground)' }}
            >
              Security
            </h3>
          </div>
          <div className="card-body">
            <button
              onClick={() => setShowChangePassword(!showChangePassword)}
              className="btn btn-secondary btn-sm"
            >
              <Key size={14} />
              Change Password
            </button>
            {showChangePassword && (
              <motion.div
                initial={{ opacity: 0, height: 0 }}
                animate={{ opacity: 1, height: 'auto' }}
                className="mt-4 flex flex-col gap-3"
              >
                <input
                  type="password"
                  placeholder="Current password"
                  className="input"
                />
                <input
                  type="password"
                  placeholder="New password"
                  className="input"
                />
                <input
                  type="password"
                  placeholder="Confirm new password"
                  className="input"
                />
                <div className="flex justify-end gap-2">
                  <button
                    onClick={() => setShowChangePassword(false)}
                    className="btn btn-ghost btn-sm"
                  >
                    Cancel
                  </button>
                  <button className="btn btn-primary btn-sm">
                    Update Password
                  </button>
                </div>
              </motion.div>
            )}
          </div>
        </motion.div>
      </div>
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import {
  Plus,
  Calendar,
  Users,
  CheckCircle2,
  FolderKanban,
  ChevronDown,
  ChevronUp,
} from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { format, isPast, parseISO } from 'date-fns';
import clsx from 'clsx';
import { useProjectStore } from '../store/projectStore';
import { useTaskStore } from '../store/taskStore';
import { useAuthStore } from '../store/authStore';
import ProjectModal from '../components/projects/ProjectModal';
import LoadingSpinner from '../components/ui/LoadingSpinner';
import ErrorState from '../components/ui/ErrorState';

export default function ProjectsPage() {
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);

  const { projects, fetchProjects, createProject, deleteProject, loading: projectsLoading, error: projectsError } = useProjectStore() as any;
  const { tasks, fetchTasks } = useTaskStore();
  const workspace = useAuthStore(s => s.workspace);
  const workspaceId = workspace?._id || '';

  const isLoading = projectsLoading;
  const error = projectsError;

  const retry = useCallback(() => {
    if (workspaceId) {
      fetchProjects(workspaceId);
      fetchTasks(workspaceId);
    }
  }, [fetchProjects, fetchTasks, workspaceId]);

  useEffect(() => {
    if (workspaceId) {
      fetchProjects(workspaceId);
      fetchTasks(workspaceId);
    }
  }, [fetchProjects, fetchTasks, workspaceId]);

  const getProjectStats = (projectId: string) => {
    const projectTasks = tasks.filter((t: any) => t.projectId === projectId);
    const completed = projectTasks.filter((t: any) => t.status === 'done').length;
    return {
      totalTasks: projectTasks.length,
      completedTasks: completed,
      progress: projectTasks.length > 0 ? Math.round((completed / projectTasks.length) * 100) : 0,
    };
  };

  const totalProjects = projects.length;
  const totalTasksAll = projects.reduce((sum: number, p: any) => sum + getProjectStats(p._id).totalTasks, 0);
  const avgProgress = totalProjects > 0
    ? Math.round(projects.reduce((sum: number, p: any) => sum + getProjectStats(p._id).progress, 0) / totalProjects)
    : 0;

  const toggleExpand = (id: string) => {
    setExpandedId((prev) => (prev === id ? null : id));
  };

  const getStatusStyle = (status: string) => {
    switch (status) {
      case 'active': return { bg: 'var(--color-success-light)', color: 'var(--color-success)' };
      case 'completed': return { bg: 'var(--color-info-light)', color: 'var(--color-info)' };
      case 'on-hold': return { bg: 'var(--color-warning-light)', color: 'var(--color-warning)' };
      default: return { bg: 'var(--color-surface-active)', color: 'var(--color-muted)' };
    }
  };

  const handleSaveProject = async (data: any) => {
    await createProject({ ...data, workspaceId });
  };

  const handleDeleteProject = (id: string) => {
    if (window.confirm('Are you sure you want to delete this project? This action cannot be undone.')) {
      deleteProject(id);
    }
  };

  return (
    <div className="page" style={{ padding: '0 32px 40px' }}>
      {/* Header */}
      <div className="mb-8 flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between">
        <div>
          <p className="mb-2 text-sm font-semibold uppercase tracking-[0.24em]" style={{ color: 'var(--color-muted)' }}>
            Project management
          </p>
          <h1 className="page-title">Projects</h1>
          <p className="page-subtitle">
            Track progress, manage deadlines, and keep your team aligned.
          </p>
        </div>
        <button className="btn btn-primary" onClick={() => setIsModalOpen(true)}>
          <Plus size={16} />
          New Project
        </button>
      </div>

      {/* Summary Bar */}
      <div className="mb-6 grid grid-cols-3 gap-4">
        {[
          { label: 'Total Projects', value: totalProjects },
          { label: 'Total Tasks', value: totalTasksAll },
          { label: 'Avg Progress', value: `${avgProgress}%` },
        ].map((stat, i) => (
          <motion.div
            key={stat.label}
            initial={{ opacity: 0, y: 8 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: i * 0.05 }}
            className="stat-card"
          >
            <p className="text-xs font-semibold uppercase tracking-[0.16em]" style={{ color: 'var(--color-muted)' }}>
              {stat.label}
            </p>
            <p className="mt-2 text-2xl font-bold" style={{ color: 'var(--color-foreground)' }}>
              {stat.value}
            </p>
          </motion.div>
        ))}
      </div>

      {/* Projects Grid */}
      {isLoading && <LoadingSpinner text="Loading projects..." />}

      {!isLoading && error && <ErrorState message={error} onRetry={retry} />}

      {!isLoading && !error && projects.length === 0 ? (
        <div className="empty-state">
          <div className="empty-state-icon">
            <FolderKanban size={32} />
          </div>
          <p className="empty-state-title">No projects yet</p>
          <p className="empty-state-description">
            Create your first project to start tracking tasks and progress.
          </p>
          <button className="btn btn-primary" onClick={() => setIsModalOpen(true)}>
            <Plus size={16} />
            Create Project
          </button>
        </div>
      ) : (
        <div className="grid gap-4 lg:grid-cols-2">
          {projects.map((project: any, index: number) => {
            const isExpanded = expandedId === project._id;
            const statusStyle = getStatusStyle(project.status || 'active');
            const stats = getProjectStats(project._id);
            const isOverdue = project.dueDate && (() => {
              try { return isPast(parseISO(project.dueDate)); } catch { return false; }
            })();

            return (
              <motion.div
                key={project._id}
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: index * 0.06 }}
                className="card overflow-hidden transition-all"
                style={{
                  borderColor: isExpanded ? (project.color || 'var(--color-accent)') : undefined,
                  boxShadow: isExpanded ? 'var(--shadow-medium)' : undefined,
                }}
              >
                <div className="cursor-pointer p-5" onClick={() => toggleExpand(project._id)}>
                  <div className="flex items-start justify-between gap-3">
                    <div className="flex items-start gap-3">
                      <div
                        className="flex h-10 w-10 flex-shrink-0 items-center justify-center rounded-xl text-sm font-bold text-white"
                        style={{ background: project.color || 'var(--color-accent)' }}
                      >
                        {project.name?.charAt(0) || 'P'}
                      </div>
                      <div className="min-w-0 flex-1">
                        <div className="flex items-center gap-2">
                          <h3 className="text-sm font-bold" style={{ color: 'var(--color-foreground)' }}>
                            {project.name}
                          </h3>
                          <span className="badge" style={{ background: statusStyle.bg, color: statusStyle.color, fontSize: '10px' }}>
                            {project.status || 'active'}
                          </span>
                        </div>
                        <p className="mt-0.5 text-xs" style={{ color: 'var(--color-muted)' }}>
                          {project.description || 'No description'}
                        </p>
                      </div>
                    </div>
                    <button className="btn btn-ghost btn-icon-sm flex-shrink-0" style={{ color: 'var(--color-muted)' }}>
                      {isExpanded ? <ChevronUp size={16} /> : <ChevronDown size={16} />}
                    </button>
                  </div>

                  {/* Progress Bar */}
                  <div className="mt-4">
                    <div className="mb-1.5 flex items-center justify-between">
                      <span className="text-xs font-semibold" style={{ color: 'var(--color-muted)' }}>
                        {stats.completedTasks} of {stats.totalTasks} tasks
                      </span>
                      <span className="text-xs font-bold" style={{ color: project.color || 'var(--color-accent)' }}>
                        {stats.progress}%
                      </span>
                    </div>
                    <div className="progress-bar">
                      <motion.div
                        initial={{ width: 0 }}
                        animate={{ width: `${stats.progress}%` }}
                        transition={{ duration: 0.8, delay: 0.2 + index * 0.1 }}
                        className="progress-bar-fill"
                        style={{ background: project.color || 'var(--color-accent)' }}
                      />
                    </div>
                  </div>

                  {/* Meta Row */}
                  <div className="mt-4 flex items-center justify-between">
                    <div className="flex items-center gap-2">
                      <div className="flex items-center gap-1.5">
                        <Users size={13} style={{ color: 'var(--color-muted)' }} />
                        <span className="text-xs" style={{ color: 'var(--color-muted)' }}>
                          {project.members?.length || 0} members
                        </span>
                      </div>
                    </div>
                    {project.dueDate && (
                      <div className="flex items-center gap-1.5">
                        <Calendar size={13} style={{ color: isOverdue ? 'var(--color-danger)' : 'var(--color-muted)' }} />
                        <span className="text-xs font-medium" style={{ color: isOverdue ? 'var(--color-danger)' : 'var(--color-muted)' }}>
                          {(() => { try { return format(parseISO(project.dueDate), 'MMM d, yyyy'); } catch { return project.dueDate; } })()}
                        </span>
                      </div>
                    )}
                  </div>
                </div>

                {/* Expanded Detail */}
                <AnimatePresence>
                  {isExpanded && (
                    <motion.div
                      initial={{ height: 0, opacity: 0 }}
                      animate={{ height: 'auto', opacity: 1 }}
                      exit={{ height: 0, opacity: 0 }}
                      transition={{ duration: 0.2 }}
                      className="overflow-hidden"
                    >
                      <div className="border-t px-5 py-4" style={{ borderColor: 'var(--color-border-light)' }}>
                        {project.members && project.members.length > 0 && (
                          <>
                            <p className="mb-3 text-xs font-semibold uppercase tracking-wider" style={{ color: 'var(--color-muted)' }}>
                              Team Members
                            </p>
                            <div className="flex flex-col gap-2">
                              {project.members.map((memberId: string, i: number) => (
                                <div
                                  key={i}
                                  className="flex items-center gap-3 rounded-lg p-2"
                                  style={{ background: 'var(--color-surface-hover)' }}
                                >
                                  <div className="flex h-8 w-8 items-center justify-center rounded-full text-xs font-bold text-white" style={{ background: 'var(--color-accent)' }}>
                                    {memberId?.charAt(0)?.toUpperCase() || '?'}
                                  </div>
                                  <div>
                                    <p className="text-sm font-medium" style={{ color: 'var(--color-foreground)' }}>{memberId}</p>
                                  </div>
                                </div>
                              ))}
                            </div>
                          </>
                        )}
                      </div>
                    </motion.div>
                  )}
                </AnimatePresence>
              </motion.div>
            );
          })}
        </div>
      )}

      <ProjectModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} onSave={handleSaveProject} />
    </div>
  );
}

import { useState, useMemo, useEffect, useCallback } from 'react';
import {
  Download,
  Clock,
  CheckCircle2,
  TrendingUp,
  Zap,
  Calendar,
  BarChart3,
} from 'lucide-react';
import { motion } from 'framer-motion';
import clsx from 'clsx';
import {
  ResponsiveContainer,
  BarChart,
  Bar,
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  PieChart,
  Pie,
  Cell,
} from 'recharts';
import { useTaskStore } from '../store/taskStore';
import { useAuthStore } from '../store/authStore';
import api from '../utils/api';
import LoadingSpinner from '../components/ui/LoadingSpinner';
import ErrorState from '../components/ui/ErrorState';

const DATE_RANGES = ['This Week', 'This Month', 'Last 3 Months', 'Year'];

const CustomTooltip = ({
  active,
  payload,
  label,
}: {
  active?: boolean;
  payload?: Array<{ name: string; value: number; color: string }>;
  label?: string;
}) => {
  if (!active || !payload) return null;
  return (
    <div
      className="rounded-xl border px-3 py-2"
      style={{
        background: 'var(--color-surface)',
        borderColor: 'var(--color-border)',
        boxShadow: 'var(--shadow-medium)',
      }}
    >
      <p className="mb-1 text-xs font-semibold" style={{ color: 'var(--color-foreground)' }}>
        {label}
      </p>
      {payload.map((entry, i) => (
        <p key={i} className="text-xs" style={{ color: entry.color || 'var(--color-muted)' }}>
          {entry.name}: {entry.value}
        </p>
      ))}
    </div>
  );
};

export default function ReportsPage() {
  const [dateRange, setDateRange] = useState('This Month');
  const { tasks, fetchTasks, loading: tasksLoading, error: tasksError } = useTaskStore();
  const workspace = useAuthStore(s => s.workspace);
  const workspaceId = workspace?._id || '';

  const isLoading = tasksLoading;
  const error = tasksError;

  const retry = useCallback(() => {
    if (workspaceId) fetchTasks(workspaceId);
  }, [fetchTasks, workspaceId]);

  useEffect(() => {
    if (workspaceId) fetchTasks(workspaceId);
  }, [fetchTasks, workspaceId]);

  // Filter tasks by date range
  const filteredTasks = useMemo(() => {
    const now = new Date();
    let startDate: Date | null = null;
    if (dateRange === 'This Week') {
      startDate = new Date(now);
      startDate.setDate(now.getDate() - 7);
    } else if (dateRange === 'This Month') {
      startDate = new Date(now);
      startDate.setMonth(now.getMonth() - 1);
    } else if (dateRange === 'Last 3 Months') {
      startDate = new Date(now);
      startDate.setMonth(now.getMonth() - 3);
    } else if (dateRange === 'Year') {
      startDate = new Date(now);
      startDate.setFullYear(now.getFullYear() - 1);
    }
    if (!startDate) return tasks;
    return tasks.filter((t: any) => {
      const created = t.createdAt ? new Date(t.createdAt) : null;
      return created && created >= startDate!;
    });
  }, [tasks, dateRange]);

  const handleExport = useCallback(async () => {
    try {
      const { data } = await api.get('/analytics/export/csv', {
        params: { workspaceId },
        responseType: 'blob',
      });
      const url = window.URL.createObjectURL(data);
      const a = document.createElement('a');
      a.href = url;
      a.download = `tamad-report-${new Date().toISOString().split('T')[0]}.csv`;
      a.click();
      window.URL.revokeObjectURL(url);
    } catch {}
  }, [workspaceId]);

  const completedTasks = filteredTasks.filter((t: any) => t.status === 'done').length;
  const totalTasks = filteredTasks.length;

  const weeklyProductivity = useMemo(() => {
    const days = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
    const now = new Date();
    return days.map((day, i) => {
      const date = new Date(now);
      date.setDate(now.getDate() - (6 - i));
      const dateStr = date.toISOString().slice(0, 10);
      const completedCount = filteredTasks.filter((t: any) => {
        if (!t.updatedAt) return false;
        return t.updatedAt.slice(0, 10) === dateStr && t.status === 'done';
      }).length;
      const createdCount = filteredTasks.filter((t: any) => {
        if (!t.createdAt) return false;
        return t.createdAt.slice(0, 10) === dateStr;
      }).length;
      return { day, completed: completedCount, created: createdCount };
    });
  }, [filteredTasks]);

  const statusDistribution = useMemo(() => {
    const counts: Record<string, number> = {};
    filteredTasks.forEach((t: any) => {
      counts[t.status] = (counts[t.status] || 0) + 1;
    });
    return [
      { name: 'To Do', value: counts['todo'] || 0, color: 'var(--color-muted)' },
      { name: 'In Progress', value: counts['in-progress'] || 0, color: 'var(--color-accent)' },
      { name: 'Review', value: counts['review'] || 0, color: 'var(--color-warning)' },
      { name: 'Done', value: counts['done'] || 0, color: 'var(--color-success)' },
    ].filter(s => s.value > 0);
  }, [filteredTasks]);

  const priorityDistribution = useMemo(() => {
    const counts: Record<string, number> = {};
    filteredTasks.forEach((t: any) => {
      counts[t.priority] = (counts[t.priority] || 0) + 1;
    });
    return [
      { name: 'Urgent', value: counts['urgent'] || 0, color: 'var(--color-danger)' },
      { name: 'High', value: counts['high'] || 0, color: 'var(--color-warning)' },
      { name: 'Medium', value: counts['medium'] || 0, color: 'var(--color-accent)' },
      { name: 'Low', value: counts['low'] || 0, color: 'var(--color-muted)' },
    ].filter(p => p.value > 0);
  }, [filteredTasks]);

  const teamPerformance = useMemo(() => {
    const members: Record<string, { name: string; tasks: number; hours: number }> = {};
    filteredTasks.forEach((t: any) => {
      const assignee = t.assignee || 'Unassigned';
      if (!members[assignee]) {
        members[assignee] = { name: assignee, tasks: 0, hours: 0 };
      }
      members[assignee].tasks += 1;
    });
    return Object.values(members).map(m => ({
      ...m,
      hours: m.tasks * 2,
    }));
  }, [filteredTasks]);

  const productivityScore = totalTasks > 0 ? Math.round((completedTasks / totalTasks) * 100) : 0;

  const SUMMARY_STATS = [
    { label: 'Total Tasks', value: totalTasks.toString(), change: 'all time', positive: true, icon: Clock },
    { label: 'Tasks Completed', value: completedTasks.toString(), change: `${totalTasks - completedTasks} remaining`, positive: true, icon: CheckCircle2 },
    { label: 'Completion Rate', value: `${productivityScore}%`, change: 'overall', positive: true, icon: TrendingUp },
    { label: 'Productivity Score', value: `${productivityScore}%`, change: productivityScore >= 50 ? 'on track' : 'needs work', positive: productivityScore >= 50, icon: Zap },
  ];

  return (
    <div className="page" style={{ padding: '0 32px 40px' }}>
      {/* Header */}
      <div className="mb-8 flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between">
        <div>
          <p className="mb-2 text-sm font-semibold uppercase tracking-[0.24em]" style={{ color: 'var(--color-muted)' }}>
            Analytics
          </p>
          <h1 className="page-title">Reports</h1>
          <p className="page-subtitle">
            Visualize team performance, track productivity, and identify trends.
          </p>
        </div>
        <div className="flex items-center gap-3">
          <div className="flex gap-1 rounded-xl p-1" style={{ background: 'var(--color-surface)', border: '1px solid var(--color-border)' }}>
            {DATE_RANGES.map((range) => (
              <button
                key={range}
                onClick={() => setDateRange(range)}
                className={clsx(
                  'rounded-lg px-3 py-1.5 text-xs font-medium transition-all',
                  dateRange === range ? 'btn-primary' : 'btn-ghost'
                )}
              >
                {range}
              </button>
            ))}
          </div>
          <button onClick={handleExport} className="btn btn-secondary btn-sm">
            <Download size={14} />
            Export
          </button>
        </div>
      </div>

      {isLoading && <LoadingSpinner text="Loading reports..." />}

      {!isLoading && error && <ErrorState message={error} onRetry={retry} />}

      {!isLoading && !error && (
        <>
          {/* Summary Stats */}
      <div className="mb-6 grid gap-4 md:grid-cols-2 xl:grid-cols-4">
        {SUMMARY_STATS.map((stat, i) => (
          <motion.div
            key={stat.label}
            initial={{ opacity: 0, y: 8 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: i * 0.05 }}
            className="stat-card"
          >
            <div className="mb-3 flex items-center justify-between">
              <p className="text-xs font-semibold uppercase tracking-[0.16em]" style={{ color: 'var(--color-muted)' }}>
                {stat.label}
              </p>
              <div className="rounded-lg p-2" style={{ background: 'var(--color-surface-active)', color: 'var(--color-accent)' }}>
                <stat.icon size={16} />
              </div>
            </div>
            <p className="text-3xl font-bold" style={{ color: 'var(--color-foreground)' }}>
              {stat.value}
            </p>
            <p className="mt-1 text-xs font-medium" style={{ color: stat.positive ? 'var(--color-success)' : 'var(--color-danger)' }}>
              {stat.change}
            </p>
          </motion.div>
        ))}
      </div>

      {/* Charts Grid */}
      <div className="grid gap-6 lg:grid-cols-2">
        {/* Weekly Productivity */}
        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.2 }} className="card">
          <div className="card-header">
            <div>
              <h3 className="text-base font-semibold" style={{ color: 'var(--color-foreground)' }}>Weekly Productivity</h3>
              <p className="mt-0.5 text-xs" style={{ color: 'var(--color-muted)' }}>Tasks completed vs. created per day</p>
            </div>
            <div className="rounded-lg px-2 py-1" style={{ background: 'var(--color-accent-light)', color: 'var(--color-accent)' }}>
              <BarChart3 size={16} />
            </div>
          </div>
          <div className="card-body">
            <ResponsiveContainer width="100%" height={260}>
              <BarChart data={weeklyProductivity} barGap={4}>
                <CartesianGrid strokeDasharray="3 3" stroke="var(--color-border-light)" vertical={false} />
                <XAxis dataKey="day" tick={{ fontSize: 12, fill: 'var(--color-muted)' }} axisLine={false} tickLine={false} />
                <YAxis tick={{ fontSize: 12, fill: 'var(--color-muted)' }} axisLine={false} tickLine={false} />
                <Tooltip content={<CustomTooltip />} />
                <Bar dataKey="completed" name="Completed" fill="var(--color-success)" radius={[6, 6, 0, 0]} maxBarSize={32} />
                <Bar dataKey="created" name="Created" fill="var(--color-accent)" radius={[6, 6, 0, 0]} maxBarSize={32} opacity={0.4} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </motion.div>

        {/* Team Performance */}
        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.25 }} className="card">
          <div className="card-header">
            <div>
              <h3 className="text-base font-semibold" style={{ color: 'var(--color-foreground)' }}>Team Performance</h3>
              <p className="mt-0.5 text-xs" style={{ color: 'var(--color-muted)' }}>Tasks completed per team member</p>
            </div>
            <div className="rounded-lg px-2 py-1" style={{ background: 'var(--color-info-light)', color: 'var(--color-info)' }}>
              <TrendingUp size={16} />
            </div>
          </div>
          <div className="card-body">
            {teamPerformance.length === 0 ? (
              <p className="text-sm text-center py-10" style={{ color: 'var(--color-muted)' }}>No team data available</p>
            ) : (
              <ResponsiveContainer width="100%" height={260}>
                <BarChart data={teamPerformance} layout="vertical" barGap={4}>
                  <CartesianGrid strokeDasharray="3 3" stroke="var(--color-border-light)" horizontal={false} />
                  <XAxis type="number" tick={{ fontSize: 12, fill: 'var(--color-muted)' }} axisLine={false} tickLine={false} />
                  <YAxis dataKey="name" type="category" tick={{ fontSize: 12, fill: 'var(--color-muted)' }} axisLine={false} tickLine={false} width={60} />
                  <Tooltip content={<CustomTooltip />} />
                  <Bar dataKey="tasks" name="Tasks" fill="var(--color-accent)" radius={[0, 6, 6, 0]} maxBarSize={24} />
                </BarChart>
              </ResponsiveContainer>
            )}
          </div>
        </motion.div>

        {/* Task Completion Trend */}
        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.3 }} className="card">
          <div className="card-header">
            <div>
              <h3 className="text-base font-semibold" style={{ color: 'var(--color-foreground)' }}>Task Completion Trend</h3>
              <p className="mt-0.5 text-xs" style={{ color: 'var(--color-muted)' }}>Daily completion over the week</p>
            </div>
            <div className="rounded-lg px-2 py-1" style={{ background: 'var(--color-success-light)', color: 'var(--color-success)' }}>
              <Calendar size={16} />
            </div>
          </div>
          <div className="card-body">
            <ResponsiveContainer width="100%" height={260}>
              <LineChart data={weeklyProductivity}>
                <CartesianGrid strokeDasharray="3 3" stroke="var(--color-border-light)" vertical={false} />
                <XAxis dataKey="day" tick={{ fontSize: 12, fill: 'var(--color-muted)' }} axisLine={false} tickLine={false} />
                <YAxis tick={{ fontSize: 12, fill: 'var(--color-muted)' }} axisLine={false} tickLine={false} />
                <Tooltip content={<CustomTooltip />} />
                <Line type="monotone" dataKey="completed" name="Completed" stroke="var(--color-success)" strokeWidth={3} dot={{ fill: 'var(--color-success)', strokeWidth: 0, r: 5 }} activeDot={{ r: 7, fill: 'var(--color-success)', stroke: 'var(--color-surface)', strokeWidth: 3 }} />
              </LineChart>
            </ResponsiveContainer>
          </div>
        </motion.div>

        {/* Priority Distribution */}
        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.35 }} className="card">
          <div className="card-header">
            <div>
              <h3 className="text-base font-semibold" style={{ color: 'var(--color-foreground)' }}>Priority Distribution</h3>
              <p className="mt-0.5 text-xs" style={{ color: 'var(--color-muted)' }}>Breakdown of tasks by priority level</p>
            </div>
          </div>
          <div className="card-body">
            {priorityDistribution.length === 0 ? (
              <p className="text-sm text-center py-10" style={{ color: 'var(--color-muted)' }}>No tasks yet</p>
            ) : (
              <div className="flex items-center gap-6">
                <ResponsiveContainer width="50%" height={200}>
                  <PieChart>
                    <Pie data={priorityDistribution} cx="50%" cy="50%" innerRadius={50} outerRadius={80} paddingAngle={4} dataKey="value">
                      {priorityDistribution.map((entry, index) => (
                        <Cell key={`cell-${index}`} fill={entry.color} stroke="none" />
                      ))}
                    </Pie>
                    <Tooltip contentStyle={{ background: 'var(--color-surface)', border: '1px solid var(--color-border)', borderRadius: '12px', fontSize: '12px' }} />
                  </PieChart>
                </ResponsiveContainer>
                <div className="flex flex-col gap-3">
                  {priorityDistribution.map((item) => (
                    <div key={item.name} className="flex items-center gap-3">
                      <div className="h-3 w-3 rounded-full" style={{ background: item.color }} />
                      <div>
                        <p className="text-sm font-medium" style={{ color: 'var(--color-foreground)' }}>{item.name}</p>
                        <p className="text-xs" style={{ color: 'var(--color-muted)' }}>{item.value} tasks</p>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        </motion.div>

        {/* Status Distribution Bar */}
        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.4 }} className="card lg:col-span-2">
          <div className="card-header">
            <div>
              <h3 className="text-base font-semibold" style={{ color: 'var(--color-foreground)' }}>Task Status Overview</h3>
              <p className="mt-0.5 text-xs" style={{ color: 'var(--color-muted)' }}>Current status distribution of all tasks</p>
            </div>
            <p className="text-sm font-semibold" style={{ color: 'var(--color-foreground)' }}>
              {totalTasks} total &middot; {completedTasks} done
            </p>
          </div>
          <div className="card-body">
            <div className="mb-4 flex h-8 w-full overflow-hidden rounded-full">
              {statusDistribution.map((status) => (
                <motion.div
                  key={status.name}
                  initial={{ width: 0 }}
                  animate={{ width: `${totalTasks > 0 ? (status.value / totalTasks) * 100 : 0}%` }}
                  transition={{ duration: 0.8, delay: 0.3 }}
                  style={{ background: status.color }}
                  className="h-full"
                  title={`${status.name}: ${status.value}`}
                />
              ))}
            </div>
            <div className="flex flex-wrap gap-6">
              {statusDistribution.map((status) => (
                <div key={status.name} className="flex items-center gap-2">
                  <div className="h-3 w-3 rounded-full" style={{ background: status.color }} />
                  <span className="text-sm font-medium" style={{ color: 'var(--color-foreground)' }}>{status.name}</span>
                  <span className="text-sm" style={{ color: 'var(--color-muted)' }}>({status.value})</span>
                </div>
              ))}
            </div>
          </div>
        </motion.div>
      </div>
        </>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Plus, Calendar as CalendarIcon, AlignLeft } from 'lucide-react';
import clsx from 'clsx';
import { format, addDays, startOfMonth, eachDayOfInterval } from 'date-fns';
import { useProjectStore } from '../store/projectStore';
import { useAuthStore } from '../store/authStore';
import ProjectModal from '../components/projects/ProjectModal';

const COLORS = ['bg-blue-500', 'bg-purple-500', 'bg-indigo-500', 'bg-teal-500', 'bg-rose-500'];

export default function RoadmapPage() {
  const workspace = useAuthStore(s => s.workspace);
  const { projects, fetchProjects, createProject } = useProjectStore() as any;
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [currentDate] = useState(new Date());

  const workspaceId = workspace?._id || '';

  useEffect(() => {
    if (workspaceId) fetchProjects(workspaceId);
  }, [fetchProjects, workspaceId]);
  
  // Generate a timeline spanning 30 days from start of month
  const timelineStart = startOfMonth(currentDate);
  const timelineEnd = addDays(timelineStart, 30);
  const days = eachDayOfInterval({ start: timelineStart, end: timelineEnd });

  const getLeftOffset = (dateStr: string) => {
    if (!dateStr) return 0;
    const date = new Date(dateStr);
    const diffTime = date.getTime() - timelineStart.getTime();
    const diffDays = Math.max(0, Math.ceil(diffTime / (1000 * 60 * 60 * 24)));
    return Math.min(100, diffDays * (100 / 30)); // percentage
  };

  const getWidth = (startStr: string, endStr: string) => {
    if (!startStr || !endStr) return 10;
    const start = new Date(startStr);
    const end = new Date(endStr);
    const diffTime = end.getTime() - start.getTime();
    const diffDays = Math.max(1, Math.ceil(diffTime / (1000 * 60 * 60 * 24)));
    return Math.min(100, diffDays * (100 / 30)); // percentage
  };

  const handleSaveProject = async (data: any) => {
    await createProject({
      ...data,
      workspaceId: '000000000000000000000000'
    });
  };

  return (
    <div className="page flex flex-col h-[calc(100vh-80px)] relative z-10">
      <div className="flex items-center justify-between mb-6 shrink-0">
        <div>
          <h1 className="page-title mb-0">Roadmap</h1>
          <p className="text-secondary mt-1 text-sm font-medium">Visualize project timelines and milestones.</p>
        </div>

        <button 
          onClick={() => setIsModalOpen(true)}
          className="btn-primary flex items-center justify-center gap-2 px-4 py-2 w-auto"
        >
          <Plus size={20} />
          New Project
        </button>
      </div>

      <div className="flex-1 bg-white rounded-2xl border border-gray-200 shadow-sm flex flex-col overflow-hidden relative z-0">
        {/* Timeline Header */}
        <div className="flex border-b border-gray-200 bg-gray-50/80">
          <div className="w-64 shrink-0 border-r border-gray-200 p-4 font-semibold text-gray-700 flex items-center gap-2">
            <AlignLeft size={18} className="text-gray-400" />
            Projects
          </div>
          <div className="flex-1 flex overflow-hidden relative">
            {days.map((day, i) => (
              <div
                key={i}
                className="flex-1 border-r border-gray-200/50 py-2 text-center text-xs font-medium text-gray-400 flex flex-col items-center justify-center"
              >
                <span>{format(day, 'MMM')}</span>
                <span className="text-gray-700 font-bold">{format(day, 'dd')}</span>
              </div>
            ))}
          </div>
        </div>

        {/* Timeline Body */}
        <div className="flex-1 overflow-y-auto">
          {projects.length === 0 ? (
            <div className="flex items-center justify-center h-full text-gray-400 text-sm font-medium">
              No projects yet. Create one to get started!
            </div>
          ) : (
            projects.map((project: any, index: number) => {
              const color = COLORS[index % COLORS.length];
              return (
                <div key={project._id} className="flex border-b border-gray-100 group hover:bg-gray-50/50 transition-colors h-24">
                  {/* Project Info Sidebar */}
                  <div className="w-64 shrink-0 border-r border-gray-200 p-4 overflow-hidden flex flex-col justify-center">
                    <h3 className="font-semibold text-gray-800 text-sm mb-1 truncate">{project.name}</h3>
                    {project.startDate && project.endDate && (
                      <div className="flex items-center gap-2 text-xs text-gray-500">
                        <CalendarIcon size={12} />
                        <span>{format(new Date(project.startDate), 'MMM d')} - {format(new Date(project.endDate), 'MMM d')}</span>
                      </div>
                    )}
                  </div>

                  {/* Gantt Area */}
                  <div className="flex-1 relative py-4">
                    {/* Vertical grid lines */}
                    <div className="absolute inset-0 flex">
                      {days.map((_, i) => (
                        <div key={i} className="flex-1 border-r border-gray-100/50 h-full pointer-events-none" />
                      ))}
                    </div>

                    {/* Project Bar */}
                    {project.startDate && project.endDate && (
                      <div
                        className={clsx('absolute top-6 h-8 rounded-lg shadow-sm opacity-90 transition-transform hover:scale-[1.01] cursor-pointer flex items-center px-3', color)}
                        style={{
                          left: `${getLeftOffset(project.startDate)}%`,
                          width: `${getWidth(project.startDate, project.endDate)}%`,
                        }}
                      >
                        <span className="text-white text-xs font-medium truncate">{project.name}</span>
                      </div>
                    )}
                  </div>
                </div>
              );
            })
          )}
        </div>
      </div>

      <ProjectModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onSave={handleSaveProject}
      />
    </div>
  );
}

