                  </SettingRow>
                  <SettingRow title="Weekly Digest" description="Receive a weekly summary of your productivity.">
                    <ToggleSwitch enabled={notifications.weeklyDigest} onToggle={() => setNotifications(p => ({ ...p, weeklyDigest: !p.weeklyDigest }))} />
                  </SettingRow>
