function CalendarMiniView({ tasks }: { tasks: Task[] }) {
  const now = new Date();
  const year = now.getFullYear();
  const month = now.getMonth();
  const firstDay = new Date(year, month, 1);
  const lastDay = new Date(year, month + 1, 0);
  const startPad = firstDay.getDay();
  const daysInMonth = lastDay.getDate();
  const days: (number | null)[] = [
    ...Array(startPad).fill(null),
    ...Array.from({ length: daysInMonth }, (_, i) => i + 1),
  ];

  const tasksByDate: Record<number, Task[]> = {};
  tasks.forEach(t => {
    if (!t.dueDate) return;
    try {
      const d = parseISO(t.dueDate);
      if (d.getMonth() === month && d.getFullYear() === year) {
        const day = d.getDate();
        if (!tasksByDate[day]) tasksByDate[day] = [];
        tasksByDate[day].push(t);
      }
    } catch {}
  });

  return (
    <div className="rounded-2xl border p-5" style={{ background: 'var(--color-surface)', borderColor: 'var(--color-border)', boxShadow: 'var(--shadow-xs)' }}>
      <h3 className="mb-4 text-sm font-semibold" style={{ color: 'var(--color-foreground)' }}>
        {format(now, 'MMMM yyyy')}
      </h3>
      <div className="grid grid-cols-7 gap-1 text-center">
        {['S', 'M', 'T', 'W', 'T', 'F', 'S'].map((d, i) => (
          <div key={i} className="py-1 text-[10px] font-bold uppercase" style={{ color: 'var(--color-muted)' }}>{d}</div>
        ))}
        {days.map((day, i) => {
          if (day === null) return <div key={`p${i}`} />;
          const dayTasks = tasksByDate[day] || [];
          const today = isToday(new Date(year, month, day));
          return (
            <div
              key={day}
              className={clsx(
                'relative flex flex-col items-center rounded-lg py-1.5 transition-colors',
                today && 'font-bold',
              )}
              style={{
                background: today ? 'var(--color-accent-light)' : 'transparent',
                color: today ? 'var(--color-accent)' : dayTasks.length > 0 ? 'var(--color-foreground)' : 'var(--color-muted)',
              }}
            >
              <span className="text-[11px]">{day}</span>
              {dayTasks.length > 0 && (
                <div className="mt-0.5 flex gap-0.5">
                  {dayTasks.slice(0, 3).map((t, j) => {
                    const p = getPriorityStyle(t.priority);
                    return <span key={j} className="h-1 w-1 rounded-full" style={{ background: p.text }} />;
                  })}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

export default function TasksPage() {
  const { tasks, fetchTasks, createTask, reorderTask, loading } = useTaskStore();
  const workspace = useAuthStore(s => s.workspace);
  const workspaceId = workspace?._id || '';

  const [view, setView] = useState<ViewMode>('kanban');
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [priorityFilter, setPriorityFilter] = useState<string>('all');
  const [quickTitle, setQuickTitle] = useState('');
  const [localTasks, setLocalTasks] = useState<Task[]>([]);
  const [activeTask, setActiveTask] = useState<Task | null>(null);
  const [listSort, setListSort] = useState<SortField>('title');
  const [listSortAsc, setListSortAsc] = useState(true);

  useEffect(() => {
    if (workspaceId) fetchTasks(workspaceId);
  }, [fetchTasks, workspaceId]);

  useEffect(() => {
    setLocalTasks(tasks as unknown as Task[]);
  }, [tasks]);

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 5 } }),
    useSensor(KeyboardSensor),
  );

  const filtered = useMemo(() => {
    return localTasks.filter(t => {
      if (search && !t.title.toLowerCase().includes(search.toLowerCase())) return false;
      if (statusFilter !== 'all' && t.status !== statusFilter) return false;
      if (priorityFilter !== 'all' && t.priority !== priorityFilter) return false;
      return true;
    });
  }, [localTasks, search, statusFilter, priorityFilter]);

  const sorted = useMemo(() => {
    return [...filtered].sort((a, b) => {
      let cmp = 0;
      switch (listSort) {
        case 'title': cmp = a.title.localeCompare(b.title); break;
        case 'status': cmp = (a.status).localeCompare(b.status); break;
        case 'priority': cmp = (PRIORITY_ORDER[a.priority] ?? 9) - (PRIORITY_ORDER[b.priority] ?? 9); break;
        case 'assignee': cmp = (a.assignee || '').localeCompare(b.assignee || ''); break;
        case 'dueDate': cmp = (a.dueDate || '').localeCompare(b.dueDate || ''); break;
      }
      return listSortAsc ? cmp : -cmp;
    });
  }, [filtered, listSort, listSortAsc]);

  const statusCounts = useMemo(() => {
    const counts: Record<string, number> = { todo: 0, 'in-progress': 0, review: 0, done: 0 };
    filtered.forEach(t => { counts[t.status] = (counts[t.status] || 0) + 1; });
    return counts;
  }, [filtered]);

  const handleQuickAdd = () => {
    if (!quickTitle.trim()) return;
    createTask({
      title: quickTitle.trim(),
      status: 'todo',
      priority: 'medium',
      workspaceId,
    });
    setQuickTitle('');
  };

  const handleDragStart = (e: DragStartEvent) => {
    const task = localTasks.find(t => t._id === e.active.id);
    if (task) setActiveTask(task);
  };

  const handleDragOver = (e: DragOverEvent) => {
    const { active, over } = e;
    if (!over) return;
    const activeId = active.id;
    const overId = over.id;
    if (activeId === overId) return;

    const isOverTask = over.data.current?.type === 'Task';
    const isOverColumn = over.data.current?.type === 'Column';

    setLocalTasks(prev => {
      const activeIndex = prev.findIndex(t => t._id === activeId);
      if (activeIndex === -1) return prev;
      const updated = [...prev];

      if (isOverTask) {
        const overIndex = prev.findIndex(t => t._id === overId);
        if (overIndex === -1) return prev;
        if (updated[activeIndex].status !== updated[overIndex].status) {
          updated[activeIndex] = { ...updated[activeIndex], status: updated[overIndex].status };
        }
        return arrayMove(updated, activeIndex, overIndex);
      }

      if (isOverColumn) {
        updated[activeIndex] = { ...updated[activeIndex], status: overId as Task['status'] };
        return arrayMove(updated, activeIndex, activeIndex);
      }

      return prev;
    });
  };

  const handleDragEnd = (e: DragEndEvent) => {
    setActiveTask(null);
  };

  const toggleSort = (field: SortField) => {
    if (listSort === field) setListSortAsc(!listSortAsc);
    else { setListSort(field); setListSortAsc(true); }
  };

  const viewButtons: { mode: ViewMode; icon: typeof LayoutGrid; label: string }[] = [
    { mode: 'kanban', icon: LayoutGrid, label: 'Kanban' },
    { mode: 'list', icon: List, label: 'List' },
    { mode: 'calendar', icon: CalendarDays, label: 'Calendar' },
  ];

  return (
    <div className="page flex flex-col h-[calc(100vh-80px)] relative z-10">
      {/* Header */}
      <div className="mb-6 flex shrink-0 flex-col gap-4 lg:flex-row lg:items-end lg:justify-between">
        <div>
          <h1 className="page-title mb-0">Tasks</h1>
          <p className="mt-1 text-sm font-medium" style={{ color: 'var(--color-muted)' }}>
            {filtered.length} task{filtered.length !== 1 ? 's' : ''} across your workflow
          </p>
        </div>

        <div className="flex items-center gap-3">
          <div
            className="inline-flex rounded-xl p-1"
            style={{ background: 'var(--color-surface-active)', border: '1px solid var(--color-border)' }}
          >
            {viewButtons.map(vb => (
              <button
                key={vb.mode}
                onClick={() => setView(vb.mode)}
                className={clsx(
                  'flex items-center gap-1.5 rounded-lg px-3 py-1.5 text-[12px] font-semibold transition-all',
                )}
                style={{
                  background: view === vb.mode ? 'var(--color-surface)' : 'transparent',
                  color: view === vb.mode ? 'var(--color-accent)' : 'var(--color-muted)',
                  boxShadow: view === vb.mode ? 'var(--shadow-sm)' : 'none',
                }}
              >
                <vb.icon size={14} />
                {vb.label}
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Filter Bar */}
      <div
        className="mb-4 flex flex-col gap-3 rounded-2xl border p-3 sm:flex-row sm:items-center"
        style={{ background: 'var(--color-surface)', borderColor: 'var(--color-border)', boxShadow: 'var(--shadow-xs)' }}
      >
        <div className="search-input flex-1">
          <Search size={16} style={{ color: 'var(--color-muted)' }} />
          <input
            placeholder="Search tasks..."
            value={search}
            onChange={e => setSearch(e.target.value)}
          />
          {search && (
            <button onClick={() => setSearch('')} className="rounded p-0.5 transition-colors hover:bg-[color:var(--color-surface-active)]">
              <X size={14} style={{ color: 'var(--color-muted)' }} />
            </button>
          )}
        </div>

        <select
          value={statusFilter}
          onChange={e => setStatusFilter(e.target.value)}
          className="rounded-xl border px-3 py-2 text-[12px] font-medium outline-none transition-all"
          style={{ background: 'var(--color-surface)', borderColor: 'var(--color-border)', color: 'var(--color-foreground)' }}
        >
          {STATUS_OPTIONS.map(s => (
            <option key={s} value={s}>{statusLabels[s]}{s !== 'all' && statusCounts[s] !== undefined ? ` (${statusCounts[s]})` : ''}</option>
          ))}
        </select>

        <select
          value={priorityFilter}
          onChange={e => setPriorityFilter(e.target.value)}
          className="rounded-xl border px-3 py-2 text-[12px] font-medium outline-none transition-all"
          style={{ background: 'var(--color-surface)', borderColor: 'var(--color-border)', color: 'var(--color-foreground)' }}
        >
          {PRIORITY_OPTIONS.map(p => (
            <option key={p} value={p}>{priorityLabels[p]}</option>
          ))}
        </select>

        {(search || statusFilter !== 'all' || priorityFilter !== 'all') && (
          <button
            onClick={() => { setSearch(''); setStatusFilter('all'); setPriorityFilter('all'); }}
            className="flex items-center gap-1 rounded-lg px-2.5 py-1.5 text-[12px] font-semibold transition-colors"
            style={{ color: 'var(--color-danger)', background: 'var(--color-danger-light)' }}
          >
            <X size={12} />
            Clear
          </button>
        )}
      </div>

      {/* Quick Add */}
      <div
        className="mb-4 flex items-center gap-3 rounded-2xl border p-2.5"
        style={{ background: 'var(--color-surface)', borderColor: 'var(--color-border)', boxShadow: 'var(--shadow-xs)' }}
      >
        <div className="flex h-8 w-8 items-center justify-center rounded-lg" style={{ background: 'var(--color-accent-light)' }}>
          <Plus size={16} style={{ color: 'var(--color-accent)' }} />
        </div>
        <input
          value={quickTitle}
          onChange={e => setQuickTitle(e.target.value)}
          onKeyDown={e => e.key === 'Enter' && handleQuickAdd()}
          placeholder="Quick add a task..."
          className="flex-1 bg-transparent text-[13px] font-medium outline-none"
          style={{ color: 'var(--color-foreground)' }}
        />
        {quickTitle.trim() && (
          <button
            onClick={handleQuickAdd}
            className="rounded-lg px-3 py-1.5 text-[12px] font-semibold transition-all"
            style={{ background: 'var(--color-accent)', color: 'white' }}
          >
            Add
          </button>
        )}
      </div>

      {/* Content */}
      <div className="flex-1 min-h-0 overflow-hidden">
        {loading && <LoadingSpinner text="Loading tasks..." />}

        {!loading && view === 'kanban' && (
          filtered.length === 0 ? <EmptyState message="Try adjusting your filters to see more tasks." /> :
          <DndContext
            sensors={sensors}
            collisionDetection={closestCorners}
            onDragStart={handleDragStart}
            onDragOver={handleDragOver}
            onDragEnd={handleDragEnd}
          >
            <div className="flex gap-5 overflow-x-auto pb-4 pt-1 h-full" style={{ scrollbarWidth: 'thin' }}>
              {COLUMNS.map(col => (
                <KanbanColumn
                  key={col.id}
                  colId={col.id}
                  label={col.label}
                  color={col.color}
                  tasks={filtered.filter(t => t.status === col.id)}
                  onTaskClick={() => {}}
                />
              ))}
            </div>
            <DragOverlay>
              {activeTask ? <KanbanOverlay task={activeTask} /> : null}
            </DragOverlay>
          </DndContext>
        )}

        {!loading && view === 'list' && (
          filtered.length === 0 ? <EmptyState message="Try adjusting your filters to see more tasks." /> :
          <div
            className="rounded-2xl border overflow-hidden"
            style={{ background: 'var(--color-surface)', borderColor: 'var(--color-border)', boxShadow: 'var(--shadow-xs)' }}
          >
            <table className="w-full text-sm">
              <thead>
                <tr style={{ borderBottom: '1px solid var(--color-border)', background: 'var(--color-surface-hover)' }}>
                  <th className="w-10 px-4 py-3" />
                  {(
                    [
                      { key: 'title' as SortField, label: 'Task', width: '' },
                      { key: 'status' as SortField, label: 'Status', width: 'w-[130px]' },
                      { key: 'priority' as SortField, label: 'Priority', width: 'w-[110px]' },
                      { key: 'assignee' as SortField, label: 'Assignee', width: 'w-[160px]' },
                      { key: 'dueDate' as SortField, label: 'Due', width: 'w-[100px]' },
                    ] as const
                  ).map(col => (
                    <th
                      key={col.key}
                      className={clsx('px-4 py-3 text-left text-[11px] font-bold uppercase tracking-wider cursor-pointer select-none', col.width)}
                      style={{ color: 'var(--color-muted)' }}
                      onClick={() => toggleSort(col.key)}
                    >
                      <span className="inline-flex items-center gap-1">
                        {col.label}
                        {listSort === col.key && (
                          listSortAsc ? <ChevronUp size={12} /> : <ChevronDown size={12} />
                        )}
                        {listSort !== col.key && <ArrowUpDown size={10} className="opacity-30" />}
                      </span>
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                <AnimatePresence>
                  {sorted.map((task, i) => (
                    <ListRow key={task._id} task={task} index={i} onClick={() => {}} />
                  ))}
                </AnimatePresence>
              </tbody>
            </table>
          </div>
        )}

        {!loading && view === 'calendar' && (
          <CalendarMiniView tasks={filtered} />
        )}
      </div>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { useWorkspaceStore } from '../store/workspaceStore';
import { useDashboardStore } from '../store/dashboardStore';
import DashboardWidgetEngine from '../components/dashboard/DashboardWidgetEngine';
import { Settings, Save, X } from 'lucide-react';
import { Button } from '../components/ui/Button';

export default function TeamDashboardPage() {
  const currentWorkspace = useWorkspaceStore(s => s.currentWorkspace);
  const { dashboard, fetchDashboard, updateLayout, saveDashboard, loading } = useDashboardStore();
  
  const [isEditing, setIsEditing] = useState(false);

  useEffect(() => {
    if (currentWorkspace?._id) {
      fetchDashboard(currentWorkspace._id);
    }
  }, [currentWorkspace?._id]);

  if (!currentWorkspace) return null;
  if (loading) return <div className="p-8 text-[color:var(--color-muted)]">Loading dashboard...</div>;
  if (!dashboard) return <div className="p-8 text-[color:var(--color-muted)]">No dashboard configured.</div>;

  const handleSave = async () => {
    await saveDashboard();
    setIsEditing(false);
  };

  return (
    <div className="flex h-full flex-col overflow-hidden bg-[color:var(--color-background)]">
      <div className="flex items-center justify-between border-b p-6" style={{ borderColor: 'var(--color-border-light)' }}>
        <div>
          <h1 className="text-2xl font-bold" style={{ color: 'var(--color-foreground)' }}>{dashboard.name}</h1>
          <p className="mt-1 text-sm text-[color:var(--color-muted)]">
            Command center for {currentWorkspace.name}
          </p>
        </div>
        <div className="flex items-center gap-3">
          {isEditing ? (
            <>
              <Button variant="secondary" onClick={() => setIsEditing(false)}>
                <X size={16} className="mr-2" /> Cancel
              </Button>
              <Button onClick={handleSave}>
                <Save size={16} className="mr-2" /> Save Layout
              </Button>
            </>
          ) : (
            <Button variant="secondary" onClick={() => setIsEditing(true)}>
              <Settings size={16} className="mr-2" /> Customize
            </Button>
          )}
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-6">
        <DashboardWidgetEngine 
          layout={dashboard.layout} 
          onChange={updateLayout}
          isEditing={isEditing}
        />
      </div>
    </div>
  );
}

import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Plus, Trash2, FileText, Copy, Pencil, X, Check,
} from 'lucide-react';
import toast from 'react-hot-toast';
import { useTemplateStore, type TaskTemplate } from '../store/templateStore';
import { useTaskStore } from '../store/taskStore';
import { useAuthStore } from '../store/authStore';

const PRIORITY_OPTIONS = [
  { value: 'low', label: 'Low', color: 'var(--color-muted)' },
  { value: 'medium', label: 'Medium', color: 'var(--color-accent)' },
  { value: 'high', label: 'High', color: 'var(--color-warning)' },
  { value: 'urgent', label: 'Urgent', color: 'var(--color-danger)' },
];

export default function TemplatesPage() {
  const { templates, addTemplate, removeTemplate, updateTemplate } = useTemplateStore();
  const createTask = useTaskStore(s => s.createTask);
  const workspace = useAuthStore(s => s.workspace);
  const [showCreate, setShowCreate] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [form, setForm] = useState({ name: '', title: '', description: '', priority: 'medium' });

  const resetForm = () => setForm({ name: '', title: '', description: '', priority: 'medium' });

  const handleCreate = () => {
    if (!form.name.trim() || !form.title.trim()) {
      toast.error('Template name and task title are required');
      return;
    }
    addTemplate({
      name: form.name.trim(),
      title: form.title.trim(),
      description: form.description.trim() || undefined,
      priority: form.priority,
    });
    toast.success('Template created');
    resetForm();
    setShowCreate(false);
  };

  const handleApply = async (template: TaskTemplate) => {
    if (!workspace?._id) return;
    try {
      await createTask({
        title: template.title,
        description: template.description,
        priority: template.priority,
        workspaceId: workspace._id,
        status: 'todo',
      } as any);
      toast.success(`Task created from "${template.name}"`);
    } catch {
      toast.error('Failed to create task from template');
    }
  };

  const handleDuplicate = (template: TaskTemplate) => {
    addTemplate({
      name: `${template.name} (copy)`,
      title: template.title,
      description: template.description,
      priority: template.priority,
    });
    toast.success('Template duplicated');
  };

  return (
    <div className="page">
      <div className="page-header">
        <div>
          <h1 className="page-title">Task Templates</h1>
          <p className="page-subtitle">Save reusable task blueprints to speed up your workflow.</p>
        </div>
        <button onClick={() => { resetForm(); setShowCreate(true); }} className="btn btn-primary btn-sm">
          <Plus size={14} />
          New Template
        </button>
      </div>

      {/* Create/Edit Modal */}
      <AnimatePresence>
        {showCreate && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-50 flex items-center justify-center p-4"
            style={{ background: 'rgba(0,0,0,0.5)', backdropFilter: 'blur(4px)' }}
            onClick={() => setShowCreate(false)}
          >
            <motion.div
              initial={{ scale: 0.95, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.95, opacity: 0 }}
              className="card w-full max-w-md"
              onClick={(e) => e.stopPropagation()}
            >
              <div className="card-header flex items-center justify-between">
                <h3 className="text-base font-semibold" style={{ color: 'var(--color-foreground)' }}>
                  {editingId ? 'Edit Template' : 'New Template'}
                </h3>
                <button onClick={() => { setShowCreate(false); setEditingId(null); }} className="btn btn-ghost btn-sm p-1">
                  <X size={16} />
                </button>
              </div>
              <div className="card-body flex flex-col gap-4">
                <div>
                  <label className="mb-1 block text-xs font-semibold" style={{ color: 'var(--color-muted)' }}>Template Name</label>
                  <input
                    className="input"
                    placeholder="e.g. Bug Report"
                    value={form.name}
                    onChange={(e) => setForm(f => ({ ...f, name: e.target.value }))}
                  />
                </div>
                <div>
                  <label className="mb-1 block text-xs font-semibold" style={{ color: 'var(--color-muted)' }}>Task Title</label>
                  <input
                    className="input"
                    placeholder="e.g. Fix login redirect bug"
                    value={form.title}
                    onChange={(e) => setForm(f => ({ ...f, title: e.target.value }))}
                  />
                </div>
                <div>
                  <label className="mb-1 block text-xs font-semibold" style={{ color: 'var(--color-muted)' }}>Description (optional)</label>
                  <textarea
                    className="input min-h-[80px] resize-y"
                    placeholder="Steps, context, etc."
                    value={form.description}
                    onChange={(e) => setForm(f => ({ ...f, description: e.target.value }))}
                  />
                </div>
                <div>
                  <label className="mb-1 block text-xs font-semibold" style={{ color: 'var(--color-muted)' }}>Priority</label>
                  <div className="flex gap-2">
                    {PRIORITY_OPTIONS.map(opt => (
                      <button
                        key={opt.value}
                        onClick={() => setForm(f => ({ ...f, priority: opt.value }))}
                        className="rounded-lg px-3 py-1.5 text-xs font-semibold transition-all"
                        style={{
                          background: form.priority === opt.value ? opt.color : 'var(--color-surface-hover)',
                          color: form.priority === opt.value ? 'white' : 'var(--color-muted)',
                          border: `1px solid ${form.priority === opt.value ? opt.color : 'var(--color-border-light)'}`,
                        }}
                      >
                        {opt.label}
                      </button>
                    ))}
                  </div>
                </div>
                <div className="flex justify-end gap-2 pt-2">
                  <button onClick={() => { setShowCreate(false); setEditingId(null); }} className="btn btn-ghost btn-sm">Cancel</button>
                  <button onClick={handleCreate} className="btn btn-primary btn-sm">
                    <Check size={14} />
                    {editingId ? 'Update' : 'Create'}
                  </button>
                </div>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Template List */}
      {templates.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-20 text-center">
          <div
            className="mb-4 flex h-16 w-16 items-center justify-center rounded-2xl"
            style={{ background: 'var(--color-surface-hover)', color: 'var(--color-muted)' }}
          >
            <FileText size={28} />
          </div>
          <h3 className="mb-1 text-base font-bold" style={{ color: 'var(--color-foreground)' }}>No templates yet</h3>
          <p className="mb-4 text-sm" style={{ color: 'var(--color-muted)' }}>
            Create your first template to reuse common task structures.
          </p>
          <button onClick={() => { resetForm(); setShowCreate(true); }} className="btn btn-primary btn-sm">
            <Plus size={14} />
            Create Template
          </button>
        </div>
      ) : (
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {templates.map((template, i) => (
            <motion.div
              key={template.id}
              initial={{ opacity: 0, y: 12 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ delay: i * 0.05 }}
              className="card group"
            >
              <div className="card-body">
                <div className="mb-3 flex items-start justify-between">
                  <div className="min-w-0 flex-1">
                    <h3 className="text-sm font-bold truncate" style={{ color: 'var(--color-foreground)' }}>
                      {template.name}
                    </h3>
                    <p className="mt-0.5 text-xs" style={{ color: 'var(--color-muted)' }}>
                      {template.title}
                    </p>
                  </div>
                  <span
                    className="shrink-0 rounded-full px-2 py-0.5 text-[10px] font-bold uppercase"
                    style={{
                      background: PRIORITY_OPTIONS.find(p => p.value === template.priority)?.color || 'var(--color-muted)',
                      color: 'white',
                    }}
                  >
                    {template.priority}
                  </span>
                </div>
                {template.description && (
                  <p className="mb-3 line-clamp-2 text-xs leading-relaxed" style={{ color: 'var(--color-muted)' }}>
                    {template.description}
                  </p>
                )}
                <div className="flex gap-2">
                  <button
                    onClick={() => handleApply(template)}
                    className="btn btn-primary btn-xs flex-1"
                  >
                    <Copy size={12} />
                    Use
                  </button>
                  <button
                    onClick={() => handleDuplicate(template)}
                    className="btn btn-ghost btn-xs"
                    title="Duplicate"
                  >
                    <Copy size={12} />
                  </button>
                  <button
                    onClick={() => {
                      removeTemplate(template.id);
                      toast.success('Template deleted');
                    }}
                    className="btn btn-ghost btn-xs"
                    style={{ color: 'var(--color-danger)' }}
                    title="Delete"
                  >
                    <Trash2 size={12} />
                  </button>
                </div>
              </div>
            </motion.div>
          ))}
        </div>
      )}
    </div>
  );
}

