import { useState, useRef, useEffect } from 'react';
import { Pen, Square, Circle, Eraser, MousePointer2, Plus, Users, Share2, ChevronDown } from 'lucide-react';
import clsx from 'clsx';
import { useWhiteboardStore } from '../store/whiteboardStore';
import { useAuthStore } from '../store/authStore';
import WhiteboardModal from '../components/whiteboards/WhiteboardModal';
import LoadingSpinner from '../components/ui/LoadingSpinner';

export default function WhiteboardPage() {
  const [activeTool, setActiveTool] = useState<'select' | 'pen' | 'square' | 'circle' | 'eraser'>('pen');
  const [isDrawing, setIsDrawing] = useState(false);
  const [currentPath, setCurrentPath] = useState<string>('');
  
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [activeBoard, setActiveBoard] = useState<any>(null);

  const { whiteboards, fetchWhiteboards, createWhiteboard, updateWhiteboard, loading } = useWhiteboardStore() as any;
  const workspace = useAuthStore(s => s.workspace);
  const canvasRef = useRef<HTMLDivElement>(null);

  const workspaceId = workspace?._id || '';

  useEffect(() => {
    if (workspaceId) fetchWhiteboards(workspaceId);
  }, [fetchWhiteboards, workspaceId]);

  useEffect(() => {
    if (!activeBoard && whiteboards?.length > 0) {
      setActiveBoard(whiteboards[0]);
    }
  }, [whiteboards, activeBoard]);

  const handlePointerDown = (e: React.PointerEvent) => {
    if (activeTool !== 'pen' || !activeBoard) return;
    const rect = canvasRef.current?.getBoundingClientRect();
    if (!rect) return;
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    
    setIsDrawing(true);
    setCurrentPath(`M ${x} ${y}`);
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!isDrawing || activeTool !== 'pen' || !activeBoard) return;
    const rect = canvasRef.current?.getBoundingClientRect();
    if (!rect) return;
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    
    setCurrentPath((prev) => `${prev} L ${x} ${y}`);
  };

  const handlePointerUp = () => {
    if (!isDrawing || !activeBoard) return;
    setIsDrawing(false);
    if (currentPath) {
      const newElements = [...(activeBoard.elements || []), { type: 'path', data: currentPath }];
      const updatedBoard = { ...activeBoard, elements: newElements };
      setActiveBoard(updatedBoard);
      setCurrentPath('');
      updateWhiteboard(activeBoard._id, { elements: newElements });
    }
  };

  const handleSaveBoard = async (data: any) => {
    const newBoard = await createWhiteboard({ ...data, workspaceId });
    if (newBoard) {
      setActiveBoard(newBoard);
    }
  };

  const tools = [
    { id: 'select', icon: <MousePointer2 size={18} /> },
    { id: 'pen', icon: <Pen size={18} /> },
    { id: 'square', icon: <Square size={18} /> },
    { id: 'circle', icon: <Circle size={18} /> },
    { id: 'eraser', icon: <Eraser size={18} /> },
  ];

  return (
    <div className="page flex flex-col h-[calc(100vh-80px)] p-0 bg-white rounded-3xl border border-border shadow-sm overflow-hidden relative z-10">
      
      {/* Header Toolbar */}
      <div className="absolute top-6 left-6 right-6 z-20 flex items-center justify-between pointer-events-none">
        
        {/* Board Title & Selector */}
        <div className="bg-white/90 backdrop-blur-md px-4 py-2.5 rounded-xl flex items-center gap-3 pointer-events-auto shadow-sm border border-border">
          <div className="w-10 h-10 rounded-lg bg-blue-50 text-blue-600 flex items-center justify-center shrink-0">
            <Pen size={18} />
          </div>
          <div className="relative flex flex-col">
            <div className="flex items-center">
              <select 
                 className="bg-transparent outline-none appearance-none cursor-pointer text-sm font-bold text-gray-900 tracking-wide pr-6 z-10"
                 value={activeBoard?._id || ''}
                 onChange={(e) => {
                   if (e.target.value === 'new') setIsModalOpen(true);
                   else setActiveBoard(whiteboards.find((w: any) => w._id === e.target.value));
                 }}
               >
                 {whiteboards.length === 0 && <option value="" disabled>No boards</option>}
                 {whiteboards.map((w: any) => <option key={w._id} value={w._id}>{w.title}</option>)}
                 <option value="new">+ Create New Board</option>
               </select>
               <ChevronDown size={14} className="absolute right-0 text-gray-400 pointer-events-none" />
            </div>
            <p className="text-[11px] text-gray-500 font-medium mt-0.5">Auto-saved</p>
          </div>
        </div>

        {/* Tools Palette */}
        <div className="bg-white/90 backdrop-blur-md p-1.5 rounded-2xl flex items-center gap-1 pointer-events-auto shadow-sm border border-border">
          {tools.map((t) => (
            <button
              key={t.id}
              onClick={() => setActiveTool(t.id as any)}
              className={clsx(
                'p-3 rounded-xl transition-all duration-200',
                activeTool === t.id
                  ? 'bg-blue-50 text-blue-600'
                  : 'text-gray-500 hover:bg-gray-100 hover:text-gray-900 border border-transparent'
              )}
            >
              {t.icon}
            </button>
          ))}
        </div>

        {/* Collab / Share */}
        <div className="flex items-center gap-3 pointer-events-auto">
          <div className="flex items-center -space-x-3 mr-1">
            <div className="w-9 h-9 rounded-full border-2 border-white bg-blue-500 text-white flex items-center justify-center text-xs font-bold z-20 shadow-sm">J</div>
            <div className="w-9 h-9 rounded-full border-2 border-white bg-amber-500 text-white flex items-center justify-center text-xs font-bold z-10 shadow-sm">A</div>
            <div className="w-9 h-9 rounded-full border-2 border-white bg-gray-100 text-gray-500 flex items-center justify-center text-xs font-bold hover:bg-gray-200 transition-colors cursor-pointer"><Plus size={14}/></div>
          </div>
          <button className="bg-white/90 backdrop-blur-md p-2.5 rounded-xl text-gray-600 hover:text-blue-600 hover:bg-blue-50 transition-colors shadow-sm border border-border">
            <Share2 size={18} />
          </button>
        </div>
      </div>

      {/* Infinite Canvas Area */}
      {loading ? (
        <div className="flex-1 w-full h-full flex items-center justify-center">
          <LoadingSpinner text="Loading whiteboards..." />
        </div>
      ) : (
      <div
        ref={canvasRef}
        className="flex-1 w-full h-full bg-[radial-gradient(#e5e5e5_1px,transparent_1px)] [background-size:24px_24px] cursor-crosshair touch-none"
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerUp}
      >
        {!activeBoard ? (
          <div className="w-full h-full flex items-center justify-center">
            <button 
              onClick={() => setIsModalOpen(true)}
              className="btn-primary px-6 py-3 shadow-lg"
            >
              + Create Whiteboard
            </button>
          </div>
        ) : (
          <svg className="w-full h-full pointer-events-none">
            {activeBoard?.elements?.map((el: any, i: number) => (
              <path
                key={i}
                d={el.data}
                fill="none"
                stroke="#0071e3"
                strokeWidth="4"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            ))}
            {isDrawing && currentPath && (
              <path
                d={currentPath}
                fill="none"
                stroke="#0071e3"
                strokeWidth="4"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            )}
          </svg>
        )}
      </div>
      )}

      <WhiteboardModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onSave={handleSaveBoard}
      />
    </div>
  );
}

import { useState } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import * as z from 'zod';
import { ArrowLeft, Mail, MailCheck } from 'lucide-react';
import { Link } from 'react-router-dom';
import toast from 'react-hot-toast';
import { sendResetEmail } from '../../services/firebase';
import { AuthLayout } from '../../components/auth/AuthLayout';
import { AuthHeading, TextField, SubmitButton } from '../../components/auth/AuthFields';

const schema = z.object({
  email: z.string().email('Enter a valid email address'),
});
type Values = z.infer<typeof schema>;

export default function ForgotPasswordPage() {
  const [isLoading, setIsLoading] = useState(false);
  const [isSent, setIsSent] = useState(false);
  const {
    register,
    handleSubmit,
    formState: { errors },
  } = useForm<Values>({ resolver: zodResolver(schema as any) as any });

  const onSubmit = async ({ email }: Values) => {
    setIsLoading(true);
    try {
      await sendResetEmail(email);
      setIsSent(true);
      toast.success('Reset email sent.');
    } catch (error: any) {
      toast.error(error.message || 'Unable to send reset email.');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <AuthLayout>
      <AuthHeading title="Forgot your password?" subtitle="No problem ΓÇö we'll send you a secure reset link." />

      {isSent ? (
        <div className="rounded-3xl border border-emerald-500/20 bg-emerald-500/[0.06] p-8 text-center">
          <div className="mx-auto mb-5 flex h-16 w-16 items-center justify-center rounded-2xl bg-emerald-500/15 text-emerald-600 dark:text-emerald-300">
            <MailCheck size={30} />
          </div>
          <h2 className="text-lg font-extrabold text-navy-950 dark:text-white">Check your inbox</h2>
          <p className="mt-2 text-sm leading-relaxed text-slate-500 dark:text-slate-400">
            We've sent a password reset link. If it doesn't arrive within a few minutes, check your spam folder.
          </p>
          <button
            type="button"
            onClick={() => setIsSent(false)}
            className="mt-6 text-sm font-bold text-brand-600 transition-colors hover:text-brand-700 dark:text-brand-300 dark:hover:text-brand-200"
          >
            Try a different email
          </button>
        </div>
      ) : (
        <form onSubmit={handleSubmit(onSubmit)} className="space-y-5">
          <div className="relative">
            <Mail size={18} className="pointer-events-none absolute left-4 top-[38px] -translate-y-1/2 text-slate-400" />
            <TextField
              id="email"
              label="Email"
              type="email"
              placeholder="you@example.com"
              autoComplete="email"
              className="pl-11"
              error={errors.email?.message}
              {...register('email')}
            />
          </div>
          <SubmitButton loading={isLoading}>{isLoading ? 'Sending...' : 'Send reset link'}</SubmitButton>
        </form>
      )}

      <div className="mt-8 text-center">
        <Link
          to="/login"
          className="inline-flex items-center gap-1.5 text-sm font-semibold text-slate-500 transition-colors hover:text-navy-900 dark:text-slate-400 dark:hover:text-white"
        >
          <ArrowLeft size={16} />
          Back to login
        </Link>
      </div>
    </AuthLayout>
  );
}

import { useState } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import * as z from 'zod';
import { ArrowRight, Phone, Check } from 'lucide-react';
import { Link, useNavigate } from 'react-router-dom';
import toast from 'react-hot-toast';
import { signInWithEmail, signInWithGoogle } from '../../services/firebase';
import { useAuthStore } from '../../store/authStore';
import { AuthLayout } from '../../components/auth/AuthLayout';
import { AuthHeading, TextField, PasswordField, GoogleButton, AuthDivider, SubmitButton } from '../../components/auth/AuthFields';

const loginSchema = z.object({
  email: z.string().email('Enter a valid email address'),
  password: z.string().min(8, 'Password must be at least 8 characters'),
  rememberMe: z.boolean(),
});

type LoginFormValues = z.infer<typeof loginSchema>;

export default function LoginPage() {
  const navigate = useNavigate();
  const completeFirebaseSignIn = useAuthStore((state) => state.completeFirebaseSignIn);
  const [isLoading, setIsLoading] = useState(false);
  const {
    register,
    handleSubmit,
    getValues,
    formState: { errors },
  } = useForm<LoginFormValues>({
    resolver: zodResolver(loginSchema as any) as any,
    defaultValues: { rememberMe: true },
  });

  const finishSignIn = async (rememberMe: boolean) => {
    const user = await completeFirebaseSignIn(rememberMe);
    toast.success('Welcome back!');
    navigate(user.authProvider === 'email' && !user.emailVerified ? '/verify-email' : '/dashboard');
  };

  const onSubmit = async ({ email, password, rememberMe }: LoginFormValues) => {
    setIsLoading(true);
    try {
      await signInWithEmail(email, password, rememberMe);
      await finishSignIn(rememberMe);
    } catch (error: any) {
      const msg = error?.message || 'Login failed. Please try again.';
      if (msg.includes('user-not-found')) {
        toast.error('No account found with this email.');
      } else if (msg.includes('wrong-password') || msg.includes('invalid-credential')) {
        toast.error('Invalid email or password.');
      } else if (msg.includes('too-many-requests')) {
        toast.error('Too many attempts. Please try again later.');
      } else {
        toast.error(msg);
      }
    } finally {
      setIsLoading(false);
    }
  };

  const handleGoogleSignIn = async () => {
    setIsLoading(true);
    try {
      await signInWithGoogle(getValues('rememberMe'));
      await finishSignIn(getValues('rememberMe'));
    } catch (error: any) {
      const msg = error?.message || 'Google sign-in failed.';
      if (msg.includes('popup-closed-by-user')) {
        toast.error('Sign-in cancelled.');
      } else {
        toast.error(msg);
      }
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <AuthLayout>
      <AuthHeading title="Welcome back" subtitle="Sign in to organize your universe." />

      <GoogleButton onClick={() => void handleGoogleSignIn()} disabled={isLoading} />

      <Link
        to="/phone-login"
        className="mt-3 inline-flex w-full items-center justify-center gap-2 rounded-xl px-4 py-2.5 text-sm font-semibold text-slate-600 transition-colors hover:bg-navy-900/[0.04] hover:text-navy-900 dark:text-slate-300 dark:hover:bg-white/[0.06] dark:hover:text-white"
      >
        <Phone size={16} /> Use your phone number instead
      </Link>

      <AuthDivider />

      <form onSubmit={handleSubmit(onSubmit)} className="space-y-5">
        <TextField
          id="email"
          label="Email"
          type="email"
          placeholder="you@example.com"
          autoComplete="email"
          error={errors.email?.message}
          {...register('email')}
        />

        <div>
          <PasswordField
            id="password"
            label="Password"
            placeholder="ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó"
            autoComplete="current-password"
            error={errors.password?.message}
            {...register('password')}
          />
          <div className="mt-3 flex items-center justify-between">
            <label className="inline-flex cursor-pointer select-none items-center gap-2 text-[13px] font-medium text-slate-600 dark:text-slate-300">
              <input
                type="checkbox"
                className="h-4 w-4 rounded border-navy-900/15 accent-brand-600"
                {...register('rememberMe')}
              />
              Remember me
            </label>
            <Link to="/forgot-password" className="text-[13px] font-semibold text-brand-600 transition-colors hover:text-brand-700 dark:text-brand-300 dark:hover:text-brand-200">
              Forgot password?
            </Link>
          </div>
        </div>

        <SubmitButton loading={isLoading}>
          Sign in to TaMaD
          <ArrowRight size={18} />
        </SubmitButton>
      </form>

      <div className="mt-8 flex items-center justify-center gap-2 text-sm text-slate-500 dark:text-slate-400">
        Don't have an account?
        <Link to="/register" className="font-bold text-brand-600 transition-colors hover:text-brand-700 dark:text-brand-300 dark:hover:text-brand-200">
          Create one free
        </Link>
      </div>

      <p className="mt-6 flex items-center justify-center gap-1.5 text-center text-[11.5px] text-slate-400 dark:text-slate-500">
        <Check size={12} /> Free forever plan ┬╖ No credit card required
      </p>
    </AuthLayout>
  );
}

import { useEffect, useRef, useState } from 'react';
import { ConfirmationResult, RecaptchaVerifier } from 'firebase/auth';
import { ArrowLeft, Loader2, Phone } from 'lucide-react';
import { Link, useNavigate } from 'react-router-dom';
import toast from 'react-hot-toast';
import clsx from 'clsx';
import { createPhoneRecaptcha, startPhoneSignIn } from '../../services/firebase';
import { useAuthStore } from '../../store/authStore';
import { AuthLayout } from '../../components/auth/AuthLayout';
import { AuthHeading, SubmitButton } from '../../components/auth/AuthFields';

const countryCodes = [
  { code: '+1', label: 'US/CA (+1)' },
  { code: '+44', label: 'UK (+44)' },
  { code: '+61', label: 'Australia (+61)' },
  { code: '+91', label: 'India (+91)' },
  { code: '+81', label: 'Japan (+81)' },
  { code: '+49', label: 'Germany (+49)' },
  { code: '+33', label: 'France (+33)' },
  { code: '+55', label: 'Brazil (+55)' },
  { code: '+86', label: 'China (+86)' },
  { code: '+82', label: 'South Korea (+82)' },
  { code: '+39', label: 'Italy (+39)' },
  { code: '+34', label: 'Spain (+34)' },
  { code: '+31', label: 'Netherlands (+31)' },
  { code: '+46', label: 'Sweden (+46)' },
  { code: '+65', label: 'Singapore (+65)' },
];

const inputClasses =
  'h-12 w-full rounded-xl border border-navy-900/10 bg-white/70 px-4 text-[14px] font-medium text-navy-900 outline-none transition-all duration-200 placeholder:text-slate-400 hover:border-navy-900/20 focus:border-brand-600 focus:ring-4 focus:ring-brand-500/10 dark:border-white/10 dark:bg-white/[0.04] dark:text-white dark:hover:border-white/20';

export default function PhoneLoginPage() {
  const navigate = useNavigate();
  const completeFirebaseSignIn = useAuthStore((state) => state.completeFirebaseSignIn);
  const captchaContainer = useRef<HTMLDivElement>(null);
  const verifier = useRef<RecaptchaVerifier | null>(null);
  const [countryCode, setCountryCode] = useState('+1');
  const [phoneNumber, setPhoneNumber] = useState('');
  const [code, setCode] = useState('');
  const [confirmation, setConfirmation] = useState<ConfirmationResult | null>(null);
  const [secondsRemaining, setSecondsRemaining] = useState(0);
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => () => verifier.current?.clear(), []);

  useEffect(() => {
    if (!secondsRemaining) return;
    const timer = window.setTimeout(() => setSecondsRemaining((v) => v - 1), 1000);
    return () => window.clearTimeout(timer);
  }, [secondsRemaining]);

  const sendCode = async () => {
    const normalizedNumber = phoneNumber.replace(/\D/g, '');
    if (normalizedNumber.length < 7 || normalizedNumber.length > 14) {
      toast.error('Enter a valid phone number.');
      return;
    }

    setIsLoading(true);
    try {
      if (!verifier.current && captchaContainer.current) {
        verifier.current = createPhoneRecaptcha(captchaContainer.current);
      }
      if (!verifier.current) throw new Error('Captcha could not be initialized');
      setConfirmation(await startPhoneSignIn(`${countryCode}${normalizedNumber}`, verifier.current));
      setSecondsRemaining(60);
      toast.success('Verification code sent.');
    } catch (error: any) {
      toast.error(error.message || 'Unable to send verification code.');
    } finally {
      setIsLoading(false);
    }
  };

  const verifyCode = async () => {
    if (!confirmation) return;
    setIsLoading(true);
    try {
      await confirmation.confirm(code);
      await completeFirebaseSignIn(true);
      toast.success('Phone number verified.');
      navigate('/dashboard');
    } catch (error: any) {
      toast.error(error.message || 'The verification code is invalid or expired.');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <AuthLayout>
      <AuthHeading title="Sign in with your phone" subtitle="We'll send a one-time verification code by SMS." />

      {!confirmation ? (
        <div className="space-y-5">
          <div>
            <label htmlFor="phoneNumber" className="mb-1.5 block text-[13px] font-semibold text-navy-900 dark:text-slate-200">
              Phone Number
            </label>
            <div className="flex gap-2">
              <select
                id="countryCode"
                value={countryCode}
                onChange={(e) => setCountryCode(e.target.value)}
                className={clsx(inputClasses, 'w-[124px] shrink-0 cursor-pointer')}
                aria-label="Country code"
              >
                {countryCodes.map(({ code: value, label }) => (
                  <option key={value} value={value}>
                    {label}
                  </option>
                ))}
              </select>
              <input
                id="phoneNumber"
                value={phoneNumber}
                onChange={(e) => setPhoneNumber(e.target.value)}
                className={inputClasses}
                placeholder="5551234567"
                autoComplete="tel-national"
                inputMode="tel"
              />
            </div>
          </div>

          <div ref={captchaContainer} className="overflow-hidden rounded-2xl" />

          <button
            type="button"
            onClick={sendCode}
            disabled={isLoading}
            className="flex h-12 w-full items-center justify-center gap-2 rounded-xl bg-brand-600 text-sm font-bold text-white shadow-[0_8px_30px_rgba(37,99,235,0.35)] transition-all duration-200 hover:-translate-y-0.5 hover:bg-brand-500 disabled:cursor-not-allowed disabled:opacity-70"
          >
            {isLoading ? <Loader2 size={18} className="animate-spin" /> : <Phone size={18} />}
            {isLoading ? 'Sending...' : 'Send verification code'}
          </button>
        </div>
      ) : (
        <div className="space-y-5">
          <div>
            <label htmlFor="otpCode" className="mb-1.5 block text-[13px] font-semibold text-navy-900 dark:text-slate-200">
              Verification Code
            </label>
            <input
              id="otpCode"
              value={code}
              onChange={(e) => setCode(e.target.value.replace(/\D/g, ''))}
              className={clsx(inputClasses, 'text-center text-lg font-bold tracking-[0.4em]')}
              inputMode="numeric"
              maxLength={6}
              placeholder="ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó"
              autoFocus
            />
            <p className="mt-1.5 text-xs text-slate-400 dark:text-slate-500">Enter the 6-digit code we sent to your phone.</p>
          </div>

          <SubmitButton type="button" loading={isLoading} disabled={isLoading || code.length !== 6} onClick={() => void verifyCode()}>
            {isLoading ? 'Verifying...' : 'Verify and sign in'}
          </SubmitButton>

          <button
            type="button"
            onClick={sendCode}
            disabled={isLoading || secondsRemaining > 0}
            className="w-full text-center text-sm font-semibold text-brand-600 transition-colors hover:text-brand-700 disabled:cursor-not-allowed disabled:text-slate-400 dark:text-brand-300 dark:hover:text-brand-200"
          >
            {secondsRemaining ? `Resend code in ${secondsRemaining}s` : 'Resend code'}
          </button>
        </div>
      )}

      <div className="mt-8 text-center">
        <Link
          to="/login"
          className="inline-flex items-center gap-1.5 text-sm font-semibold text-slate-500 transition-colors hover:text-navy-900 dark:text-slate-400 dark:hover:text-white"
        >
          <ArrowLeft size={16} />
          Back to login
        </Link>
      </div>
    </AuthLayout>
  );
}

import { useState } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import * as z from 'zod';
import { ArrowRight, Check } from 'lucide-react';
import { Link, useNavigate } from 'react-router-dom';
import toast from 'react-hot-toast';
import clsx from 'clsx';
import { registerWithEmail } from '../../services/firebase';
import { useAuthStore } from '../../store/authStore';
import { AuthLayout } from '../../components/auth/AuthLayout';
import { AuthHeading, TextField, PasswordField, SubmitButton } from '../../components/auth/AuthFields';

const passwordSchema = z
  .string()
  .min(8, 'Use at least 8 characters')
  .regex(/[A-Z]/, 'Include an uppercase letter')
  .regex(/[a-z]/, 'Include a lowercase letter')
  .regex(/\d/, 'Include a number');

const registerSchema = z
  .object({
    name: z.string().min(2, 'Name must be at least 2 characters'),
    email: z.string().email('Enter a valid email address'),
    password: passwordSchema,
    confirmPassword: z.string(),
  })
  .refine((data) => data.password === data.confirmPassword, {
    message: 'Passwords do not match',
    path: ['confirmPassword'],
  });

type RegisterFormValues = z.infer<typeof registerSchema>;

const requirements = [
  { key: 'length', label: '8+ characters' },
  { key: 'upper', label: 'Uppercase' },
  { key: 'lower', label: 'Lowercase' },
  { key: 'digit', label: 'Number' },
];

export default function RegisterPage() {
  const navigate = useNavigate();
  const completeFirebaseSignIn = useAuthStore((state) => state.completeFirebaseSignIn);
  const [isLoading, setIsLoading] = useState(false);
  const [password, setPassword] = useState('');

  const {
    register,
    handleSubmit,
    formState: { errors },
  } = useForm<RegisterFormValues>({
    resolver: zodResolver(registerSchema as any) as any,
  });

  const met = {
    length: password.length >= 8,
    upper: /[A-Z]/.test(password),
    lower: /[a-z]/.test(password),
    digit: /\d/.test(password),
  };

  const onSubmit = async ({ name, email, password: pw }: RegisterFormValues) => {
    setIsLoading(true);
    try {
      await registerWithEmail(name, email, pw);
      await completeFirebaseSignIn(false);
      toast.success('Account created! Check your email to verify it.');
      navigate('/verify-email');
    } catch (error: any) {
      const msg = error?.message || 'Registration failed.';
      if (msg.includes('email-already-in-use')) {
        toast.error('An account with this email already exists. Try signing in.');
      } else {
        toast.error(msg);
      }
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <AuthLayout wide>
      <div className="mx-auto w-full max-w-md">
        <AuthHeading
          title="Create your account"
          subtitle="Start free forever ΓÇö no credit card required."
        />

        <form onSubmit={handleSubmit(onSubmit)} className="space-y-5">
          <TextField
            id="name"
            label="Full Name"
            placeholder="Ada Lovelace"
            autoComplete="name"
            error={errors.name?.message}
            {...register('name')}
          />

          <TextField
            id="email"
            label="Email"
            type="email"
            placeholder="you@example.com"
            autoComplete="email"
            error={errors.email?.message}
            {...register('email')}
          />

          <PasswordField
            id="password"
            label="Password"
            placeholder="Create a strong password"
            autoComplete="new-password"
            error={errors.password?.message}
            {...register('password', { onChange: (e) => setPassword(e.target.value) })}
          />

          <div className="flex flex-wrap gap-2">
            {requirements.map((req) => {
              const done = met[req.key as keyof typeof met];
              return (
                <span
                  key={req.key}
                  className={clsx(
                    'inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[11px] font-semibold transition-all duration-200',
                    done
                      ? 'border-emerald-500/25 bg-emerald-500/[0.08] text-emerald-600 dark:text-emerald-300'
                      : 'border-navy-900/10 text-slate-400 dark:border-white/10 dark:text-slate-500',
                  )}
                >
                  <span className={clsx('flex h-3.5 w-3.5 items-center justify-center rounded-full', done ? 'bg-emerald-500 text-white' : 'bg-slate-200 dark:bg-white/10')}>
                    {done && <Check size={9} strokeWidth={3.5} />}
                  </span>
                  {req.label}
                </span>
              );
            })}
          </div>

          <PasswordField
            id="confirmPassword"
            label="Confirm Password"
            placeholder="Re-enter your password"
            autoComplete="new-password"
            error={errors.confirmPassword?.message}
            {...register('confirmPassword')}
          />

          <p className="text-[11.5px] leading-relaxed text-slate-400 dark:text-slate-500">
            By creating an account, you agree to TaMaD's Terms of Service and acknowledge the Privacy Policy.
          </p>

          <SubmitButton loading={isLoading}>
            Create account
            <ArrowRight size={18} />
          </SubmitButton>
        </form>

        <div className="mt-8 flex items-center justify-center gap-2 border-t border-navy-900/[0.07] pt-7 text-sm text-slate-500 dark:border-white/[0.08] dark:text-slate-400">
          Already have an account?
          <Link to="/login" className="font-bold text-brand-600 transition-colors hover:text-brand-700 dark:text-brand-300 dark:hover:text-brand-200">
            Sign in
          </Link>
        </div>
      </div>
    </AuthLayout>
  );
}

import { useState } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import * as z from 'zod';
import { ArrowLeft, Lock, ShieldCheck } from 'lucide-react';
import { Link, useSearchParams } from 'react-router-dom';
import toast from 'react-hot-toast';
import { resetFirebasePassword } from '../../services/firebase';
import { AuthLayout } from '../../components/auth/AuthLayout';
import { AuthHeading, PasswordField, SubmitButton } from '../../components/auth/AuthFields';

const schema = z
  .object({
    password: z.string().min(8, 'Use at least 8 characters'),
    confirmPassword: z.string(),
  })
  .refine((data) => data.password === data.confirmPassword, {
    path: ['confirmPassword'],
    message: 'Passwords do not match',
  });
type Values = z.infer<typeof schema>;

export default function ResetPasswordPage() {
  const [params] = useSearchParams();
  const [complete, setComplete] = useState(false);
  const {
    register,
    handleSubmit,
    formState: { errors, isSubmitting },
  } = useForm<Values>({ resolver: zodResolver(schema as any) as any });

  const onSubmit = async ({ password }: Values) => {
    const code = params.get('oobCode');
    if (!code) return toast.error('This reset link is invalid or expired.');
    try {
      await resetFirebasePassword(code, password);
      setComplete(true);
      toast.success('Password updated.');
    } catch (error: any) {
      toast.error(error.message || 'This reset link is invalid or expired.');
    }
  };

  return (
    <AuthLayout>
      <AuthHeading title="Set a new password" subtitle="Choose a strong password to secure your account." />

      {complete ? (
        <div className="rounded-3xl border border-emerald-500/20 bg-emerald-500/[0.06] p-8 text-center">
          <div className="mx-auto mb-5 flex h-16 w-16 items-center justify-center rounded-2xl bg-emerald-500/15 text-emerald-600 dark:text-emerald-300">
            <ShieldCheck size={30} />
          </div>
          <h2 className="text-lg font-extrabold text-navy-950 dark:text-white">Password updated</h2>
          <p className="mt-2 text-sm leading-relaxed text-slate-500 dark:text-slate-400">
            Your password has been reset. Sign in with your new credentials.
          </p>
          <Link
            to="/login"
            className="mt-6 inline-flex h-12 items-center justify-center rounded-xl bg-brand-600 px-6 text-sm font-bold text-white shadow-[0_8px_30px_rgba(37,99,235,0.35)] transition-all hover:-translate-y-0.5 hover:bg-brand-500"
          >
            Sign in
          </Link>
        </div>
      ) : (
        <form onSubmit={handleSubmit(onSubmit)} className="space-y-5">
          <div className="relative">
            <Lock size={18} className="pointer-events-none absolute left-4 top-[38px] -translate-y-1/2 text-slate-400" />
            <PasswordField
              id="password"
              label="New Password"
              placeholder="ΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇóΓÇó"
              autoComplete="new-password"
              className="pl-11"
              error={errors.password?.message}
              {...register('password')}
            />
          </div>
          <PasswordField
            id="confirmPassword"
            label="Confirm Password"
            placeholder="Re-enter your new password"
            autoComplete="new-password"
            error={errors.confirmPassword?.message}
            {...register('confirmPassword')}
          />
          <SubmitButton loading={isSubmitting}>{isSubmitting ? 'Updating...' : 'Update password'}</SubmitButton>
        </form>
      )}

      <div className="mt-8 text-center">
        <Link
          to="/login"
          className="inline-flex items-center gap-1.5 text-sm font-semibold text-slate-500 transition-colors hover:text-navy-900 dark:text-slate-400 dark:hover:text-white"
        >
          <ArrowLeft size={16} />
          Back to login
        </Link>
      </div>
    </AuthLayout>
  );
}

import { useState, useEffect, useRef, useCallback } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { Loader2, Mail, CheckCircle, RefreshCw } from 'lucide-react';
import toast from 'react-hot-toast';
import { getClientAuth, resendVerificationEmail } from '../../services/firebase';
import { useAuthStore } from '../../store/authStore';
import { AuthLayout } from '../../components/auth/AuthLayout';
import { AuthHeading } from '../../components/auth/AuthFields';

const AUTO_CHECK_INTERVAL = 10;

export default function VerifyEmailPage() {
  const navigate = useNavigate();
  const syncEmailVerification = useAuthStore((state) => state.syncEmailVerification);
  const [isSending, setIsSending] = useState(false);
  const [isChecking, setIsChecking] = useState(false);
  const [countdown, setCountdown] = useState(AUTO_CHECK_INTERVAL);
  const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null);

  const checkVerification = useCallback(async () => {
    setIsChecking(true);
    try {
      await getClientAuth().currentUser?.reload();
      const user = await syncEmailVerification();
      if (!user.emailVerified) {
        toast.error('Your email is not verified yet. Please click the link in your email first.');
        return;
      }
      toast.success('Email verified!');
      navigate('/onboarding');
    } catch (error: any) {
      toast.error(error.message || 'Unable to check verification status.');
    } finally {
      setIsChecking(false);
    }
  }, [syncEmailVerification, navigate]);

  const resend = async () => {
    setIsSending(true);
    try {
      await resendVerificationEmail();
      toast.success('Verification email sent. Check your inbox.');
    } catch (error: any) {
      toast.error(error.message || 'Unable to send verification email.');
    } finally {
      setIsSending(false);
    }
  };

  useEffect(() => {
    intervalRef.current = setInterval(() => {
      setCountdown((prev) => {
        if (prev <= 1) {
          checkVerification();
          return AUTO_CHECK_INTERVAL;
        }
        return prev - 1;
      });
    }, 1000);

    return () => {
      if (intervalRef.current) clearInterval(intervalRef.current);
    };
  }, [checkVerification]);

  return (
    <AuthLayout>
      <AuthHeading title="Verify your email" subtitle="One last step before you can organize your universe." />

      <div className="rounded-3xl border border-brand-500/20 bg-brand-500/[0.05] p-8 text-center">
        <div className="mx-auto mb-5 flex h-16 w-16 items-center justify-center rounded-2xl bg-brand-600 text-white shadow-[0_10px_30px_rgba(37,99,235,0.35)]">
          <Mail size={30} />
        </div>
        <p className="text-sm leading-relaxed text-slate-600 dark:text-slate-300">
          We sent a verification link to your inbox. Click it, then come back ΓÇö we'll check automatically every{' '}
          <strong className="font-bold text-navy-950 dark:text-white">{countdown}s</strong>.
        </p>

        <div className="mt-6 space-y-3">
          <button
            type="button"
            onClick={checkVerification}
            disabled={isChecking}
            className="flex h-12 w-full items-center justify-center gap-2 rounded-xl bg-brand-600 text-sm font-bold text-white shadow-[0_8px_30px_rgba(37,99,235,0.35)] transition-all duration-200 hover:-translate-y-0.5 hover:bg-brand-500 disabled:cursor-not-allowed disabled:opacity-70"
          >
            {isChecking ? <Loader2 size={18} className="animate-spin" /> : <CheckCircle size={18} />}
            {isChecking ? 'Checking...' : "I've verified my email"}
          </button>

          <button
            type="button"
            onClick={resend}
            disabled={isSending}
            className="inline-flex w-full items-center justify-center gap-2 rounded-xl px-4 py-2.5 text-sm font-semibold text-brand-600 transition-colors hover:bg-brand-500/[0.06] disabled:cursor-not-allowed disabled:opacity-60 dark:text-brand-300"
          >
            {isSending ? <Loader2 size={16} className="animate-spin" /> : <RefreshCw size={16} />}
            {isSending ? 'Sending...' : 'Resend verification email'}
          </button>
        </div>
      </div>

      <div className="mt-8 text-center">
        <Link to="/login" className="text-sm font-semibold text-slate-500 transition-colors hover:text-navy-900 dark:text-slate-400 dark:hover:text-white">
          Back to login
        </Link>
      </div>
    </AuthLayout>
  );
}

import React, { useState, useEffect } from 'react';
import { useMeetingStore, Meeting } from '../../store/meetingStore';
import { useTeamStore } from '../../store/teamStore';
import { X, Copy, Check } from 'lucide-react';
import api from '../../utils/api';

interface Props {
  meeting: Meeting;
  onClose: () => void;
}

const MeetingInviteModal: React.FC<Props> = ({ meeting, onClose }) => {
  const { currentTeam } = useTeamStore();
  const { inviteMember } = useMeetingStore();
  const [members, setMembers] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [copied, setCopied] = useState(false);

  useEffect(() => {
    const fetchMembers = async () => {
      if (!currentTeam) return;
      try {
        const { data } = await api.get(`/teams/${currentTeam._id}/members`);
        setMembers(data.members || []);
      } catch (e) {
        console.error(e);
      } finally {
        setLoading(false);
      }
    };
    fetchMembers();
  }, [currentTeam]);

  const handleInvite = async (userId: string) => {
    try {
      await inviteMember(meeting._id, userId);
    } catch (e) {
      console.error(e);
    }
  };

  const inviteLink = `${window.location.origin}/team/${meeting.teamId}/meetings/${meeting._id}`;

  const copyLink = () => {
    navigator.clipboard.writeText(inviteLink);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="modal-overlay">
      <div className="modal max-w-md flex flex-col max-h-[80vh]">
        <div className="modal-header">
          <h2 className="text-lg font-semibold" style={{ color: 'var(--color-foreground)' }}>Invite to {meeting.title}</h2>
          <button onClick={onClose} className="p-1 rounded-lg" style={{ color: 'var(--color-muted)' }}>
            <X size={20} />
          </button>
        </div>
        
        <div className="p-4 border-b" style={{ borderColor: 'var(--color-border-light)' }}>
          <label className="block text-sm font-medium mb-2" style={{ color: 'var(--color-foreground)' }}>Share Link</label>
          <div className="flex items-center gap-2">
            <input
              readOnly
              value={inviteLink}
              className="input flex-1"
            />
            <button
              onClick={copyLink}
              className="btn btn-secondary p-2"
            >
              {copied ? <Check size={18} style={{ color: 'var(--color-success)' }} /> : <Copy size={18} />}
            </button>
          </div>
        </div>

        <div className="modal-body flex-1 overflow-y-auto">
          <label className="block text-sm font-medium mb-3" style={{ color: 'var(--color-foreground)' }}>Invite Team Members</label>
          {loading ? (
            <p className="text-sm" style={{ color: 'var(--color-muted)' }}>Loading members...</p>
          ) : (
            <div className="space-y-3">
              {members.map(member => (
                <div key={member.user._id} className="flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <div className="avatar avatar-sm" style={{ background: 'var(--color-accent-light)', color: 'var(--color-accent)' }}>
                      {member.user.name.charAt(0)}
                    </div>
                    <div>
                      <p className="text-sm font-medium" style={{ color: 'var(--color-foreground)' }}>{member.user.name}</p>
                      <p className="text-xs" style={{ color: 'var(--color-muted)' }}>{member.user.email}</p>
                    </div>
                  </div>
                  <button
                    onClick={() => handleInvite(member.user._id)}
                    className="btn btn-sm" style={{ background: 'var(--color-accent-light)', color: 'var(--color-accent)' }}
                  >
                    Invite
                  </button>
                </div>
              ))}
              {members.length === 0 && (
                <p className="text-sm" style={{ color: 'var(--color-muted)' }}>No other team members found.</p>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default MeetingInviteModal;

import React, { useState, useEffect, useCallback } from 'react';
import io from 'socket.io-client';

import { useAuthStore } from '../../store/authStore';
import { Send, Users, FileText, MessageSquare } from 'lucide-react';

interface Props {
  meetingId: string;
}

const MeetingNotes: React.FC<Props> = ({ meetingId }) => {
  const [content, setContent] = useState('');
  const [socket, setSocket] = useState<any>(null);
  const [activeTab, setActiveTab] = useState<'notes' | 'chat' | 'presence'>('notes');
  const [chatMessages, setChatMessages] = useState<any[]>([]);
  const [newMessage, setNewMessage] = useState('');
  const [presence, setPresence] = useState<string[]>([]);
  const user = useAuthStore(s => s.user);

  useEffect(() => {
    const newSocket = io(import.meta.env.VITE_API_URL || 'http://localhost:5000', {
      withCredentials: true,
    });
    
    setSocket(newSocket);
    
    newSocket.emit('meeting_join', { meetingId, userId: user?.id });
    
    newSocket.on('meeting_notes_updated', (data: { content: string }) => {
      setContent(data.content);
    });

    newSocket.on('meeting_chat_received', (chat: any) => {
      setChatMessages(prev => [...prev, chat]);
    });

    newSocket.on('meeting_presence_update', (userIds: string[]) => {
      setPresence(userIds);
    });

    return () => {
      newSocket.emit('meeting_leave', { meetingId, userId: user?.id });
      newSocket.disconnect();
    };
  }, [meetingId, user]);

  const handleChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const newContent = e.target.value;
    setContent(newContent);
    if (socket) {
      socket.emit('meeting_notes_update', { meetingId, content: newContent });
    }
  };

  const sendChatMessage = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newMessage.trim() || !socket) return;
    
    socket.emit('meeting_chat', { meetingId, senderId: user?.id, message: newMessage });
    setNewMessage('');
  };

  return (
    <div className="flex flex-col h-full border-l border-gray-200 dark:border-gray-800 bg-white dark:bg-dark-bg">
      <div className="flex border-b border-gray-200 dark:border-gray-800 bg-gray-50 dark:bg-gray-900">
        <button
          onClick={() => setActiveTab('notes')}
          className={`flex-1 py-3 text-sm font-semibold flex items-center justify-center gap-2 ${activeTab === 'notes' ? 'text-primary-600 border-b-2 border-primary-600' : 'text-gray-500 hover:text-gray-700 dark:hover:text-gray-300'}`}
        >
          <FileText size={16} /> Notes
        </button>
        <button
          onClick={() => setActiveTab('chat')}
          className={`flex-1 py-3 text-sm font-semibold flex items-center justify-center gap-2 ${activeTab === 'chat' ? 'text-primary-600 border-b-2 border-primary-600' : 'text-gray-500 hover:text-gray-700 dark:hover:text-gray-300'}`}
        >
          <MessageSquare size={16} /> Chat
        </button>
        <button
          onClick={() => setActiveTab('presence')}
          className={`flex-1 py-3 text-sm font-semibold flex items-center justify-center gap-2 ${activeTab === 'presence' ? 'text-primary-600 border-b-2 border-primary-600' : 'text-gray-500 hover:text-gray-700 dark:hover:text-gray-300'}`}
        >
          <Users size={16} /> Users ({presence.length})
        </button>
      </div>

      {activeTab === 'notes' && (
        <div className="flex-1 p-0 flex flex-col">
          <textarea
            value={content}
            onChange={handleChange}
            placeholder="Type meeting notes here... (Markdown supported)"
            className="w-full h-full p-4 resize-none bg-transparent text-gray-800 dark:text-gray-200 border-none focus:ring-0 outline-none placeholder-gray-400"
          />
        </div>
      )}

      {activeTab === 'chat' && (
        <div className="flex-1 flex flex-col min-h-0">
          <div className="flex-1 overflow-y-auto p-4 space-y-4">
            {chatMessages.map((msg, idx) => (
              <div key={idx} className={`flex flex-col ${msg.senderId === user?.id ? 'items-end' : 'items-start'}`}>
                <div className={`px-4 py-2 rounded-2xl max-w-[85%] ${msg.senderId === user?.id ? 'bg-primary-600 text-white rounded-br-none' : 'bg-gray-100 dark:bg-gray-800 text-gray-900 dark:text-gray-100 rounded-bl-none'}`}>
                  {msg.message}
                </div>
              </div>
            ))}
            {chatMessages.length === 0 && (
              <div className="text-center text-gray-500 mt-10">No messages yet. Start chatting!</div>
            )}
          </div>
          <form onSubmit={sendChatMessage} className="p-3 border-t border-gray-200 dark:border-gray-800 flex gap-2">
            <input
              type="text"
              value={newMessage}
              onChange={e => setNewMessage(e.target.value)}
              placeholder="Type a message..."
              className="flex-1 px-3 py-2 border border-gray-300 dark:border-gray-700 rounded-lg bg-gray-50 dark:bg-gray-900 text-gray-900 dark:text-white"
            />
            <button type="submit" className="p-2 bg-primary-600 text-white rounded-lg hover:bg-primary-700 transition-colors">
              <Send size={18} />
            </button>
          </form>
        </div>
      )}

      {activeTab === 'presence' && (
        <div className="flex-1 overflow-y-auto p-4 space-y-3">
          {presence.map(userId => (
            <div key={userId} className="flex items-center gap-3">
              <div className="w-8 h-8 rounded-full bg-green-100 text-green-700 flex items-center justify-center font-bold text-xs relative">
                {userId.charAt(0).toUpperCase()}
                <span className="absolute bottom-0 right-0 w-2.5 h-2.5 bg-green-500 border-2 border-white dark:border-gray-900 rounded-full"></span>
              </div>
              <span className="text-sm font-medium text-gray-900 dark:text-white">User {userId.substring(0, 4)}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default MeetingNotes;

import React, { useEffect, useState } from 'react';
import {
  LiveKitRoom,
  VideoConference,
