            audio={true}
            token={activeToken}
            serverUrl={serverUrl}
            onDisconnected={handleDisconnected}
            data-lk-theme="default"
            className="h-full w-full custom-lk-room"
          >
            <VideoConference />
            <RoomAudioRenderer />
