import React, { useState, useEffect } from 'react';
import { X, Users } from 'lucide-react';
import { useTeamStore } from '../../store/teamStore';
import { useAuthStore } from '../../store/authStore';

interface MeetingModalProps {
  isOpen: boolean;
  onClose: () => void;
  type: 'Instant' | 'Scheduled';
  onSubmit: (payload: any) => void;
  isCreating: boolean;
  teamId: string;
}

export default function MeetingModal({ isOpen, onClose, type, onSubmit, isCreating, teamId }: MeetingModalProps) {
  const [title, setTitle] = useState('');
  const [startTime, setStartTime] = useState('');
  const [duration, setDuration] = useState(30);
  const [selectedParticipants, setSelectedParticipants] = useState<string[]>([]);

  const { members, getMembers } = useTeamStore();
  const currentUser = useAuthStore(s => s.user);

  useEffect(() => {
    if (isOpen && teamId) {
      getMembers(teamId);
    }
  }, [isOpen, teamId]);

  useEffect(() => {
    if (isOpen) {
      setTitle(type === 'Instant' ? 'Instant Meet' : 'Scheduled Meet');
      const now = new Date();
      now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
      setStartTime(now.toISOString().slice(0, 16));
      setSelectedParticipants([]);
      setDuration(30);
    }
  }, [isOpen, type]);

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSubmit({
      title,
      startTime: type === 'Instant' ? new Date().toISOString() : new Date(startTime).toISOString(),
      duration,
      meetingType: type,
      participants: selectedParticipants
    });
  };

  const toggleParticipant = (userId: string) => {
    setSelectedParticipants(prev => 
      prev.includes(userId) ? prev.filter(id => id !== userId) : [...prev, userId]
    );
  };

  // Filter out current user from members to invite
  const inviteableMembers = members.filter(m => m.userId._id !== currentUser?.id);

  return (
    <div className="modal-overlay">
      <div className="modal max-w-md w-full bg-surface text-foreground shadow-float" style={{ background: 'var(--color-surface)' }}>
        <div className="modal-header border-b border-border p-4 flex justify-between items-center">
          <h2 className="text-xl font-semibold">
            {type === 'Instant' ? 'Start Instant Meeting' : 'Schedule Meeting'}
          </h2>
          <button onClick={onClose} className="p-1 hover:bg-gray-100 dark:hover:bg-gray-800 rounded">
            <X size={20} />
          </button>
        </div>

        <form onSubmit={handleSubmit}>
          <div className="modal-body p-4 space-y-4">
            <div>
              <label className="block text-sm font-medium mb-1">Meeting Title</label>
              <input
                required
                type="text"
                className="input-field"
                value={title}
                onChange={(e) => setTitle(e.target.value)}
                placeholder="Enter meeting title"
              />
            </div>

            {type === 'Scheduled' && (
              <>
                <div>
                  <label className="block text-sm font-medium mb-1">Start Time</label>
                  <input
                    required
                    type="datetime-local"
                    className="input-field"
                    value={startTime}
                    onChange={(e) => setStartTime(e.target.value)}
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium mb-1">Duration (minutes)</label>
                  <input
                    required
                    type="number"
                    min="15"
                    step="15"
                    className="input-field"
                    value={duration}
                    onChange={(e) => setDuration(parseInt(e.target.value))}
                  />
                </div>
              </>
            )}

            <div>
              <label className="block text-sm font-medium mb-2 flex items-center gap-2">
                <Users size={16} /> Invite Team Members
              </label>
              <div className="max-h-40 overflow-y-auto border border-border rounded-lg p-2 space-y-1" style={{ borderColor: 'var(--color-border)' }}>
                {inviteableMembers.length === 0 ? (
                  <p className="text-sm text-gray-500 text-center py-2">No other team members found.</p>
                ) : (
                  inviteableMembers.map(member => (
                    <label key={member.userId._id} className="flex items-center gap-3 p-2 hover:bg-gray-100 dark:hover:bg-gray-800 rounded cursor-pointer transition-colors">
                      <input
                        type="checkbox"
                        checked={selectedParticipants.includes(member.userId._id)}
                        onChange={() => toggleParticipant(member.userId._id)}
                        className="rounded border-gray-300 text-blue-600 focus:ring-blue-600 w-4 h-4"
                      />
                      <div className="flex items-center gap-2 flex-1">
                        {member.userId.avatarUrl ? (
                          <img src={member.userId.avatarUrl} alt={member.userId.name} className="w-6 h-6 rounded-full object-cover" />
                        ) : (
                          <div className="w-6 h-6 rounded-full bg-blue-100 text-blue-600 flex items-center justify-center text-xs font-medium">
                            {member.userId.name?.charAt(0).toUpperCase() || 'U'}
                          </div>
                        )}
                        <span className="text-sm font-medium truncate">{member.userId.name}</span>
                      </div>
                    </label>
                  ))
                )}
              </div>
            </div>
          </div>

          <div className="modal-footer border-t border-border p-4 flex justify-end gap-3">
            <button type="button" onClick={onClose} className="btn btn-secondary">Cancel</button>
            <button type="submit" disabled={isCreating} className="btn btn-primary">
              {isCreating ? 'Processing...' : (type === 'Instant' ? 'Start Now' : 'Schedule')}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useWorkspaceStore } from '../../store/workspaceStore';
import { useTamadMeetStore } from '../../store/tamadMeetStore';
import { Video, Plus, Calendar, Settings, Play } from 'lucide-react';
import toast from 'react-hot-toast';
import MeetingModal from './MeetingModal';

export default function TamadMeetDashboard() {
  const currentWorkspace = useWorkspaceStore(s => s.currentWorkspace);
  const { meetings, loading, fetchMeetings, createMeeting, joinRoom } = useTamadMeetStore();
  const navigate = useNavigate();
  const [isCreating, setIsCreating] = useState(false);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [modalType, setModalType] = useState<'Instant' | 'Scheduled'>('Instant');

  useEffect(() => {
    if (currentWorkspace?.teamId) {
      fetchMeetings(currentWorkspace.teamId);
    }
  }, [currentWorkspace]);

  const handleOpenModal = (type: 'Instant' | 'Scheduled') => {
    setModalType(type);
    setIsModalOpen(true);
  };

  const handleMeetingSubmit = async (payload: any) => {
    if (!currentWorkspace?.teamId) return;
    setIsCreating(true);
    try {
      const meeting = await createMeeting({
        ...payload,
        teamId: currentWorkspace.teamId,
        workspaceId: currentWorkspace._id,
      });
      
      toast.success(payload.meetingType === 'Instant' ? 'Meeting started!' : 'Meeting scheduled!');
      setIsModalOpen(false);
      fetchMeetings(currentWorkspace.teamId);
      
      if (payload.meetingType === 'Instant') {
        navigate(`/team/tamad-meet/room/${meeting._id}`);
      }
    } catch (err) {
      console.error(err);
    } finally {
      setIsCreating(false);
    }
  };

  return (
    <div className="page flex h-full flex-col p-6">
      <header className="mb-8 flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold" style={{ color: 'var(--color-foreground)' }}>TaMaD Meet Dashboard</h1>
          <p className="mt-1 text-sm" style={{ color: 'var(--color-muted)' }}>Enterprise WebRTC Communications</p>
        </div>
        <div className="flex gap-3">
          <button onClick={() => handleOpenModal('Instant')} disabled={isCreating} className="btn btn-primary flex items-center gap-2">
            <Video size={16} /> Instant Meet
          </button>
          <button onClick={() => handleOpenModal('Scheduled')} className="btn btn-secondary flex items-center gap-2">
            <Plus size={16} /> Schedule
          </button>
        </div>
      </header>
      
      <div className="flex-1 overflow-auto">
        {loading ? (
          <p>Loading...</p>
        ) : (
          <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
            {meetings.map((m: any) => (
              <div key={m._id} className="card p-4 rounded-xl border" style={{ background: 'var(--color-surface)', borderColor: 'var(--color-border)' }}>
                <h3 className="font-semibold text-lg">{m.title}</h3>
                <p className="text-sm mt-2" style={{ color: 'var(--color-muted)' }}>{new Date(m.startTime).toLocaleString()}</p>
                <div className="mt-4 flex justify-between">
                  <span className="text-xs px-2 py-1 rounded-full bg-blue-100 text-blue-800">{m.status}</span>
                  <button className="btn btn-primary btn-sm flex items-center gap-1" onClick={() => navigate(`/team/tamad-meet/room/${m._id}`)}>
                    <Play size={14} /> Join Room
                  </button>
                </div>
              </div>
            ))}
            {meetings.length === 0 && (
              <p style={{ color: 'var(--color-muted)' }}>No meetings scheduled.</p>
            )}
          </div>
        )}
      </div>
      
      <MeetingModal
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        type={modalType}
        onSubmit={handleMeetingSubmit}
        isCreating={isCreating}
        teamId={currentWorkspace?.teamId || ''}
      />
    </div>
  );
}

import { useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useAuthStore } from '../../../store/authStore';
import { useTamadMeetStore } from '../../../store/tamadMeetStore';
import { useWebRTC } from '../../../hooks/useWebRTC';
import { Video, Mic, VideoOff, MicOff, PhoneOff, MonitorUp } from 'lucide-react';

export default function TamadMeetRoom() {
  const { roomId } = useParams();
  const navigate = useNavigate();
  const user = useAuthStore(s => s.user);
  const { currentRoom, currentParticipant, joinRoom, leaveRoom } = useTamadMeetStore();
  const { 
    localStream, 
    remoteStreams, 
    startLocalStream, 
    stopLocalStream,
    toggleAudio,
    toggleVideo,
    toggleScreenShare,
    isAudioEnabled,
    isVideoEnabled,
    isScreenSharing
  } = useWebRTC(roomId, currentParticipant?._id);

  useEffect(() => {
    if (roomId) {
      joinRoom(roomId).catch(() => navigate('/team/tamad-meet'));
    }
    return () => leaveRoom();
  }, [roomId]);

  useEffect(() => {
    if (currentRoom && currentParticipant) {
      startLocalStream();
    }
    return () => stopLocalStream();
  }, [currentRoom, currentParticipant]);

  if (!currentRoom) return <div className="p-8">Joining room...</div>;

  return (
    <div className="flex h-screen bg-black text-white flex-col">
      <header className="p-4 border-b border-gray-800 flex justify-between items-center">
        <h1 className="font-bold">TaMaD Meet: Room {roomId}</h1>
      </header>
      
      <main className="flex-1 overflow-auto p-4 flex gap-4 flex-wrap justify-center items-center">
        {/* Local Video */}
        {localStream && (
          <div className="relative w-[320px] h-[240px] bg-gray-900 rounded-xl overflow-hidden border border-gray-700">
            <video 
              autoPlay 
              muted 
              playsInline 
              className="w-full h-full object-cover"
              ref={el => { if (el) el.srcObject = localStream }} 
            />
            <div className="absolute bottom-2 left-2 bg-black/60 px-2 py-1 rounded text-xs">{user?.name} (You)</div>
          </div>
        )}

        {/* Remote Videos */}
        {Object.entries(remoteStreams).map(([id, stream]) => (
          <div key={id} className="relative w-[320px] h-[240px] bg-gray-900 rounded-xl overflow-hidden border border-gray-700">
            <video 
              autoPlay 
              playsInline 
              className="w-full h-full object-cover"
              ref={el => { if (el) el.srcObject = stream }} 
            />
            <div className="absolute bottom-2 left-2 bg-black/60 px-2 py-1 rounded text-xs">Participant</div>
          </div>
        ))}
      </main>

      <footer className="p-4 border-t border-gray-800 flex justify-center gap-4">
        <button 
          onClick={toggleAudio}
          className={`p-3 rounded-full hover:bg-gray-700 ${isAudioEnabled ? 'bg-gray-800' : 'bg-red-600 hover:bg-red-700'}`}
        >
          {isAudioEnabled ? <Mic size={20} /> : <MicOff size={20} />}
        </button>
        <button 
          onClick={toggleVideo}
          className={`p-3 rounded-full hover:bg-gray-700 ${isVideoEnabled ? 'bg-gray-800' : 'bg-red-600 hover:bg-red-700'}`}
        >
          {isVideoEnabled ? <Video size={20} /> : <VideoOff size={20} />}
        </button>
        <button 
          onClick={toggleScreenShare}
          className={`p-3 rounded-full hover:bg-gray-700 ${isScreenSharing ? 'bg-blue-600 hover:bg-blue-700' : 'bg-gray-800'}`}
        >
          <MonitorUp size={20} />
        </button>
        <button onClick={() => navigate('/team/tamad-meet')} className="p-3 rounded-full bg-red-600 hover:bg-red-700"><PhoneOff size={20} /></button>
      </footer>
    </div>
  );
}

