import React, { createContext, useContext, useEffect, useState, useCallback, useRef } from 'react';
import { io, Socket } from 'socket.io-client';
import { useAuthStore } from '../store/authStore';
import { useTaskStore } from '../store/taskStore';
import { useNotifStore } from '../store/notifStore';
import api from '../utils/api';

interface RealtimeContextType {
  socket: Socket | null;
  isConnected: boolean;
  onlineUsers: string[];
  requestNotificationPermission: () => Promise<NotificationPermission>;
}

const RealtimeContext = createContext<RealtimeContextType>({
  socket: null,
  isConnected: false,
  onlineUsers: [],
  requestNotificationPermission: async () => 'default',
});

export const useRealtime = () => useContext(RealtimeContext);

export const RealtimeProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const user = useAuthStore(s => s.user);
  const workspace = useAuthStore(s => s.workspace);
  const fetchTasks = useTaskStore(s => s.fetchTasks);
  const addRealtime = useNotifStore(s => s.addRealtime);
  const fetchNotifications = useNotifStore(s => s.fetchNotifications);
  const [socket, setSocket] = useState<Socket | null>(null);
  const [isConnected, setIsConnected] = useState(false);
  const [onlineUsers, setOnlineUsers] = useState<string[]>([]);
  const socketRef = useRef<Socket | null>(null);
  const reconnectAttempts = useRef(0);
  const maxReconnectAttempts = 5;

  const workspaceId = workspace?._id;

  const requestNotificationPermission = useCallback(async (): Promise<NotificationPermission> => {
    if (!('Notification' in window)) return 'denied';
    if (Notification.permission === 'granted') return 'granted';
    if (Notification.permission === 'denied') return 'denied';
    return await Notification.requestPermission();
  }, []);

  const getAuthToken = useCallback(async (): Promise<string | null> => {
    try {
      const { data } = await api.get('/auth/me');
      return data.user?.id || null;
    } catch {
      return null;
    }
  }, []);

  useEffect(() => {
    if (!user || !workspaceId) return;

    const SOCKET_URL = import.meta.env.VITE_API_URL
      ? import.meta.env.VITE_API_URL.replace('/api', '')
      : 'http://localhost:5000';

    const connectSocket = async () => {
      const token = await getAuthToken();
      
      const newSocket = io(SOCKET_URL, {
        auth: { token },
        withCredentials: true,
        reconnection: true,
        reconnectionAttempts: maxReconnectAttempts,
        reconnectionDelay: 1000,
        reconnectionDelayMax: 5000,
      });

      newSocket.on('connect', () => {
        setIsConnected(true);
        reconnectAttempts.current = 0;
        newSocket.emit('join_workspace', workspaceId);
        fetchNotifications();
      });

      newSocket.on('disconnect', (reason) => {
        setIsConnected(false);
        if (reason === 'io server disconnect') {
          newSocket.connect();
        }
      });

      newSocket.on('connect_error', async (error) => {
        console.error('Socket connection error:', error.message);
        reconnectAttempts.current++;
        
        if (reconnectAttempts.current >= maxReconnectAttempts) {
          const newToken = await getAuthToken();
          if (newToken) {
            newSocket.auth = { token: newToken };
            newSocket.connect();
            reconnectAttempts.current = 0;
          }
        }
      });

      newSocket.on('reconnect', () => {
        setIsConnected(true);
        newSocket.emit('join_workspace', workspaceId);
        fetchNotifications();
      });

      newSocket.on('task_created', () => fetchTasks(workspaceId));
      newSocket.on('task_updated', () => fetchTasks(workspaceId));
      newSocket.on('task_deleted', () => fetchTasks(workspaceId));
      newSocket.on('tasks_bulk_updated', () => fetchTasks(workspaceId));
      newSocket.on('tasks_bulk_deleted', () => fetchTasks(workspaceId));

      newSocket.on('notification_created', (data: any) => {
        addRealtime(data);
      });

      newSocket.on('notification_updated', (data: any) => {
        fetchNotifications();
      });

      newSocket.on('notification_deleted', () => {
        fetchNotifications();
      });

      newSocket.on('notification_read_all', () => {
        fetchNotifications();
      });

      newSocket.on('presence_update', (data: { workspaceId: string; users: string[] }) => {
        if (data.workspaceId === workspaceId) {
          setOnlineUsers(data.users);
        }
      });

      newSocket.on('task_assigned', (data: { taskId: string; taskTitle: string; assignedBy: string }) => {
        addRealtime({
          title: 'Task Assigned',
          body: `You have been assigned to "${data.taskTitle}"`,
          type: 'task_assigned',
          entityId: data.taskId,
          entityType: 'task',
        });
      });

      socketRef.current = newSocket;
      setSocket(newSocket);
    };

    connectSocket();

    return () => {
      if (socketRef.current) {
        socketRef.current.close();
        socketRef.current = null;
      }
    };
  }, [user, workspaceId, fetchTasks, addRealtime, fetchNotifications, getAuthToken]);

  return (
    <RealtimeContext.Provider value={{ socket, isConnected, onlineUsers, requestNotificationPermission }}>
      {children}
    </RealtimeContext.Provider>
  );
};

import { initializeApp, getApps, FirebaseApp } from 'firebase/app';
import {
  getAuth,
  Auth,
  GoogleAuthProvider,
  RecaptchaVerifier,
  browserLocalPersistence,
  browserSessionPersistence,
  createUserWithEmailAndPassword,
  sendEmailVerification,
  sendPasswordResetEmail,
  setPersistence,
  signInWithEmailAndPassword,
  signInWithPhoneNumber,
  signInWithPopup,
  updateProfile,
  confirmPasswordReset,
  signOut,
  onAuthStateChanged,
  User as FirebaseUser,
} from 'firebase/auth';
import {
  getStorage,
  FirebaseStorage,
  ref,
  uploadBytesResumable,
  getDownloadURL,
  deleteObject,
} from 'firebase/storage';

const firebaseConfig = {
  apiKey: import.meta.env.VITE_FIREBASE_API_KEY,
  authDomain: import.meta.env.VITE_FIREBASE_AUTH_DOMAIN,
  projectId: import.meta.env.VITE_FIREBASE_PROJECT_ID,
  storageBucket: import.meta.env.VITE_FIREBASE_STORAGE_BUCKET,
  messagingSenderId: import.meta.env.VITE_FIREBASE_MESSAGING_SENDER_ID,
  appId: import.meta.env.VITE_FIREBASE_APP_ID,
};

function validateConfig() {
  const missing = Object.entries(firebaseConfig)
    .filter(([, v]) => !v)
    .map(([k]) => k);
  if (missing.length > 0) {
    throw new Error(
      `Missing Firebase config: ${missing.join(', ')}. ` +
      'Add VITE_FIREBASE_* environment variables to your .env.local file.'
    );
  }
}

let app: FirebaseApp;
let auth: Auth;
let storage: FirebaseStorage;

try {
  validateConfig();
  app = getApps().length > 0 ? getApps()[0] : initializeApp(firebaseConfig);
  auth = getAuth(app);
  storage = getStorage(app);
} catch (error) {
  console.error('Firebase initialization error:', error);
  throw error;
}

export { app, auth, storage };

// ---- Auth helpers ----

export const getClientAuth = (): Auth => auth;

export const onAuthChange = (callback: (user: FirebaseUser | null) => void) =>
  onAuthStateChanged(auth, callback);

const setSessionPersistence = (rememberMe: boolean) =>
  setPersistence(auth, rememberMe ? browserLocalPersistence : browserSessionPersistence);

export const signInWithGoogle = async (rememberMe: boolean) => {
  await setSessionPersistence(rememberMe);
  return signInWithPopup(auth, new GoogleAuthProvider());
};

export const signInWithEmail = async (email: string, password: string, rememberMe: boolean) => {
  await setSessionPersistence(rememberMe);
  return signInWithEmailAndPassword(auth, email, password);
};

export const registerWithEmail = async (name: string, email: string, password: string) => {
  await setSessionPersistence(false);
  const credential = await createUserWithEmailAndPassword(auth, email, password);
  await updateProfile(credential.user, { displayName: name });
  await sendEmailVerification(credential.user);
  return credential;
};

export const sendResetEmail = (email: string) =>
  sendPasswordResetEmail(auth, email);

export const resetFirebasePassword = (code: string, password: string) =>
  confirmPasswordReset(auth, code, password);

export const resendVerificationEmail = async () => {
  if (!auth.currentUser) throw new Error('Please sign in again to verify your email');
  await sendEmailVerification(auth.currentUser);
};

export const createPhoneRecaptcha = (container: HTMLElement) =>
  new RecaptchaVerifier(auth, container, { size: 'normal' });

export const startPhoneSignIn = (phoneNumber: string, verifier: RecaptchaVerifier) =>
  signInWithPhoneNumber(auth, phoneNumber, verifier);

export const signOutFromFirebase = () => signOut(auth);

export const getCurrentFirebaseUser = () => auth.currentUser;

export const refreshFirebaseUser = async () => {
  if (auth.currentUser) {
    await auth.currentUser.getIdToken(true);
  }
};

