    try {
      await api.delete(`/documents/${id}`);
      set(s => ({
        documents: s.documents.filter(d => d._id !== id),
        currentDocument: s.currentDocument?._id === id ? null : s.currentDocument,
      }));
      toast.success('Document deleted');
    } catch {
      toast.error('Failed to delete document');
    }
  },

